window.BRIG_CONTENT = {"version": "2026-09-29-1313", "items": [{"i": "D1.1-L1-a", "c": "D1.1", "l": 1, "f": "a", "cl": "I can spot when an everyday tool is using AI.", "s": "Which of these everyday features is most likely powered by AI?", "o": ["A photo app that automatically groups pictures of the same person's face", "A spreadsheet that automatically calculates the total sum of a column", "A digital clock that automatically shifts its time for daylight saving", "A text editor that automatically flags words that match a dictionary"], "k": 0, "w": "Recognizing human faces relies on identifying complex visual patterns in data. Distractors represent standard rule-based software automation that follows simple fixed instructions rather than learning from data patterns."}, {"i": "D1.1-L1-b", "c": "D1.1", "l": 1, "f": "b", "cl": "I can explain in plain words what generative AI does.", "s": "A friend asks how a chatbot decides which words to use in a reply. What is the most accurate description?", "o": ["It looks up the absolute correct response in a built-in encyclopedia.", "It searches online to find matching answers written by human experts.", "It predicts likely next words from patterns in text it was trained on.", "It follows fixed grammar rules to construct entirely new logical facts."], "k": 2, "w": "Chatbots build responses word by word based on mathematical probability and training patterns. Distractors show common misconceptions that the system uses true logical reasoning or queries databases like search engines."}, {"i": "D1.1-L1-c", "c": "D1.1", "l": 1, "f": "c", "cl": "I can spot the difference between an AI-driven tool and a static algorithm.", "s": "Which everyday feature most likely uses AI rather than a fixed rule?", "o": ["A calculator that converts currency using the official rate today", "A web browser that blocks websites from tracking your online habits", "A keyboard that suggests your next word from how you usually write", "A media player that shuffles your music track list in random order"], "k": 2, "w": "The keyboard dynamically adapts to individual user behavior, which requires learning from data patterns. The remaining options rely on fixed algorithms, simple randomization, or straightforward external lookup tables."}, {"i": "D1.1-L2-a", "c": "D1.1", "l": 2, "f": "a", "cl": "I can tell generative, predictive and rule-based AI apart.", "s": "A banking system flags a transaction as unusual. How does it indicate that it uses predictive AI rather than a compliance rule?", "o": ["Because it follows a list of banned countries, it blocks specific international accounts.", "Because it catches transfers that exceed a fixed dollar limit, it flags big amounts.", "Because it triggers whenever an account is accessed at night, it pauses card access.", "Because it learns your normal spending pattern, it flags anything that deviates."], "k": 3, "w": "Predictive AI analyzes historical behavior to evaluate probability and detect anomalies. Distractors illustrate rule-based systems that rely on strict if-then thresholds, which do not learn or adapt over time."}, {"i": "D1.1-L2-b", "c": "D1.1", "l": 2, "f": "b", "cl": "I can explain in plain words what a predictive model does.", "s": "A weather app projects a 70% chance of rain tomorrow. In plain terms, how does this predictive model calculate this?", "o": ["By asking a chatbot to summarize what current meteorologists say online", "By running a fixed rule that triggers rain whenever humidity hits 80%", "By finding patterns in past weather data, it estimates how likely rain is.", "By searching for identical dates in history to see if it rained before"], "k": 2, "w": "Predictive models use statistical patterns in historical data to estimate the likelihood of future events. Distractors confuse prediction with simple threshold logic, internet searches, or strict historical repetition."}, {"i": "D1.1-L2-c", "c": "D1.1", "l": 2, "f": "c", "cl": "I know AI models have a knowledge cut-off and can make things up.", "s": "An AI tool confidently names the winner of a game played yesterday. Why should you treat this response with skepticism?", "o": ["Because it avoids answering when it lacks facts, it must be guessing blindly.", "Because it relies on outdated internet searches, it mixes up older matches.", "Because it changes its sources dynamically, it reports different scores each hour.", "Because it lacks live data past its training cut-off, it can invent a convincing answer."], "k": 3, "w": "Models facing a knowledge cut-off often hallucinate plausible-sounding information instead of admitting ignorance. Distractors reflect the incorrect beliefs that tools always refuse to answer or search live websites poorly."}, {"i": "D1.1-L3-a", "c": "D1.1", "l": 3, "f": "a", "cl": "I can match the right kind of AI to a problem.", "s": "You need a system that outputs an identical, standardized message for a customer query every time. Which choice is best?", "o": ["A simple conditional script delivers 100% deterministic text consistency, whereas a generative model introduces random phrasing variations.", "A generative chatbot guarantees identical responses across different users, whereas a static script creates unpredictable sentence structures.", "A predictive classification tool ensures tone matching across all responses, whereas a template engine requires constant manual rewriting.", "A deep learning model prevents formatting errors during heavy traffic, whereas a basic script crashes under high volume."], "k": 0, "w": "Simple rule-based systems are deterministic and guarantee consistency, making them superior to generative AI for rigid compliance tasks. Distractors misstate chatbot capabilities or invent fake advantages for deep learning models."}, {"i": "D1.1-L3-b", "c": "D1.1", "l": 3, "f": "b", "cl": "I can explain why two AI tools behave differently.", "s": "A generative chatbot uses diverse phrasing, while a spam filter delivers a consistent Yes or No classification. What explains this difference?", "o": ["The chatbot operates without any built-in mathematical limits, whereas the filter follows rigid laws.", "The chatbot searches the live internet for inspiration, whereas the filter uses internal statistics.", "The chatbot relies on human supervisors for adjustments, whereas the filter operates completely alone.", "The chatbot selects from many possible word combinations, whereas the filter is designed to make a single, fixed choice."], "k": 3, "w": "Generative models predict probabilities across thousands of tokens, while classification models evaluate inputs to select a single categorical label. Distractors represent common misconceptions regarding internet access and human supervision."}, {"i": "D1.1-L3-c", "c": "D1.1", "l": 3, "f": "c", "cl": "I can tell when a task needs AI at all, or when a simple rule is better.", "s": "You want to sort a long list of company expenses from highest to lowest. Is AI the right tool for this task?", "o": ["Because a standard sorting rule accomplishes this perfectly, using AI would be unnecessary overkill.", "Because AI handles large numbers faster than standard code, it saves valuable processing time.", "Because a spreadsheet might make arithmetic mistakes, AI ensures the final sequence is accurate.", "Because ordering values requires understanding financial context, AI prevents classification errors."], "k": 0, "w": "Standard sorting algorithms are fast, exact, and require no training, making AI unnecessary. Distractors show mistaken beliefs that AI is faster at math or more accurate than traditional sorting rules."}, {"i": "D1.1-L4-a", "c": "D1.1", "l": 4, "f": "a", "cl": "I can reason about an AI tool's limits when setting it up for others.", "s": "You deploy an AI tool to summarize multi-page documents, but the model has a very small context window. What is the main constraint?", "o": ["When the window is too small, the tool runs out of storage and crashes during the process.", "When the window is too small, the tool requires human validation for every single sentence.", "When the window is too small, the tool reads only the first part and cuts off the rest.", "When the window is too small, the tool switches to a public database and leaks corporate secrets."], "k": 2, "w": "The context window limits how much text a model can process at one time, causing it to ignore text beyond that limit. Distractors mistake this memory limit for data leaks, crashes, or workflow interruptions."}, {"i": "D1.1-L4-b", "c": "D1.1", "l": 4, "f": "b", "cl": "I can choose and justify the right type of AI for someone else's need.", "s": "A relative wants an AI application to identify bird species from their smartphone photos. Which capability decides if a tool can do this?", "o": ["Because the task requires real-time results, the tool must connect directly to global positioning satellites.", "Because the task needs photos, the tool must accept image input, not only text.", "Because the task involves wildlife data, the tool must hold an official academic biology certification.", "Because the task uses mobile hardware, the tool must run completely without an internet network."], "k": 1, "w": "Identifying visual subjects like birds requires multimodal inputs or computer vision. Distractors emphasize irrelevant requirements like cellular satellite tracking, formal institutional degrees, or fully offline edge processing."}, {"i": "D1.1-L4-c", "c": "D1.1", "l": 4, "f": "c", "cl": "I can explain a capability trade-off to a non-expert.", "s": "A friend asks why a free AI chatbot sometimes invents realistic historical facts. How should you explain this capability trade-off?", "o": ["The tool is built to predict fluent text patterns rather than check facts, allowing it to stay highly creative but prone to believable errors.", "The tool is programmed to prioritize entertainment over accuracy for free users, reserving verified databases for premium corporate accounts.", "The tool is designed to search open internet forums where user rumors contaminate the output, forcing the system to repeat incorrect data.", "The tool is configured to save processing memory by shortening its calculations, which accidentally introduces random historical names."], "k": 0, "w": "Large language models balance creative text generation against precise factual verification, optimizing for fluency over accuracy. Distractors incorrectly blame text length optimization, commercial tier restrictions, or public forum scraping."}, {"i": "D1.2-L1-a", "c": "D1.2", "l": 1, "f": "a", "cl": "I know AI can sound confident and still be wrong.", "s": "An AI answer includes a precise line: \"A 2023 Leiden trial showed a 34% improvement.\" Why treat this with care?", "o": ["AI can convincingly invent precise details like a named study and figure.", "AI can only output verified data when it cites a specific percentage.", "AI can pull statistics only from public medical records that match exactly.", "AI can change historical numbers to protect the privacy of the participants."], "k": 0, "w": "Language models simulate authority by inventing highly specific details, names, and statistical counts. Distractors exhibit common mistakes, such as assuming that exact values or numerical formats confirm factual validity."}, {"i": "D1.2-L1-b", "c": "D1.2", "l": 1, "f": "b", "cl": "I know AI does not truly understand the way a person does.", "s": "Why might an AI write a grammatically perfect reply that still completely misses what you actually meant?", "o": ["Because it predicts fluent text without grasping meaning, it can be smooth yet off-target.", "Because it lacks a proper spelling checker, it replaces complex definitions with simple words.", "Because it updates its memory during your typing, it gets confused by long sentences.", "Because it uses translation software for every query, it alters the intent of your words."], "k": 0, "w": "AI creates fluent syntax based on structural token probabilities without tracking true underlying intent or meaning. Distractors represent technical errors regarding translation layers, typing processing, or standard grammar checking tools."}, {"i": "D1.2-L1-c", "c": "D1.2", "l": 1, "f": "c", "cl": "I know AI can reflect gaps in what it was trained on.", "s": "An AI gives great advice on a popular global topic but is vague and wrong on a niche local one. Most likely reason?", "o": ["Because local topics are protected by strict privacy laws, the system blocks the information.", "Because regional information changes too fast for computers, the data becomes obsolete daily.", "Because the developers filter out small towns, the system ignores local request terms.", "Because it saw far more data on common topics, rare ones are weaker."], "k": 3, "w": "Model accuracy corresponds directly to training dataset volume, making thin or localized subjects highly error-prone. Distractors suggest false barriers like regional compliance walls, developer geographic filters, or processing speed caps."}, {"i": "D1.2-L2-a", "c": "D1.2", "l": 2, "f": "a", "cl": "I can spot the fabricated part in an AI answer.", "s": "An AI claims chamomile cuts night waking by 40% according to the 2019 Zurich Sleep Index. Which part is most suspect?", "o": ["The therapeutic claim that chamomile functions as a natural calming herb is highly doubtful.", "The general advice that drinking herbal tea helps people rest better is completely incorrect.", "The named 2019 Zurich Sleep Index and its exact 40% figure are most suspect.", "The suggestion that tracking sleep patterns improves overnight rest is a known myth."], "k": 2, "w": "Academic citations and matching numeric percentages are common forms of hallucination used to make text sound authoritative. Distractors question the basic validity of common herbal remedies rather than targeting the fabricated evidence."}, {"i": "D1.2-L2-b", "c": "D1.2", "l": 2, "f": "b", "cl": "I can tell an unverifiable claim from a checkable one.", "s": "An AI recommends a cafe and states it \"won Best Espresso in the city in 2022.\" What is the main issue here?", "o": ["Because cafe reviews change fast, the quality rating is likely completely wrong now.", "Because espresso taste is purely personal, the recommendation cannot be trusted by anyone.", "Because the system lacks a map feature, it cannot know the true city location.", "Because a named award and year is a checkable external claim, you should verify it."], "k": 3, "w": "Factual claims with historical keys, award names, or calendar dates can be cross-referenced against public records. Distractors track opinions on flavor subjectivity, operational location software, or shifting hospitality trends."}, {"i": "D1.2-L2-c", "c": "D1.2", "l": 2, "f": "c", "cl": "I can notice when an answer quietly changes my question.", "s": "You ask an AI for the cheapest laptop option, but the tool enthusiastically describes the \"best\" model instead. What occurred?", "o": ["Because it lacks price data, it uses popularity as a direct substitute.", "Because it uses a premium filter, it blocks cheap options from users.", "Because it wants to maximize profits, it tricks you into buying more.", "Because it drifted from cheapest to best, a subtle switch, you should catch it."], "k": 3, "w": "Context drift occurs when models shift user criteria toward high-frequency training associations like quality rankings. Distractors incorrectly suggest corporate monetization schemes, hard financial filters, or complete database absence."}, {"i": "D1.2-L3-a", "c": "D1.2", "l": 3, "f": "a", "cl": "I can predict which tasks a text-only AI will struggle with.", "s": "Which task is a text-only chatbot, with no internet access or external tools, most likely to get wrong?", "o": ["Because summarizing long classic novels requires deep emotional empathy, the text tool fails.", "Because drafting promotional marketing emails requires live feedback, the text tool fails.", "Because translating standard business memos requires cultural immersion, the text tool fails.", "Because live prices change constantly, stating a stock's exact price now is unreliable."], "k": 3, "w": "Static offline models cannot query live events, leading to severe failure rates on real-time data needs. Distractors argue that human empathy or cultural context completely prevents automated text processing, translation, or summary."}, {"i": "D1.2-L3-b", "c": "D1.2", "l": 3, "f": "b", "cl": "I can foresee counting and arithmetic slips before trusting them.", "s": "You paste a long list of items into an AI tool and ask for an exact count and total sum. What should you plan to do?", "o": ["Trust the final sum entirely, because computers execute mathematical formulas without making errors.", "Because long precise counting is a known weak spot, verify the count and total.", "Reject the calculation immediately, because language models cannot process formatting like columns or rows.", "Check the spelling of the items, because typographical mistakes cause the system to drop rows."], "k": 1, "w": "Language models tokenized for text frequently miscount characters or lines, necessitating secondary validation of calculations. Distractors assert absolute computational perfection or assume models cannot parse standard structured line formats."}, {"i": "D1.2-L3-c", "c": "D1.2", "l": 3, "f": "c", "cl": "I can anticipate when my own question biases the answer.", "s": "You ask \"Why is option X the best?\" and the AI lists only benefits for X. What failure is at work?", "o": ["Because the question is leading, it defends X and skips the downsides.", "Because option X is historically superior, it generates the only true response.", "Because the system lacks competitive databases, it drops alternative product files.", "Because the tool requires absolute clarity, it ignores complex comparison tables."], "k": 0, "w": "Sycophancy causes generative systems to conform to the premise of a leading user prompt, hiding objective balancing data. Distractors assume true product dominance, systemic database corruption, or structural tabular limitations."}, {"i": "D1.2-L4-a", "c": "D1.2", "l": 4, "f": "a", "cl": "I can build a check that targets AI's most likely error.", "s": "You set up AI to draft messages containing dates and names. Which single check catches its most likely error?", "o": ["Because specifics are the main risk, verify every name, date and figure first.", "Because message tone varies across platforms, check the emotional impact on readers.", "Because long text reduces email open rates, check the exact final character count.", "Because translation layers introduce code bugs, check the background script for errors."], "k": 0, "w": "Factual information represents the highest error margin in text generation, demanding systematic programmatic or human verification. Distractors fixate on subjective stylistic reviews, message length optimization, or lower-risk backend bugs."}, {"i": "D1.2-L4-b", "c": "D1.2", "l": 4, "f": "b", "cl": "I can design a workflow that resists fabricated sources.", "s": "To stop AI summaries from citing reference sources that do not exist, which design choice helps most?", "o": ["Because short summaries prevent errors, limit the final output to 50 words.", "Because formatting hides lies, force the system to use plain text files.", "Because public tools are less stable, change the user interface every week.", "Because openable links are checkable, require them and flag any it cannot provide."], "k": 3, "w": "Forcing verifiable hyperlinks lets users anchor text claims to reality and surface hallucinations quickly. Distractors suppose that output caps, plain text formatting, or interface adjustments stop the underlying token fabrication."}, {"i": "D1.2-L4-c", "c": "D1.2", "l": 4, "f": "c", "cl": "I can decide when a task is too risky to let AI run unchecked.", "s": "For which specific task should you avoid letting an AI tool act automatically without human review?", "o": ["Because grammar rules change over time, writing corporate blog entries requires a human review.", "Because sorting takes high processing power, organizing customer lists requires a human review.", "Because money moves are irreversible, refunds or payments need a human check.", "Because data logs grow large, deleting temporary web cache files requires a human review."], "k": 2, "w": "Irreversible transactions with severe financial or legal stakes require human-in-the-loop validation to absorb automation failures. Distractors cite low-risk tasks like marketing copy editing, simple list sorting, or local cache clearance."}, {"i": "D1.3-L1-a", "c": "D1.3", "l": 1, "f": "a", "cl": "I can find and manage a file I saved.", "s": "You saved an important document on your desktop computer but cannot find it. Which approach is reliable?", "o": ["Because files disappear during power saving, restart the system to restore memory.", "Because systems delete files after closing, check the permanent removal trash history.", "Because the file still exists, search its name or check Downloads and recents.", "Because desktop folders corrupt easily, download the file from the internet again."], "k": 2, "w": "Methodical file recovery utilizes recent history tools, download directories, and operating system indexing tools rather than guessing. Distractors reflect irrational fears about sleep mode data loss, sudden automatic wiping, or directory corruption."}, {"i": "D1.3-L1-b", "c": "D1.3", "l": 1, "f": "b", "cl": "I can recover access to an account sensibly.", "s": "A login page says your password is wrong although you are sure it is right. What is the best first move?", "o": ["Because account errors damage hardware, shut down the device for one hour.", "Because website errors imply safety hacks, report a data breach to authorities.", "Because old browsers lock out accounts, delete the entire system software setup.", "Because small input slips are common, check Caps Lock, then use forgot password."], "k": 3, "w": "Resolving authentication problems starts with verifying local entry parameters before triggering formal account recovery paths. Distractors lean into extreme overreactions like hardware cooling shutdowns, immediate breach alerts, or complete system wipes."}, {"i": "D1.3-L1-c", "c": "D1.3", "l": 1, "f": "c", "cl": "I can tell a safe online prompt from a risky one.", "s": "A browser pop-up window suddenly states your device is infected and demands you click to fix it. What is the best action?", "o": ["Because infection alerts are urgent, click the button to run the scanner.", "Because genuine warnings never demand a panic click, ignore or close the pop-up.", "Because delaying allows viruses to spread, download the suggested security application immediately.", "Because pop-ups mirror system tools, trust the message and provide admin credentials."], "k": 1, "w": "Scareware relies on emotional panic and urgent calls to action to force users to execute unsafe downloads. Distractors promote compliance with the scam by urging immediate clicking, swift software acquisition, or credential sharing."}, {"i": "D1.3-L2-a", "c": "D1.3", "l": 2, "f": "a", "cl": "I can keep files in sync across devices.", "s": "You want to access the same up-to-date document on your phone and laptop without emailing copies back and forth. What is the best approach?", "o": ["Because local drives are fast, export the text to a removable card weekly.", "Because security requires isolation, print the document and scan it on each device.", "Because modern screens share images, take photos of the laptop with the phone.", "Because a synced cloud folder holds one live copy, both devices open the same file."], "k": 3, "w": "Cloud storage ecosystems keep files synchronized centrally, ensuring multi-device parity without redundant versions. Distractors recommend highly manual, inefficient habits like physically re-scanning documents, taking screen photos, or swapping local storage cards."}, {"i": "D1.3-L2-b", "c": "D1.3", "l": 2, "f": "b", "cl": "I can control an app's permissions.", "s": "A smartphone application keeps tracking your location in the background and you want that to stop. Where do you adjust this setting?", "o": ["Because tracking depends on the cell network, contact your mobile provider service desk.", "Because per-app permissions control access, fix it in that app's settings.", "Because updates reset security logs, wait for the next operating system release.", "Because hardware switches control data, cover the top front microphone of the device."], "k": 1, "w": "Operating systems manage data privacy through modular application permission menus where users can toggle background access. Distractors display errors like calling service providers, blocking physical hardware elements, or waiting for systemic software updates."}, {"i": "D1.3-L2-c", "c": "D1.3", "l": 2, "f": "c", "cl": "I can weigh a convenience against a privacy trade.", "s": "A simple free puzzle game asks for access to your contacts, photo library, and microphone. What is a sensible reading of this situation?", "o": ["Because game developers require user details to improve graphics, approve the access.", "Because access should match need, question the request and deny what is unnecessary.", "Because mobile apps are pre-screened for safety, accept the conditions without worry.", "Because denying permission corrupts the save file, grant full access to play."], "k": 1, "w": "Evaluating data privacy involves verifying whether requested system permissions match the functional scope of the tool. Distractors illustrate over-trusting marketplace screening, believing technical myths about file corruption, or accepting bad justifications for data harvesting."}, {"i": "D1.3-L3-a", "c": "D1.3", "l": 3, "f": "a", "cl": "I can troubleshoot by isolating the cause.", "s": "A video call freezes on your phone but not your laptop when using the same home network. What is the best initial diagnostic action?", "o": ["Because full systems share resources, reset the main residential internet gateway immediately.", "Because only the phone fails, reset its connection before anything wider.", "Because bandwidth varies by account, contact the cellular provider to increase data allowances.", "Because video software is intensive, replace the application across all personal devices."], "k": 1, "w": "Effective troubleshooting isolates variables by testing the failing component independently before modifying shared infrastructure. Distractors involve unnecessarily resetting the entire network, upgrading external data plans, or replacing software everywhere."}, {"i": "D1.3-L3-b", "c": "D1.3", "l": 3, "f": "b", "cl": "I can fix an app problem in a sensible order.", "s": "A specific smartphone application crashes immediately whenever you try to open it. Which sequence of fixes is the most logical?", "o": ["Because light fixes come first, force-close and reopen, then update or reinstall.", "Because storage resets data, delete all account credentials, then restart the phone hardware.", "Because network updates resolve bugs, disconnect from internet access, then change the device password.", "Because deep alterations clear errors, factory reset the smartphone, then adjust the display settings."], "k": 0, "w": "Technical troubleshooting should follow a low-to-high impact sequence, starting with trivial adjustments before moving to disruptive changes. Distractors suggest starting with destructive actions like data deletion, password changes, or full system wipes."}, {"i": "D1.3-L3-c", "c": "D1.3", "l": 3, "f": "c", "cl": "I can spot when a fix is targeted rather than random.", "s": "Your smartphone alerts you that photos cannot save because the local device storage is full. What is the targeted fix?", "o": ["Because storage is full, free space by removing or offloading large unused files.", "Because storage is full, change the default home screen layout to save power.", "Because storage is full, download a secondary web browser application from the marketplace.", "Because storage is full, reset the cellular network connection settings to factory defaults."], "k": 0, "w": "A targeted fix directly addresses the root cause of an error rather than applying random changes. Distractors represent irrelevant modifications like altering visual layouts, acquiring secondary browsers, or resetting network connections."}, {"i": "D1.3-L4-a", "c": "D1.3", "l": 4, "f": "a", "cl": "I can set up shared access for others safely.", "s": "You are setting up a shared cloud repository for a working group. Which approach provides access without over-exposing your personal data?", "o": ["Because access should be scoped, grant each person permission to that folder only.", "Because access requires collaboration, give the entire group your master account credentials.", "Because access must remain open, disable all privacy passwords on the shared folder.", "Because access needs tracking, authorize administrative entry to your full personal storage drive."], "k": 0, "w": "The principle of least privilege dictates that users should only receive the minimum access required to complete their specific tasks. Distractors advocate for dangerous over-exposure like credential sharing, removing passwords, or granting full storage drive permissions."}, {"i": "D1.3-L4-b", "c": "D1.3", "l": 4, "f": "b", "cl": "I can configure a device so a less-confident person copes alone.", "s": "You are setting up a tablet for an older relative to make video calls independently. Which configuration helps them the most?", "o": ["Because advanced tools maximize options, install four separate messaging platforms with different notifications.", "Because storage efficiency preserves performance, configure the system to delete call logs every hour.", "Because ease matters, set large text, a one-tap call shortcut and automatic updates.", "Because complete control reduces confusion, require manual validation for every routine system update."], "k": 2, "w": "Supporting non-technical users involves reducing cognitive load through accessibility settings, direct shortcuts, and automated background maintenance. Distractors increase user confusion by adding redundant platforms, deleting history, or requiring manual update validation."}, {"i": "D1.3-L4-c", "c": "D1.3", "l": 4, "f": "c", "cl": "I can design a backup habit that survives a lost device.", "s": "You want to ensure your personal family photos survive if your primary smartphone is lost or physically broken. What is the strongest setup?", "o": ["Because local copies are easily accessible, leave the images on the phone internal memory.", "Because a second automatic copy survives loss, back up to a cloud or drive.", "Because physical items are durable, save the image files onto a secondary smartphone screen.", "Because encryption prevents total corruption, change the security code on the mobile device daily."], "k": 1, "w": "Redundancy through off-site duplication guarantees that data persists independently of any single physical failure or device loss. Distractors rely on unsafe habits like keeping data localized, taking screen photos, or altering device passcodes."}, {"i": "D1.4-L1-a", "c": "D1.4", "l": 1, "f": "a", "cl": "I treat AI as a tool, not an authority.", "s": "An AI tool provides financial advice that directly contradicts your personal knowledge of your situation. What is the healthiest stance?", "o": ["Because computers possess superior calculation capabilities, accept the tool's suggestions over your intuition.", "Because AI only informs, treat it as one input and let your judgement lead.", "Because automated advice is legally binding, follow the recommendation to avoid administrative errors.", "Because systems avoid making factual errors, assume your personal calculations are completely wrong."], "k": 1, "w": "AI outputs serve as informational references rather than infallible commands, meaning human oversight must ultimately guide final choices. Distractors represent over-trusting habits that defer personal agency entirely to the automated output."}, {"i": "D1.4-L1-b", "c": "D1.4", "l": 1, "f": "b", "cl": "I know the responsibility for a choice stays with me.", "s": "You choose to execute a plan based on a suggestion generated by an AI chatbot, and the plan fails. Who is accountable?", "o": ["Because you chose to act on it, the accountability is yours.", "Because the developer created the software code, the accountability is theirs.", "Because the tool generated the specific text response, the accountability is its.", "Because the internet provided the initial training datasets, the accountability is shared."], "k": 0, "w": "End-users retain full ethical and practical accountability for actions they choose to execute, regardless of where the ideas originated. Distractors reflect the misconception that blame can be shifted onto software code, inanimate models, or internet data."}, {"i": "D1.4-L1-c", "c": "D1.4", "l": 1, "f": "c", "cl": "I can notice when AI is quietly replacing my own thinking.", "s": "Which user habit serves as an early warning sign that you are leaning on AI tools too heavily?", "o": ["Because checking metrics keeps you sharp, comparing output text with public encyclopedias is the sign.", "Because exploration builds skill, trying out alternative phrasing styles on the prompt is the sign.", "Because understanding fades quietly, accepting answers you no longer try to grasp is the sign.", "Because security protects data, changing your account password every single month is the sign."], "k": 2, "w": "Passive compliance with unverified machine output indicates a decline in critical engagement and active human reasoning. Distractors highlight healthy verification and exploration practices or irrelevant account security actions."}, {"i": "D1.4-L2-a", "c": "D1.4", "l": 2, "f": "a", "cl": "I keep my own voice and judgement in AI-assisted work.", "s": "An AI tool drafts a heartfelt message for you to send to a close friend. Before sending, what is the most human-centered move?", "o": ["Because automated writing is flawless, copy the draft directly into your messaging screen immediately.", "Because efficiency is your primary objective, send the text without spending time reading it over.", "Because algorithms understand relationships well, trust that the language matches your personal connection perfectly.", "Because it must be true and yours, read it and adjust anything off."], "k": 3, "w": "Maintaining human-centered relationships requires editing automated text drafts to ensure they convey genuine individual intent and voice. Distractors advocate for blind copying, prioritizing raw speed over relationships, or over-trusting algorithmic emotional intelligence."}, {"i": "D1.4-L2-b", "c": "D1.4", "l": 2, "f": "b", "cl": "I check AI output against what I already know.", "s": "An AI tool provides walking directions to a local landmark you know well, but the route appears incorrect. What should you do?", "o": ["Because you know the area, trust that knowledge and cross-check the route.", "Because systems use satellite tracking, follow the new route despite your personal doubts.", "Because maps adjust to live construction variables, ignore your experience and walk blindly.", "Because software optimization reduces transit times, assume the classic neighborhood path is closed."], "k": 0, "w": "Established personal experience provides a critical baseline for verifying spatial or factual claims made by an offline text tool. Distractors suggest suppressing your own knowledge out of deference to assumed satellite accuracy or nonexistent live mapping telemetry."}, {"i": "D1.4-L2-c", "c": "D1.4", "l": 2, "f": "c", "cl": "I can resist an answer just because it is convenient.", "s": "An AI tool offers a convenient response that saves you hours of work, but you have a small nagging doubt about it. What is the best action?", "o": ["Because convenience is not correctness, check the doubt before relying on it.", "Because saving time is your ultimate metric, ignore the small doubt entirely.", "Because computers analyze text patterns deeply, trust that the answer is perfect.", "Because checking data requires too much energy, assume the error is minor."], "k": 0, "w": "Resisting the convenience trap means taking the time to validate plausible-sounding shortcuts before acting on them. Distractors reinforce bad habits like prioritizing speed over accuracy, trusting the computer blindly, or dismissing doubts due to low energy."}, {"i": "D1.4-L3-a", "c": "D1.4", "l": 3, "f": "a", "cl": "I can balance speed against accountability.", "s": "An AI tool can auto-approve low-value customer refunds for your online shop, saving you time. What is a responsible configuration?", "o": ["Because risk scales with size, auto-handle small refunds and route larger ones to you.", "Because full automation ensures equality, allow the tool to approve all transactions without review.", "Because manual steps reduce efficiency, completely disable human oversight to speed up processing.", "Because systems require constant observation, check every single small transaction while it finishes live."], "k": 0, "w": "Balancing efficiency and risk involves setting automated guardrails for low-stakes actions while preserving human oversight for high-impact decisions. Distractors represent complete abdication of control or inefficient micro-management of low-risk flows."}, {"i": "D1.4-L3-b", "c": "D1.4", "l": 3, "f": "b", "cl": "I decide when to defer to AI and when to override it.", "s": "In a professional workflow, when is overriding an automated AI recommendation most clearly justified?", "o": ["Because verifiable conflict matters, override it when facts or your values disagree.", "Because standard software operates predictably, override it when the layout matches your expectations.", "Because tool pricing changes monthly, override it when the corporate subscription tier drops down.", "Because processing limits reduce efficiency, override it when the response generates too quickly."], "k": 0, "w": "Overriding automated output is essential when the generated suggestions conflict with verified facts or human ethical principles. Distractors link overriding to visual interface consistency, corporate subscription pricing, or raw computing speed."}, {"i": "D1.4-L3-c", "c": "D1.4", "l": 3, "f": "c", "cl": "I can tell high-stakes decisions from low-stakes ones for AI use.", "s": "For which specific scenario should an AI tool stay strictly an assistant rather than becoming the primary decider?", "o": ["Because color choices carry minimal financial risk, selecting a background theme requires a human decider.", "Because it affects a person's livelihood, a loan or job decision needs a human decider.", "Because simple categorization saves operational time, sorting incoming spam emails requires a human decider.", "Because grammatical correctness impacts clarity, checking basic spelling rules needs a human decider."], "k": 1, "w": "High-stakes determinations affecting human livelihoods or legal rights require human judgment to prevent systemic biases and maintain accountability. Distractors classify low-stakes tasks like theme styling, spam filtering, or spellchecking as requiring strict human finality."}, {"i": "D1.4-L4-a", "c": "D1.4", "l": 4, "f": "a", "cl": "I can champion human-centered use in a group's norms.", "s": "You are establishing a single AI-use norm for a community volunteer organization. Which core principle is strongest?", "o": ["Because speed is our chief metric, members must automate all outgoing official letters.", "Because technology is flawless, the software will handle all member dispute resolutions automatically.", "Because checking work causes unnecessary delays, trust all generated metrics without manual validation.", "Because accountability anchors trust, AI assists while a named person owns the outcome."], "k": 3, "w": "Promoting human-centered norms means ensuring human actors remain explicitly accountable for any automated output published by the group. Distractors elevate complete automation, uncritical trust, or absolute speed above organizational transparency and accountability."}, {"i": "D1.4-L4-b", "c": "D1.4", "l": 4, "f": "b", "cl": "I can help others keep their judgement in the loop.", "s": "A teammate constantly forwards unverified AI chat responses as absolute fact in your group workspace. How can you help them?", "o": ["Because habits build judgement, show them a quick verify-before-share routine and its value.", "Because conflict damages morale, accept the shared information quietly to keep the peace.", "Because software handles verification automatically, tell them to download a secondary validation extension.", "Because compliance requires authority, report their profile to the network administration team immediately."], "k": 0, "w": "Mentoring peers in digital literacy involves sharing practical, low-friction habits for validating claims rather than ignoring the issue or escalating it. Distractors suggest passive capitulation, trusting extensions blindly, or jumping directly to administrative punishments."}, {"i": "D1.4-L4-c", "c": "D1.4", "l": 4, "f": "c", "cl": "I can spot when 'efficiency' is hiding a loss of accountability.", "s": "A committee wants to fully automate the selection of new members using a text tool to save time. What is the main human-centered concern?", "o": ["Because automation consumes substantial network bandwidth, the group website will face frequent connectivity crashes.", "Because the system requires unique fonts, members will struggle to read the final acceptance notifications.", "Because full automation removes a decider, no one would answer for the outcome.", "Because digital tools operate slowly, the evaluation process will take weeks longer than manual reviews."], "k": 2, "w": "The primary ethical risk of total automation is the removal of explicit human agency, leaving no one responsible for biased or erroneous outcomes. Distractors focus on minor infrastructure concerns like internet bandwidth, visual font layouts, or inaccurate processing speeds."}, {"i": "D2.1-L1-a", "c": "D2.1", "l": 1, "f": "a", "cl": "I can ask a clear, answerable question.", "s": "Which request gives the AI tool enough specific context to actually help you plan dinner?", "o": ["What should humans eat when they feel hungry in the evening hours?", "Suggest 3 quick dinners I can make with chicken and rice.", "Tell me everything about the culinary history of cooking basic poultry dishes.", "Make a meal out of whatever ingredients exist inside my kitchen cabinets."], "k": 1, "w": "Clear prompts specify constraints like quantities, ingredient lists, and time boundaries to yield actionable suggestions. Distractors show vague philosophical queries, overly broad history requests, or impossible demands for the system to scan invisible home cabinets."}, {"i": "D2.1-L1-b", "c": "D2.1", "l": 1, "f": "b", "cl": "I can tell a clear prompt from a vague one.", "s": "Two users want to learn about financial planning. Which prompt is structured clearly enough to yield a practical answer?", "o": ["Discuss money and how people manage their bank accounts over time.", "Help me understand banks because financial matters feel very confusing today.", "Provide a comprehensive list of every investment strategy known to historians.", "Explain simply how a savings buffer works and roughly how much a beginner might aim for."], "k": 3, "w": "Clarity in prompting involves identifying specific subtopics and target formats rather than requesting general discussions or impossibly vast historical overviews. Distractors illustrate rambling emotional statements, overly abstract topics, or boundless data dumps."}, {"i": "D2.1-L1-c", "c": "D2.1", "l": 1, "f": "c", "cl": "I know a polite or longer prompt is not automatically a better prompt.", "s": "A friend thinks adding \"please, kind AI, if you would be so lovely\" gets better answers. What is the best guidance?", "o": ["What helps most is being clear and specific, not flattery.", "What helps most is keeping character counts low, not manners.", "What helps most is using formal legal language, not friendliness.", "What helps most is waiting for the system update, not politeness."], "k": 0, "w": "Language models process computational instructions based on semantic clarity rather than human social courtesy or flattery. Distractors display errors such as prioritizing character limits, legal tones, or future network modifications."}, {"i": "D2.1-L2-a", "c": "D2.1", "l": 2, "f": "a", "cl": "I can isolate the precise context an AI requires to generate highly relevant and useful outputs.", "s": "When requesting a tailored travel inventory, which phrasing provides the model with the necessary parameters?", "o": ["A nice comprehensive overview of what travelers need for typical vacation destinations.", "Help me figure out what to put in my luggage before leaving home next season.", "A complete packing checklist for individuals traveling to cold locations during winter holidays.", "Packing list for a 3-day winter city trip, carry-on only, one adult."], "k": 3, "w": "Effective context requires specific, concrete parameters like trip duration, baggage restrictions, and traveler counts to guide the output. Distractors rely on broad generalities, emotional statements, or open-ended destination descriptors."}, {"i": "D2.1-L2-b", "c": "D2.1", "l": 2, "f": "b", "cl": "I can articulate a specific goal so the resulting AI response aligns perfectly with its intended purpose.", "s": "If you require practical academic strategies tailored specifically for brief night sessions, which prompt provides the necessary direction?", "o": ["Discuss how students manage their learning environments when studying in dark rooms.", "What are the main differences between daytime learning habits and night work?", "Explain why human concentration levels drop significantly after completing a long workday.", "Give me 5 study tips for short evening sessions when I struggle to focus."], "k": 3, "w": "Clear goals include structural constraints like counts, specific behaviors, and targeted circumstances to ensure actionable responses. Distractors ask for broad discussions, comparative histories, or explanations of biological phenomena."}, {"i": "D2.1-L2-c", "c": "D2.1", "l": 2, "f": "c", "cl": "I can tell relevant context from noise.", "s": "Which detail actually helps the AI recommend a workout, rather than padding the prompt?", "o": ["I bought new blue athletic shoes last weekend from a sports store downtown.", "I have 20 minutes a day, no equipment, and a knee to protect.", "I really want to become a healthier person before summer vacation starts.", "I think my regular gym membership is getting too expensive to maintain."], "k": 1, "w": "Functional constraints like time limits, equipment availability, and physical restrictions directly shape the program logic. Distractors represent conversational noise, like shoe colors, general aspirations, or gym pricing complaints."}, {"i": "D2.1-L3-a", "c": "D2.1", "l": 3, "f": "a", "cl": "I can structure a prompt with role, context and output format.", "s": "Which prompt is best structured for a reliable, reusable result?", "o": ["Act as a budgeting coach. From the income and costs below, return a table of categories, amounts and one savings tip.", "Think like a wealthy banker. Look at my simple financial metrics and guess if I spend too much money on food.", "Assume I want to save cash. Read my bank transaction history and write a long essay explaining my personal habits.", "Operate as an entry level accountant. Review the attached document list and tell me your emotional reaction to the total."], "k": 0, "w": "Structured prompts isolate the persona, input data reference, and structural output layout clearly. Distractors rely on subjective actions, vague guesses, emotional responses, or unstructured essay formats."}, {"i": "D2.1-L3-b", "c": "D2.1", "l": 3, "f": "b", "cl": "I can give an example to steer the format I want.", "s": "You want the AI to reformat messy notes consistently. What most reliably gets the format you want?", "o": ["Tell the system how frustrating disorganized layout designs look to typical professional corporate readers.", "Show it one example of the exact layout you want, then ask it to match that.", "Request the tool to use its default optimization logic to straighten out the text file headers.", "Ask for a clean structure that looks highly professional according to standard modern internet conventions."], "k": 1, "w": "Few-shot prompting using concrete formatting examples provides an explicit pattern for the model to replicate. Distractors try to guide layouts using emotional complaints, default formatting assumptions, or vague stylistic descriptors."}, {"i": "D2.1-L3-c", "c": "D2.1", "l": 3, "f": "c", "cl": "I can break a big task into steps instead of one giant ask.", "s": "You want AI to research a topic, then summarise it, then draft a post. What is the best approach?", "o": ["Do it in steps: gather, then summarise, then draft, checking each stage.", "Ask for everything at once in a single massive message to save internet bandwidth.", "Request three alternative draft variations simultaneously and pick the longest generation.", "Let the tool determine the execution sequence independently without monitoring the interim outputs."], "k": 0, "w": "Chaining complex workflows sequentially prevents errors by letting users audit and correct text at each boundary. Distractors promote high-risk single prompts, choosing items based solely on length, or abdicating sequence control."}, {"i": "D2.1-L4-a", "c": "D2.1", "l": 4, "f": "a", "cl": "I can design a prompt template others can reuse.", "s": "You are turning a prompt that worked into a template for others. What makes it reusable?", "o": ["Locking the text configuration entirely so nobody can alter the words inside the instruction box.", "Replace the parts that change with clear placeholders and a note on how to fill them.", "Translating the operational definitions into complex coding languages to protect the background layout structure.", "Adding comprehensive warnings telling team members to avoid running the instruction on mobile operating systems."], "k": 1, "w": "Templates remain reusable by isolating static structural text from variable user data via clear placeholders. Distractors advocate for locking fields completely, using irrelevant coding structures, or adding mobile hardware limits."}, {"i": "D2.1-L4-b", "c": "D2.1", "l": 4, "f": "b", "cl": "I can write a standing instruction that sets behaviour once.", "s": "You want an AI to always reply in a warm, short tone for your project, without repeating that each time. What is the best move?", "o": ["Copy and paste your style demands manually into every new message string you open.", "Set it once as a saved standing instruction the AI follows by default.", "Hope the system remembers your stylistic voice across different browser application windows automatically.", "Type your strict tone requirements in capital letters during your very first introductory profile configuration."], "k": 1, "w": "System instructions or custom rules anchor model behavior persistently across different operational sessions. Distractors rely on repetitive manual cutting, blind hope, or shouting parameters inside initial setup screens."}, {"i": "D2.1-L4-c", "c": "D2.1", "l": 4, "f": "c", "cl": "I can teach a repeatable prompting pattern, not just give one answer.", "s": "A friend keeps getting weak AI results. Which help builds their skill rather than solving the problem once?", "o": ["Rewrite their current prompt text for them so they complete their assignment on time today.", "Recommend they purchase a premium subscription tier to bypass formatting issues completely.", "Show them the pattern: role, context, format, then refine, and when to use it.", "Tell them to search online forums until they find a matching pre-written code snippet."], "k": 2, "w": "Teaching framework patterns empowers users to adapt their prompting strategies across diverse future use cases. Distractors resolve the immediate block without building capability, or recommend expensive upgrades and forum searching."}, {"i": "D2.2-L1-a", "c": "D2.2", "l": 1, "f": "a", "cl": "I know the first answer is a starting point, not the final word.", "s": "The AI's first answer is vague. What is the healthiest view of it?", "o": ["The system cannot understand your topic and you must change your project entirely.", "It is a first draft you can improve by asking again with detail.", "The software interface is broken and requires a full hardware reboot to function.", "The response represents the absolute factual peak of what automation can deliver today."], "k": 1, "w": "First generations are initial baselines that can be conversationalized and refined through incremental prompting. Distractors treat weak starts as definitive capability ceilings, project failures, or hardware breakdowns."}, {"i": "D2.2-L1-b", "c": "D2.2", "l": 1, "f": "b", "cl": "I know a specific follow-up beats starting over.", "s": "An AI recipe is missing the quantities. What is the simplest good move?", "o": ["Close the current chat session immediately and start over with a fresh blank page.", "Ask it to add exact amounts and steps.", "Assume the recipe is dangerous and delete the entire browser application history log.", "Search online for human cooking blogs to replace the automated generation completely."], "k": 1, "w": "Submitting direct follow-up requests within the active context window maintains continuity and addresses specific gaps easily. Distractors recommend inefficient clean slates, panic clearing, or abandoning the tool immediately."}, {"i": "D2.2-L1-c", "c": "D2.2", "l": 1, "f": "c", "cl": "I can tell a useless retry from a useful one.", "s": "Which action is most likely to actually improve a weak answer?", "o": ["Submitting the identical prompt text repeatedly without making any changes to the wording.", "Typing the request using all capital letters to display urgency to the system processor.", "Adding polite phrases like thank you very much to motivate the text engine.", "Saying what was missing and asking again."], "k": 3, "w": "Meaningful iteration identifies explicit informational deficiencies and directs the model to remediate them. Distractors represent repetitive submission habits, typographical shouting, or empty social pleasantries."}, {"i": "D2.2-L2-a", "c": "D2.2", "l": 2, "f": "a", "cl": "I re-ask with the missing detail rather than vaguely.", "s": "An AI gave a generic workout plan. What is the best refinement?", "o": ["Make it much better and cooler for an average adult user this time.", "Do it over because that first draft looked boring to my family members.", "Add your goal, time per day and any injury, then ask again.", "Change the entire text format because the structure feels a little bit off."], "k": 2, "w": "Refinement requires injecting missing programmatic details rather than submitting vague stylistic complaints. Distractors offer empty qualitative descriptors like \"cooler,\" \"boring,\" or \"off\" without adding functional data."}, {"i": "D2.2-L2-b", "c": "D2.2", "l": 2, "f": "b", "cl": "I can steer tone or format on a second pass.", "s": "A drafted message is too formal for a close friend. What is the best refinement?", "o": ["Start a brand new conversation and explain your childhood relationship history in detail.", "Tell the system that its vocabulary selection is completely wrong for modern human society.", "Ask a different AI application to write an essay about friendship communication styles.", "Ask for a warmer, shorter, casual version."], "k": 3, "w": "Adjusting tone or style on a second pass involves giving explicit stylistic feedback like \"warmer\" or \"casual.\" Distractors rely on conversational history dumps, aggressive tool critiques, or shifting to unrelated abstract essays."}, {"i": "D2.2-L2-c", "c": "D2.2", "l": 2, "f": "c", "cl": "I can deliver precise, actionable feedback that explicitly directs the AI on how to refine its output.", "s": "When adjusting an initial AI generation, which feedback style is most effective for improving the subsequent response?", "o": ["That response is not what I expected at all; try again from scratch.", "Fix the text layout because it looks regular and needs more professional flair.", "The structure is bad and you need to rewrite it using better arguments.", "\"Good, but it missed my budget and is too long; keep it under 5 points.\""], "k": 3, "w": "High-utility feedback isolates what was correct, identifies omissions, and sets rigid operational boundaries for the next draft. Distractors use subjective value judgments without clear, bounded criteria."}, {"i": "D2.2-L3-a", "c": "D2.2", "l": 3, "f": "a", "cl": "I iterate by changing one thing at a time.", "s": "A cover message is close but flat. Which approach is systematic iteration, not guesswork?", "o": ["Change the tone, the length, and the role description all at the same moment.", "Name the weak spots, fix one at a time, and compare versions.", "Abandon the chat window and write the document manually to save time.", "Paste the draft into a secondary search engine to locate grammatical errors."], "k": 1, "w": "Systematic refinement isolates single variables sequentially to evaluate their specific impact on text quality. Distractors recommend confounding variations, manual abandonment, or irrelevant search engine checks."}, {"i": "D2.2-L3-b", "c": "D2.2", "l": 3, "f": "b", "cl": "I refine against clear criteria, not a vibe.", "s": "How do you turn \"make it better\" into an actionable iteration?", "o": ["Judging it against set criteria: accurate, on-tone, complete, right length.", "Asking your social circle if the paragraph feels interesting to read over lunch.", "Requesting the tool to evaluate if the text flows nicely according to its intuition.", "Waiting an hour before reading the draft again to check your emotional response."], "k": 0, "w": "Actionable evaluation transitions from vague feelings to explicit parameters like accuracy, tone fit, completeness, and length bounds. Distractors prioritize social polls, machine intuition, or passing human moods."}, {"i": "D2.2-L3-c", "c": "D2.2", "l": 3, "f": "c", "cl": "I can tell real improvement from just 'different'.", "s": "After three rewrites the answer keeps missing the same key point. What is the best structured fix?", "o": ["Repeat the instruction louder by adding multiple exclamation marks at the end of the line.", "State exactly what must be included and ask it to check its draft against that list.", "Assume the application is broken and switch to an offline text processing platform.", "Delete the original prompt query text and write a short poem about the topic instead."], "k": 1, "w": "Resolving stubborn errors requires forcing the model to run a comparative check against an explicit list of mandatory criteria. Distractors present empty punctuation emphasis, tool swapping, or changing the task format entirely."}, {"i": "D2.2-L4-a", "c": "D2.2", "l": 4, "f": "a", "cl": "I can teach a repeatable refine-loop.", "s": "You show someone how to reliably get better AI results. What is the best pattern to teach?", "o": ["\"State the goal, critique the draft on set criteria, fix one point at a time.\"", "\"Submit the prompt, copy the first line, and hope the calculation is right.\"", "\"Change the persona, restart the browser session, and request a longer text block.\"", "\"Ignore the formatting, use basic templates, and run the calculation three separate times.\""], "k": 0, "w": "A repeatable refinement loop establishes clear goals, systematic critiquing criteria, and isolated, single-variable adjustments. Distractors highlight passive acceptance, chaotic reset habits, or running identical steps blindly without auditing."}, {"i": "D2.2-L4-b", "c": "D2.2", "l": 4, "f": "b", "cl": "I can share a reusable checklist for refining outputs.", "s": "Which checklist best helps your team systematically evaluate any AI text output?", "o": ["Check if the text matches the brand voice and includes relevant details.", "Check if the text reads naturally and uses appropriate formatting choices.", "Check if the text is accurate, on-tone, complete and the right length.", "Check if the text looks professional and uses advanced vocabulary terms."], "k": 2, "w": "The correct checklist covers core evaluation metrics like accuracy and completeness. Distractors focus on partial checks or superficial features like format and tone while ignoring factuality."}, {"i": "D2.2-L4-c", "c": "D2.2", "l": 4, "f": "c", "cl": "I coach my team on AI methods instead of fixing errors.", "s": "A colleague constantly asks you to fix their bad AI outputs. What is the most effective approach?", "o": ["Give them a list of specific terms to include in their next prompt.", "Fix the text yourself this time to avoid wasting collective project time.", "Teach them the critique-and-refine method so they can improve outputs independently.", "Suggest they try a different brand of AI model for better results."], "k": 2, "w": "Teaching iteration patterns scales team capability long-term. Distractors rely on temporary fixes, changing platforms or giving rigid prompt words instead of building critical evaluation skills."}, {"i": "D2.3-L1-a", "c": "D2.3", "l": 1, "f": "a", "cl": "I critical read an AI answer before taking action.", "s": "You receive instructions from a chatbot. What is the best first step before using the advice?", "o": ["Scan the text to ensure it looks professional and well organized.", "Accept the advice if the chatbot sounds confident and highly authoritative.", "Save the instructions because computers usually generate factual and accurate data.", "Read the advice carefully and check if it actually makes sense."], "k": 3, "w": "Users must critically evaluate AI text rather than blindly trusting it. Distractors show common habits like trusting confident tone, assuming computer accuracy or checking only appearance."}, {"i": "D2.3-L1-b", "c": "D2.3", "l": 1, "f": "b", "cl": "I can spot warning signs that an output requires verification.", "s": "You are reading an AI response. Which sign indicates that you must double-check the information?", "o": ["It provides a standard explanation that you have heard many times before.", "It makes a strong specific claim you cannot find anywhere else.", "It uses a polite tone and includes helpful examples for context.", "It generates a very long answer with multiple bulleted summary points."], "k": 1, "w": "Unique, unverified claims are high-risk warning signs in AI outputs. Distractors represent common misconceptions where users overlook risk due to tone, length or formatting."}, {"i": "D2.3-L1-c", "c": "D2.3", "l": 1, "f": "c", "cl": "I know a confident tone does not prove factual accuracy.", "s": "An AI assistant answers your question with absolute certainty. What does this tone tell you?", "o": ["It tells you nothing about accuracy because confidence and correctness are separate.", "It tells you the information is reliable since computers verify facts internally.", "It tells you the model found the single best answer available online.", "It tells you the topic is simple and has no conflicting viewpoints."], "k": 0, "w": "AI models generate confident-sounding text regardless of accuracy. Distractors mistake a confident tone or computer processing for a guarantee of factual correctness."}, {"i": "D2.3-L2-a", "c": "D2.3", "l": 2, "f": "a", "cl": "I verify important details before relying on them.", "s": "An AI chatbot lists local shop hours for a trip you are making today. How should you verify this?", "o": ["Trust the hours since the chatbot listed them with specific opening times.", "Trust the hours because the chatbot is a famous and expensive tool.", "Check the hours only if you arrive and find the door locked.", "Check the shop's official website to confirm the hours are correct."], "k": 3, "w": "Important specific details require verification from an official source. Distractors show habits like trusting specific details, relying on brand reputation or checking at the wrong moment."}, {"i": "D2.3-L2-b", "c": "D2.3", "l": 2, "f": "b", "cl": "I perform plausibility checks on numbers from AI.", "s": "An AI tool states that your brief morning walk burned 4,000 calories. What is the best reaction?", "o": ["Accept the number because computers calculate biological metrics with great precision.", "Accept the number since the tool customized the calculation for your walk.", "Reject the number because it is implausibly high for a walk.", "Reject the number only if your personal fitness tracker shows zero."], "k": 2, "w": "A basic sanity check reveals this figure is physically impossible. Distractors trust computer precision or individual customization, failing to apply everyday common-sense boundaries to numeric outputs."}, {"i": "D2.3-L2-c", "c": "D2.3", "l": 2, "f": "c", "cl": "I check risky claims harder than trivial outputs.", "s": "An AI text mixes a casual lifestyle tip with a specific medical dosage. Where should you focus your verification?", "o": ["Verify both equally because all text from a chatbot carries risk.", "Verify the casual tip since lifestyle trends change very quickly online.", "Verify neither because the chatbot uses trusted medical databases for answers.", "Verify the medical dosage since an error there causes real harm."], "k": 3, "w": "Verification effort should scale with the risk of the claim. Distractors treat all claims identically, assume the tool is infallible or prioritize low-stakes information."}, {"i": "D2.3-L3-a", "c": "D2.3", "l": 3, "f": "a", "cl": "I trace an important claim back to its source.", "s": "An AI tool cites an interesting statistic for a public presentation you are writing. What is the strongest check?", "o": ["Find the original published study and confirm the exact statistical data.", "Ask the tool to provide three additional facts supporting that statistic.", "Paste the statistic into a different chatbot to see if it agrees.", "Assume the statistic is correct because the tool writes very professionally."], "k": 0, "w": "Cross-checking requires independent tracking to the primary source. Distractors show bad habits like asking the same tool again, cross-checking with a different chatbot or trusting professional prose."}, {"i": "D2.3-L3-b", "c": "D2.3", "l": 3, "f": "b", "cl": "I use independent sources rather than repeating AI queries.", "s": "Which action counts as a genuine cross-check of a fact provided by an AI model?", "o": ["Comparing the fact against an independent, highly trustworthy reference source.", "Generating the same prompt again to see if you get identical text.", "Asking the chatbot if it is absolutely sure about the fact.", "Searching a different AI tool using the exact same prompt wording."], "k": 0, "w": "Genuine cross-checking requires independent verification. Distractors involve looping back into the same tool or using alternative AI tools, which may repeat the same algorithmic bias or error."}, {"i": "D2.3-L3-c", "c": "D2.3", "l": 3, "f": "c", "cl": "I check official authorities for high-stakes information.", "s": "An AI assistant states a specific benefit deadline that affects your personal finances. How do you verify this?", "o": ["Trust the date because the AI assistant explained the rules clearly.", "Check the official government website to confirm the deadline date matches.", "Run the query again later to check if the date changes.", "Ask a colleague if they heard about a deadline this month."], "k": 1, "w": "High-stakes financial or legal info requires checking the official authority. Distractors rely on clear explanations, repeating the prompt or trusting casual office hearsay."}, {"i": "D2.3-L4-a", "c": "D2.3", "l": 4, "f": "a", "cl": "I build verification steps into routine publishing workflows.", "s": "Your team publishes AI-drafted articles on a fixed schedule. What is the safest workflow requirement?", "o": ["Require a final proofread to ensure the grammar looks professional.", "Require a mandatory step to verify key facts against independent sources.", "Require a secondary AI prompt to check the tone of voice.", "Require an automated count to ensure articles meet length targets."], "k": 1, "w": "High-level creators build manual human-in-the-loop verification steps into automated publishing routines. Distractors focus on cosmetic elements like grammar, length or tone rather than factual accuracy."}, {"i": "D2.3-L4-b", "c": "D2.3", "l": 4, "f": "b", "cl": "I design workflows to flag claims that lack verification.", "s": "You are designing an AI research workflow for your department. Which feature best ensures factual reliability?", "o": ["A system that automatically formats the final output into clean slides.", "A feature that translates summaries into multiple languages for global teams.", "A setting that limits summaries to exactly three paragraphs per article.", "A requirement to link every claim to a source, flagging unlinkable items."], "k": 3, "w": "Designing a workflow that isolates and flags unverified claims prevents misinformation. Distractors focus on structural or cosmetic changes like translation, formatting and text length limits."}, {"i": "D2.3-L4-c", "c": "D2.3", "l": 4, "f": "c", "cl": "I decide upfront which claims require strict verification.", "s": "How can you make your AI verification workflow efficient rather than exhausting for your team?", "o": ["Check every single word to ensure complete accuracy across all outputs.", "Skip verification entirely unless a client complains about a specific error.", "Target high-stakes claims for strict verification while letting trivia pass through.", "Delegate all verification steps to a cheaper secondary AI model instead."], "k": 2, "w": "Efficient workflows prioritize high-stakes information based on risk. Distractors present unsustainable extremes like checking everything, checking nothing or trusting another unverified AI model to evaluate the data."}, {"i": "D2.4-L2-a", "c": "D2.4", "l": 2, "f": "a", "cl": "I save successful prompts for future use.", "s": "A prompt you wrote generated a perfect weekly meal plan. What is the smartest next step?", "o": ["Delete the text because you can easily write it again next week.", "Assume the AI tool remembers your exact phrasing automatically for next time.", "Share the final meal plan on social media to show your results.", "Save the prompt wording in a file so you can reuse it."], "k": 3, "w": "Saving successful prompts enables reliable reuse. Distractors show inefficient habits like deleting work, relying on tool memory or focusing on the output rather than the reusable prompt."}, {"i": "D2.4-L2-b", "c": "D2.4", "l": 2, "f": "b", "cl": "I store prompts so I can easily find them later.", "s": "You want to save a useful prompt for next month. What is the best storage habit?", "o": ["Store it with a clear name in a dedicated prompt folder.", "Bookmark the entire chat session in your web browser history file.", "Paste it into a random text document on your computer desktop.", "Write it down on a physical paper notepad at your desk."], "k": 0, "w": "Efficient reuse requires structured storage with clear names. Distractors like bookmarking chats, cluttered desktops or physical paper make locating specific prompts difficult later."}, {"i": "D2.4-L2-c", "c": "D2.4", "l": 2, "f": "c", "cl": "I know why reusing prompts beats rewriting them.", "s": "Why should you bother saving a prompt that worked well instead of rewriting it later?", "o": ["It ensures the AI model never updates its underlying database software.", "It guarantees the AI tool runs faster during peak operating hours.", "It prevents other users on the platform from seeing your history.", "It gives you consistent results without rewriting the instructions each time."], "k": 3, "w": "Saving prompts saves time and ensures consistent output quality. Distractors suggest incorrect technical limits, like stopping software updates, changing model speed or hiding public data."}, {"i": "D2.4-L3-a", "c": "D2.4", "l": 3, "f": "a", "cl": "I organize my prompt library by task.", "s": "Your saved AI prompts have become a messy, disorganized list. What is the best optimization strategy?", "o": ["Organize the prompts by specific tasks using clear descriptive labels.", "Delete any prompt that is more than three sentences long.", "Merge all the text into one giant master prompt file.", "Sort the list alphabetically by the very first word used."], "k": 0, "w": "A professional prompt library should be categorized by task or objective. Distractors suggest unhelpful formatting methods like sorting by first word, merging everything or deleting long prompts."}, {"i": "D2.4-L3-b", "c": "D2.4", "l": 3, "f": "b", "cl": "I maintain the best version of each prompt.", "s": "You just improved an old prompt in your library. What is the best maintenance habit?", "o": ["Keep both versions in the library so you have more total choices.", "Delete the library file completely and start a new one tomorrow.", "Share the old inferior version with colleagues to get their feedback.", "Replace the old version so the best option is easy find."], "k": 3, "w": "Keeping a clean library requires version control and removing redundant drafts. Distractors create clutter, waste work by deleting everything or circulate outdated prompt versions."}, {"i": "D2.4-L3-c", "c": "D2.4", "l": 3, "f": "c", "cl": "I update my prompt library as tools evolve.", "s": "What keeps a professional prompt library genuinely useful over a long period?", "o": ["Keeping the exact same phrasing regardless of model software updates.", "Adding hundreds of random prompts found on public internet forums.", "Modifying prompts when better techniques or new model versions arrive.", "Restricting library access to only one specific brand of chatbot."], "k": 2, "w": "Prompt libraries must adapt to changing model behaviors and context windows. Distractors advocate for rigid phrasing, hoarding low-quality prompts or limiting platform compatibility."}, {"i": "D2.4-L4-a", "c": "D2.4", "l": 4, "f": "a", "cl": "I document a shared prompt so others can use it right.", "s": "You share prompts with a hobby group. What makes them usable by others?", "o": ["List the advanced prompt engineering rules used to build the template.", "Add a short note on what each does and how to fill the blanks.", "Provide a generic list of alternative keywords to try if it fails.", "Explain the history of the model software updates over the past year."], "k": 1, "w": "Documentation helps collaborators deploy shared prompts successfully. Distractors focus on technical complexity, theoretical model updates or generic keywords rather than practical template usage notes."}, {"i": "D2.4-L4-b", "c": "D2.4", "l": 4, "f": "b", "cl": "I test a shared prompt before others rely on it.", "s": "How do you ensure a shared prompt library is reliable for a group?", "o": ["Check that the total word count of the file matches template guidelines.", "Include tested prompts with a clear purpose and an example input.", "Select prompts that feature complex vocabulary to sound highly professional.", "Pick prompts from famous online repositories that have many user likes."], "k": 1, "w": "Testing assets ensures group workflows remain reliable and repeatable. Distractors trust metrics like external popularity, large file lengths or sophisticated vocabulary rather than verifiable internal tests."}, {"i": "D2.4-L4-c", "c": "D2.4", "l": 4, "f": "c", "cl": "I fix a shared prompt that keeps being misused.", "s": "A shared prompt keeps getting misused by the group. Best response?", "o": ["Inform the group that they need to read basic AI user guides.", "Clarify its purpose and add a usage example.", "Delete the prompt from the shared asset folder.", "Switch the whole team to a different chatbot tool."], "k": 1, "w": "Structural confusion requires simplification and practical examples. Distractors show bad leadership habits like blaming the users, deleting assets or switching platforms unnecessarily."}, {"i": "D3.1-L1-a", "c": "D3.1", "l": 1, "f": "a", "cl": "I know AI tools differ and are not all equal.", "s": "Which statement shows real awareness about AI tools?", "o": ["All available chatbot tools use identical source databases and logic.", "Different tools suit different tasks and vary in how much you can trust them.", "Every computer tool online handles your personal data with complete safety.", "Any mobile app can answer factual questions with perfect numerical accuracy."], "k": 1, "w": "Recognizing the distinct capabilities and safety variations of tools is an early milestone. Distractors falsely assume all tools are equal, completely accurate or uniformly safe."}, {"i": "D3.1-L1-b", "c": "D3.1", "l": 1, "f": "b", "cl": "I can tell a trustworthy tool source from a risky one.", "s": "You want to try an AI tool. Which is the safer way to find one?", "o": ["Click a flashy popup advertisement while browsing an entertainment website.", "Download a random software link shared in an unverified group chat.", "Choose a well-known, reputable tool you can find independently.", "Install the first search result that claims to be completely free."], "k": 2, "w": "Independent discovery of reputable brands reduces cybersecurity risks. Distractors trust aggressive advertising, unverified text links or free price models, which often signal malware or scams."}, {"i": "D3.1-L1-c", "c": "D3.1", "l": 1, "f": "c", "cl": "I check what a tool does with my data before using it.", "s": "Before uploading personal photos to a new AI app, the first sensible question is?", "o": ["Will this specific photo editing app make me look highly professional?", "Can this photo tool process my uploaded files in under ten seconds?", "Does this application offer a premium subscription with advanced filter features?", "Is it reputable and clear about what it does with my images?"], "k": 3, "w": "Data privacy checks are crucial before uploading sensitive user content like photos. Distractors represent superficial concerns like processing speed, premium features or visual aesthetics."}, {"i": "D3.1-L2-a", "c": "D3.1", "l": 2, "f": "a", "cl": "I use an AI tool for a real everyday task, with a check.", "s": "You often skim long emails. Sensible real use of AI?", "o": ["Let a chatbot read them and delete any message it marks as boring.", "Allow a tool to auto-reply to your boss using its own judgment.", "Use an unverified app to process confidential emails without reading them.", "Use a trusted tool to draft summaries, then glance to confirm."], "k": 3, "w": "Everyday tool use must balance automation with manual verification. Distractors delegate critical decisions blindly, trust unverified platforms or let tools delete emails without human oversight."}, {"i": "D3.1-L2-b", "c": "D3.1", "l": 2, "f": "b", "cl": "I try a new tool on something low-stakes first.", "s": "Best first task to test a new AI tool on?", "o": ["Calculate your family tax return details for the government.", "Summarize a high-stakes legal document for a pending court case.", "Write a specific medical diagnosis for an ongoing physical illness.", "A low-stakes task like drafting a shopping list."], "k": 3, "w": "Testing new tools on low-stakes data limits the impact of errors or hallucinations. Distractors involve critical financial, medical or legal tasks where mistakes cause major harm."}, {"i": "D3.1-L2-c", "c": "D3.1", "l": 2, "f": "c", "cl": "I get comfortable with one tool before adding more.", "s": "You found one AI tool that works well. Reasonable next step?", "o": ["Get comfortable with it before adding another.", "Install five similar applications to compare them simultaneously.", "Delete the working tool and search for a newer release.", "Stop using computer software entirely to avoid future issues."], "k": 0, "w": "Mastering a single tool provides a strong baseline before expanding. Distractors cause choice overload by adding too many tools, deleting working setups or abandoning technology."}, {"i": "D3.1-L3-a", "c": "D3.1", "l": 3, "f": "a", "cl": "I match the tool's strength to what the task needs.", "s": "You need an image made, not text. Best tool choice?", "o": ["A standard text summarization tool.", "An image-generation tool.", "A financial spreadsheet tool.", "A basic code writing tool."], "k": 1, "w": "Selection should align with the core functional output of the asset. Distractors utilize inappropriate text, data or code models that cannot generate the required graphic format."}, {"i": "D3.1-L3-b", "c": "D3.1", "l": 3, "f": "b", "cl": "I pick a tool that can reach current information.", "s": "You need today's live information for a decision. Which tool fits?", "o": ["A tool with a fixed three-year-old knowledge cut-off.", "A basic offline text formatting application.", "An image creation model with no network access.", "A tool with live web search."], "k": 3, "w": "Real-time queries require active web connections. Distractors rely on offline programs, image engines or outdated databases that cannot access the live internet."}, {"i": "D3.1-L3-c", "c": "D3.1", "l": 3, "f": "c", "cl": "I choose by fit, not by habit or hype.", "s": "What should actually guide which tool you reach for?", "o": ["Following the latest trending topics on social media platforms.", "Selecting the most expensive subscription option available online.", "Sticking with whatever old system you used five years ago.", "Matching the tool's strength to the task at hand."], "k": 3, "w": "Integrators match tool capabilities directly to current project constraints. Distractors choose software based on social media trends, high prices or rigid personal habits."}, {"i": "D3.1-L4-a", "c": "D3.1", "l": 4, "f": "a", "cl": "I choose shared tools by fit, ease and data handling.", "s": "Picking an AI tool for your family to share, strongest criterion?", "o": ["The tool that features the highest number of advanced coding settings.", "The application that has the most aggressive online marketing campaign.", "Fit for their tasks, easy to use and clear about data handling.", "The platform that allows the largest number of anonymous user accounts."], "k": 2, "w": "Selecting tools for groups requires balancing functional utility, usability and data security. Distractors focus on aggressive advertising, niche developer settings or anonymous account creation."}, {"i": "D3.1-L4-b", "c": "D3.1", "l": 4, "f": "b", "cl": "I roll out tools with simple defaults and a short guide.", "s": "Rolling a tool out to less-confident users, best first step?", "o": ["Set it up with simple defaults and a short how-to.", "Hand them a massive technical manual detailing the underlying algorithm.", "Provide the software link without instructions to encourage independent trial.", "Require them to pass a complex engineering exam before getting access."], "k": 0, "w": "Successful adoption patterns rely on clear, minimal onboarding artifacts. Distractors overcomplicate onboarding with massive instruction manuals, technical exams or zero guidance."}, {"i": "D3.1-L4-c", "c": "D3.1", "l": 4, "f": "c", "cl": "I respond to confusion by simplifying, not blaming.", "s": "A tool you rolled out is confusing people. Best response?", "o": ["Warn the group that they are failing to pay attention to instructions.", "Replace the system with a more complex programming framework.", "Tell the group to figure it out using online video tutorials.", "Simplify the setup and give a clear example task."], "k": 3, "w": "Creators address adoption hurdles by lowering friction and providing concrete examples. Distractors alienate users by blaming them, ignoring requests or adding technical layer complexity."}, {"i": "D3.2-L1-a", "c": "D3.2", "l": 1, "f": "a", "cl": "I can spot an AI feature inside an everyday app.", "s": "Which option is most likely an AI feature inside an app you already use?", "o": ["A button that lets you change the background color of your document profile.", "A feature that lets you download a backup copy of your personal data files.", "A menu that allows you to sort your inbox messages by date received.", "A button that summarizes a long chat thread or suggests a text reply."], "k": 3, "w": "Common embedded AI features handle tasks like summarization and drafting text. Distractors represent standard non-AI software utilities like sorting, changing themes or downloading files."}, {"i": "D3.2-L1-b", "c": "D3.2", "l": 1, "f": "b", "cl": "I can spot an AI feature inside an everyday app.", "s": "Your email program gives you three quick, full responses to click and send. What is doing this?", "o": ["A basic spell checker that corrects your existing words.", "A standard system update to your device operating software.", "An internet search engine running a background web query.", "A built-in AI writing feature inside your email app."], "k": 3, "w": "Contextual text generation is a classic example of an embedded AI feature. Distractors attribute the text creation to unrelated standard functions like spell checking, system updates or web searches."}, {"i": "D3.2-L1-c", "c": "D3.2", "l": 1, "f": "c", "cl": "I know AI help can live inside tools I already have.", "s": "Where can you often find AI help without downloading a separate app?", "o": ["On popular social media video pages that show software tutorials.", "Inside tools you already use, as built-in features.", "On public tech forums where users share custom coding files.", "Inside printed instructional manuals that come with new computers."], "k": 1, "w": "Many daily apps now feature native, built-in AI assistance. Distractors suggest external learning resources like videos, forums or printed manuals rather than recognizing embedded tools."}, {"i": "D3.2-L2-a", "c": "D3.2", "l": 2, "f": "a", "cl": "I use a summarize feature, then confirm it.", "s": "You have a long group chat to catch up on. Practical use of an in-tool feature?", "o": ["Use the summarize feature, then skim to confirm the key points.", "Use the summarize feature and copy it without reading the text.", "Avoid the summarize feature because it takes too long to load.", "Run the summarize feature five times to ensure it has no bugs."], "k": 0, "w": "Efficient use balances automated summaries with a quick human check. Distractors show careless blind trust, complete avoidance of the tool or excessive, repetitive generation."}, {"i": "D3.2-L2-b", "c": "D3.2", "l": 2, "f": "b", "cl": "I use a suggested draft, then make it mine.", "s": "You want to write a quick, warm reply. Good use of an in-tool draft feature?", "o": ["Use it as a starting point, then edit it to sound like you.", "Send the draft immediately so you look highly efficient to others.", "Ignore the feature because automated text is always rude and cold.", "Copy the draft into a blank document and rewrite every single word."], "k": 0, "w": "Suggested drafts should be personalized rather than sent raw or totally discarded. Distractors represent sending unedited text, avoiding the feature entirely or wasting time completely rewriting it."}, {"i": "D3.2-L2-c", "c": "D3.2", "l": 2, "f": "c", "cl": "I always read an auto-draft before it goes out.", "s": "What is the best habit when using any in-tool draft feature?", "o": ["Read and adjust the text before sending it to anyone.", "Trust the text completely since built-in software rarely makes mistakes.", "Send the text immediately to keep your response time low.", "Print the text out to check the alignment and fonts."], "k": 0, "w": "Checking automated drafts prevents sending inappropriate or inaccurate text. Distractors display blind trust in built-in tools, prioritizing speed over accuracy or focusing on irrelevant formatting checks."}, {"i": "D3.2-L3-a", "c": "D3.2", "l": 3, "f": "a", "cl": "I weave AI in where it helps, not everywhere.", "s": "Which choice shows AI sensibly woven into a routine, not overused?", "o": ["Letting a chatbot draft every single personal message you send.", "Using it for repetitive drafting and summaries, doing the judgment yourself.", "Avoiding all computer tools because manual work is always safer.", "Using four different chatbots simultaneously to write one short email."], "k": 1, "w": "Integrators apply AI to routine work while retaining ultimate creative and analytical control. Distractors show extreme habits like total automation, complete technology rejection or chaotic over-tooling."}, {"i": "D3.2-L3-b", "c": "D3.2", "l": 3, "f": "b", "cl": "I keep decisions and final checks with me.", "s": "You use AI daily to draft text and plan schedules. What is a healthy boundary?", "o": ["Let the tool automatically send out your weekly project plans.", "Stop reading the original documents to save your energy.", "Allow the chatbot to prioritize your daily work task list.", "Keep the ultimate decisions and final checks for yourself."], "k": 3, "w": "Maintaining a human-in-the-loop approach ensures accountability in AI-assisted workflows. Distractors give away control by letting the tool send plans, prioritize tasks or replace reading entirely."}, {"i": "D3.2-L3-c", "c": "D3.2", "l": 3, "f": "c", "cl": "I can tell when AI actually helps versus just looks busy.", "s": "Which choice is a real sign that AI is improving your workflow?", "o": ["You spend hours writing highly complex prompts every single morning.", "It reliably saves time on repetitive parts you still verify.", "Your chatbot generates thousands of pages of unread summary text.", "You installed ten new browser extensions today to look modern."], "k": 1, "w": "AI utility is measured by verified time savings on repetitive tasks. Distractors confuse true productivity with looking busy, such as over-engineering prompts, hoarding unread text or installing endless tools."}, {"i": "D3.2-L4-a", "c": "D3.2", "l": 4, "f": "a", "cl": "I set up shared features to include human review steps.", "s": "You add AI summaries to a shared family planning document. What is the best design?", "o": ["Let the tool post summaries directly without anyone looking at them.", "Disable the feature entirely so family members must read everything manually.", "Force users to pass a typing test before they can view summaries.", "Generate a summary that a person reviews before others rely on it."], "k": 3, "w": "Creators design collaborative tools with a built-in human verification step. Distractors allow unverified text to propagate, remove the feature entirely or invent arbitrary user hurdles."}, {"i": "D3.2-L4-b", "c": "D3.2", "l": 4, "f": "b", "cl": "I keep it clear which shared content is AI-assisted.", "s": "You add an AI feature to a shared group tool. How do you protect group trust?", "o": ["Be clear which content is AI-assisted, with someone owning accuracy.", "Hide the AI feature so group members think you write everything.", "Ban any discussion regarding the use of technology in the group.", "Assume everyone knows which parts are computer-generated without clear labels."], "k": 0, "w": "Transparency about AI assistance preserves trust and accountability in group settings. Distractors rely on deceptive concealment, banning open communication or assuming implicit user knowledge."}, {"i": "D3.2-L4-c", "c": "D3.2", "l": 4, "f": "c", "cl": "I add a light review step for occasional errors.", "s": "A shared AI feature makes an occasional wrong summary. What is the best safeguard?", "o": ["Delete the entire shared document library to avoid future errors.", "Introduce a quick human review before a summary is acted on.", "Tell the group members that errors are impossible with modern software.", "Ignore the errors because family planning has very low stakes."], "k": 1, "w": "A lightweight verification step mitigates occasional errors without destroying utility. Distractors show extreme reactions like deleting assets, denying errors exist or ignoring known quality issues."}, {"i": "D3.3-L1-a", "c": "D3.3", "l": 1, "f": "a", "cl": "I stick to tools that are allowed for a shared task.", "s": "Your group has a rule to use only approved AI tools. What should you do?", "o": ["Use any tool you find online if it seems faster.", "Use the approved ones, or ask before trying another.", "Avoid using any technology so you never break rules.", "Secretly use unapproved programs and hide the final results."], "k": 1, "w": "Compliance means using approved assets or seeking permission for new ones. Distractors promote rule-breaking for speed, covert tool use or abandoning tech due to fear of rules."}, {"i": "D3.3-L1-b", "c": "D3.3", "l": 1, "f": "b", "cl": "I know approval rules protect shared data privacy.", "s": "Why might an organization approve only certain specific AI tools?", "o": ["To ensure all team members use software with a dark interface theme.", "To make daily tasks more complicated and slow down overall project progress.", "To protect data and stay within rules and licensing terms.", "To prevent individual employees from learning new digital skills independently."], "k": 2, "w": "Tool restrictions exist to maintain security and regulatory compliance. Distractors misinterpret governance as aesthetic preference, intentional operational friction or a limitation on personal skill growth."}, {"i": "D3.3-L1-c", "c": "D3.3", "l": 1, "f": "c", "cl": "I check before using an unfamiliar tool for shared work.", "s": "You are unsure whether a specific tool is allowed for a shared task. What is your best move?", "o": ["Use the tool anyway and see if anyone notices later.", "Check whether it is approved before using it.", "Assume it is fine because a famous influencer recommended it.", "Tell the entire group that the tool is officially cleared."], "k": 1, "w": "Checking approval status beforehand prevents compliance issues on collaborative projects. Distractors show reckless behaviors like hiding tool usage, trusting influencers or lying about tool status."}, {"i": "D3.3-L2-a", "c": "D3.3", "l": 2, "f": "a", "cl": "I confirm a tool is cleared before putting real data in.", "s": "You want to paste group data into a new online tool. What is a sensible check?", "o": ["Verify that the tool has a colorful and modern user interface.", "Check if the tool allows you to select custom text fonts.", "Ensure the tool is free to use for individual accounts.", "Confirm it is on the approved list or cleared first."], "k": 3, "w": "Checking official authorization protects group data before exposure. Distractors focus on cosmetic features like interface design and fonts, or financial traits like free access tiers."}, {"i": "D3.3-L2-b", "c": "D3.3", "l": 2, "f": "b", "cl": "I pause on handy but unvetted suggestions.", "s": "A colleague suggests a handy but unvetted tool for your shared data. What do you do?", "o": ["Check its approval status before using real data.", "Adopt it immediately because your colleague is a close friend.", "Reject the suggestion and report your colleague for rule violations.", "Use it only late at night when system tracking is low."], "k": 0, "w": "Unvetted tools require verification before handling real project data. Distractors prioritize friendship over safety, overreact with immediate punishment or suggest sneaking around monitoring systems."}, {"i": "D3.3-L2-c", "c": "D3.3", "l": 2, "f": "c", "cl": "I know what actually counts as an approved tool.", "s": "What is the best evidence that an AI tool is okay to use for a shared task?", "o": ["Your favorite tech blog wrote a positive review about it.", "It is on the approved list or has been cleared.", "The application website claims it is completely safe for everyone.", "Three people in your social media feed used it yesterday."], "k": 1, "w": "Formal clearance or an official list is the only true proof of tool approval. Distractors mistake external hype, marketing text or peer usage for official organizational policy."}, {"i": "D3.3-L3-a", "c": "D3.3", "l": 3, "f": "a", "cl": "I understand what tool approval is really protecting.", "s": "What is the main reason tool approval matters when handling shared data?", "o": ["It ensures the group saves maximum storage space on local drives.", "It tracks exactly how many hours each team member spends working.", "It forces everyone to use identical screen layouts and color themes.", "It monitors where data goes, how it is used and licensing terms."], "k": 3, "w": "Governance ensures data security, clear usage rights and strict license compliance. Distractors misinterpret governance as storage optimization, time tracking or visual uniformity."}, {"i": "D3.3-L3-b", "c": "D3.3", "l": 3, "f": "b", "cl": "I can name the main risk of an unapproved tool.", "s": "Which risk does using an unapproved AI tool most raise for a group?", "o": ["The tool might require you to update your internet browser.", "The software could change the background font of your document.", "Sensitive data leaving safe hands or breaching tool terms.", "The application might send too many notification emails to you."], "k": 2, "w": "Unvetted tools risk data leaks and severe compliance violations. Distractors downplay the issue by highlighting trivial inconveniences like browser updates, font changes or extra emails."}, {"i": "D3.3-L3-c", "c": "D3.3", "l": 3, "f": "c", "cl": "I know popular tools can still violate privacy rules.", "s": "A tool is free and widely used but unvetted for private data. Sound judgment?", "o": ["Use it freely because millions of global users have proven it is safe.", "Use it only for small tasks since low text volume eliminates data risk.", "Avoid it entirely because popular tools always contain malicious software tracking code.", "Free and popular do not mean cleared; check its data handling first."], "k": 3, "w": "Popularity and price do not equal compliance or security authorization. Distractors assume popularity guarantees safety, underestimate data risk based on volume or assume all popular software contains malware."}, {"i": "D3.3-L4-a", "c": "D3.3", "l": 4, "f": "a", "cl": "I help establish the criteria for approved group tools.", "s": "Helping a club decide on approved AI tools, strongest criterion?", "o": ["Choosing the platform that features the most aggressive online marketing campaign.", "Clear data handling, reliability and fit for the group's tasks.", "Selecting the absolute newest application available on public mobile app stores.", "Requiring the software to have anonymous user account creation features."], "k": 1, "w": "Governance criteria must prioritize security, stability and functional alignment. Distractors emphasize superficial marketing, recency or anonymity over operational fit and data safety."}, {"i": "D3.3-L4-b", "c": "D3.3", "l": 4, "f": "b", "cl": "I regularly update the approved group tool list.", "s": "What keeps an approved tool list genuinely useful over time?", "o": ["Keeping the exact same software options regardless of technological change.", "Reviewing it systematically as tools and group needs change.", "Adding every new chatbot application that appears on social media.", "Restricting the list to tools from only one specific vendor company."], "k": 1, "w": "Modern tech governance requires iterative assessment as systems evolve. Distractors advocate for rigid static lists, hoarding unvetted apps or vendor lock-in."}, {"i": "D3.3-L4-c", "c": "D3.3", "l": 4, "f": "c", "cl": "I evaluate new tool clearance requests systematically.", "s": "Someone wants a tool added to the approved list. Best process?", "o": ["Check its data handling and fit, then decide.", "Add it immediately to encourage team innovation and speed.", "Reject it instantly to maintain complete file system security.", "Ask a colleague if they personally like using the application."], "k": 0, "w": "Reviewing data handling and task alignment ensures consistent policy enforcement. Distractors represent impulsive approval, complete risk aversion or relying on casual personal opinions."}, {"i": "D4.1-L1-a", "c": "D4.1", "l": 1, "f": "a", "cl": "I can read what a trend line shows.", "s": "A trend line on your savings chart climbs steadily from January to June. It shows?", "o": ["Your total monthly expenses outpaced your total earnings.", "Your bank account was closed during those specific months.", "You saved an identical amount of money every single day.", "Savings rose consistently over those six months."], "k": 3, "w": "A basic upward line indicates an increase in a variable over time. Distractors misinterpret the trend as a negative financial outcome, account closure or a perfectly linear daily rate."}, {"i": "D4.1-L1-b", "c": "D4.1", "l": 1, "f": "b", "cl": "I can read proportions from a chart.", "s": "A family budget pie chart shows 'housing 50%'. That means housing is?", "o": ["Half of the total spending shown on the chart.", "The single least expensive part of the monthly budget.", "Double the amount spent on all other items combined.", "Exactly fifty dollars of your total monthly household bills."], "k": 0, "w": "A 50% pie slice represents exactly half of the total dataset. Distractors confuse percentages with raw dollar amounts or reverse the metric to mean the smallest or absolute largest component."}, {"i": "D4.1-L1-c", "c": "D4.1", "l": 1, "f": "c", "cl": "I can compare data bars on a chart.", "s": "March's bar is twice as tall as February's on a spending chart. Sensible read?", "o": ["March spending was exactly identical to February spending.", "February spending was double the amount spent in March.", "March spending was about double February's total spending.", "No money was spent during the month of February."], "k": 2, "w": "Bar heights communicate proportional relationships directly. Distractors misinterpret a double height as equality, invert the relationship or assume a shorter bar means zero activity."}, {"i": "D4.1-L2-a", "c": "D4.1", "l": 2, "f": "a", "cl": "I understand where two chart lines cross.", "s": "On a chart tracking income and spending, the two lines cross in April. That point means?", "o": ["Income and spending were equal that month.", "Spending was double the income received that month.", "The account balance reached zero during that month.", "No transactions occurred during the month of April."], "k": 0, "w": "The intersection of two lines on a shared scale denotes identical values. Distractors assume an intersection means double value, absolute zero baseline or a lack of activity."}, {"i": "D4.1-L2-b", "c": "D4.1", "l": 2, "f": "b", "cl": "I can spot a misleading chart axis.", "s": "A bar chart's vertical axis starts at 90 instead of 0, exaggerating differences. Careful read?", "o": ["The cut axis exaggerates small differences; check the real numbers.", "The data values are completely false and should be discarded.", "The tallest bar represents a massive crisis for the project.", "The chart is perfectly formatted for sharing with senior leadership."], "k": 0, "w": "Truncating the vertical axis alters visual proportions dramatically. Distractors assume the underlying data is completely fraudulent, overreact to the visual distortion or endorse the misleading design."}, {"i": "D4.1-L2-c", "c": "D4.1", "l": 2, "f": "c", "cl": "I can tell temporary dips from real declines.", "s": "A steady trend line dips for one month, then returns to normal. Best interpretation?", "o": ["The entire project is experiencing a total system failure.", "The dataset has corrupted and needs immediate recalculation.", "The chart proves a permanent downward trend has begun.", "A temporary dip within an overall steady pattern."], "k": 3, "w": "Isolated fluctuations within a stable series indicate brief anomalies rather than structural changes. Distractors overreact by diagnosing failure, data corruption or permanent decay."}, {"i": "D4.1-L3-a", "c": "D4.1", "l": 3, "f": "a", "cl": "I investigate data outliers instead of ignoring them.", "s": "Your monthly spend is steady except for one massive spike. Best first move?", "o": ["Change the chart style to hide the spike from view.", "Delete that month's data entry to fix the average.", "Ask what happened that month to cause the spike.", "Ignore it because a single month does not matter long term."], "k": 2, "w": "Integrators interrogate variances to discover root causes. Distractors demonstrate poor analytical habits like cosmetic concealment, data manipulation or ignoring valuable data signals."}, {"i": "D4.1-L3-b", "c": "D4.1", "l": 3, "f": "b", "cl": "I evaluate the data spread, not just averages.", "s": "A weekly productivity average looks normal, but one week was extreme. Sound analysis?", "o": ["Trust the average since it simplifies your final summary report.", "Look at the spread, since the average can hide extremes.", "Delete the extreme week to make the data look clean.", "Assume every single week matched the average number perfectly."], "k": 1, "w": "Averages mask underlying volatility and extreme variance. Distractors show analytical shortcuts like over-relying on basic means, removing inconvenient data outliers or assuming zero variance."}, {"i": "D4.1-L3-c", "c": "D4.1", "l": 3, "f": "c", "cl": "I do not confuse correlation with causation.", "s": "Ice cream sales and sunburns both rise rapidly in summer. Careful conclusion?", "o": ["Eating ice cream directly causes skin tissue damage.", "Sunburns create a biological craving for cold dairy products.", "The chart data must be faulty because the items are unrelated.", "Both rise with hot weather; moving together does not prove cause."], "k": 3, "w": "Correlation between variables does not imply a direct cause-and-effect relationship. Distractors invent absurd direct causes or reject valid observations because they misunderstand shared variables."}, {"i": "D4.1-L4-a", "c": "D4.1", "l": 4, "f": "a", "cl": "I present data honestly so others can act.", "s": "You share a budget summary others will act on. Best practice?", "o": ["Adjust the numbers slightly to make the project look successful.", "Show the figures, their source and the time period clearly.", "Use highly complex mathematical terms to discourage deep questions.", "Hide any minor expenses that might cause group discussions."], "k": 1, "w": "Honest data publication requires explicit context, origins and timelines. Distractors display deceptive practices like data smoothing, obfuscation or omission to avoid scrutiny."}, {"i": "D4.1-L4-b", "c": "D4.1", "l": 4, "f": "b", "cl": "I know what makes shared data trustworthy.", "s": "What structural element most makes a shared analysis trustworthy?", "o": ["Incorporating professional color palettes and custom infographic icons.", "Writing a very long introduction paragraph praising the team.", "A clear data source, explicit method and honest axes.", "Using complex financial code formulas that look advanced."], "k": 2, "w": "Trust stems from provenance transparency, clean methodology and objective visualization. Distractors prize cosmetic graphics, flattering introductory remarks or intimidating code complexity over transparency."}, {"i": "D4.1-L4-c", "c": "D4.1", "l": 4, "f": "c", "cl": "I design charts so they cannot be misread.", "s": "A reader could easily misread your chart. Best fix before sharing?", "o": ["Remove all labels so readers focus only on visual shapes.", "Label the axes, note the source and state the takeaway.", "Add three more datasets to the chart to provide context.", "Tell the reader that the chart is simple to understand."], "k": 1, "w": "Clear notation and explicit callouts prevent misinterpretation. Distractors worsen readability by removing labels, causing visual clutter with too much data or using dismissive statements."}, {"i": "D4.2-L1-a", "c": "D4.2", "l": 1, "f": "a", "cl": "I verify AI figures before using them.", "s": "An AI tool gives you a calculation for an important decision. Right stance?", "o": ["Trust it completely because computer calculations are always error-free.", "Reject it instantly because chatbots cannot process numeric values.", "Check it against a reliable source before relying on it.", "Use it only if the chatbot confirms it is correct twice."], "k": 2, "w": "AI outputs require external confirmation before high-stakes implementation. Distractors represent absolute blind trust, total digital tool rejection or trusting a chatbot's internal self-validation."}, {"i": "D4.2-L1-b", "c": "D4.2", "l": 1, "f": "b", "cl": "I know AI numbers can be factually wrong.", "s": "Which statement is true about numbers an AI model produces?", "o": ["They can be wrong and are worth verifying when they matter.", "They are guaranteed to be correct if generated by paid apps.", "They represent absolute truth because computers do not make math mistakes.", "They are always random hallucinations that have no utility."], "k": 0, "w": "Large language models can hallucinate or distort numbers easily. Distractors show false beliefs like premium app infallibility, general computer infallibility or total tool dismissal."}, {"i": "D4.2-L1-c", "c": "D4.2", "l": 1, "f": "c", "cl": "I confirm AI data before public sharing.", "s": "What is the best habit for an AI statistic you want to share?", "o": ["Share it immediately to show you have fast research skills.", "Add a disclaimer stating you did not read the text closely.", "Assume it is correct if it matches your personal opinion.", "Confirm the statistic against a primary source before sharing."], "k": 3, "w": "Responsible sharing requires checking facts at the source first. Distractors prioritize dissemination speed, try to avoid accountability with weak disclaimers or rely on confirmation bias."}, {"i": "D4.2-L2-a", "c": "D4.2", "l": 2, "f": "a", "cl": "I understand where two chart lines cross.", "s": "On a chart tracking income and spending, the two lines cross in April. That point means?", "o": ["Income and spending were equal that month.", "Spending was double the income received that month.", "The account balance reached zero during that month.", "No transactions occurred during the month of April."], "k": 0, "w": "The intersection of two lines on a shared scale denotes identical values. Distractors assume an intersection means double value, absolute zero baseline or a lack of activity."}, {"i": "D4.2-L2-b", "c": "D4.2", "l": 2, "f": "b", "cl": "I can spot a misleading chart axis.", "s": "A bar chart's vertical axis starts at 90 instead of 0, exaggerating differences. Careful read?", "o": ["The chart is perfectly formatted for sharing with senior leadership.", "The data values are completely false and should be discarded.", "The tallest bar represents a massive crisis for the project.", "The cut axis exaggerates small differences; check the real numbers."], "k": 3, "w": "Truncating the vertical axis alters visual proportions dramatically. Distractors assume the underlying data is completely fraudulent, overreact to the visual distortion or endorse the misleading design."}, {"i": "D4.2-L2-c", "c": "D4.2", "l": 2, "f": "c", "cl": "I can tell temporary dips from real declines.", "s": "A steady trend line dips for one month, then returns to normal. Best interpretation?", "o": ["The entire project is experiencing a total system failure.", "A temporary dip within an overall steady pattern.", "The chart proves a permanent downward trend has begun.", "The dataset has corrupted and needs immediate recalculation."], "k": 1, "w": "Isolated fluctuations within a stable series indicate brief anomalies rather than structural changes. Distractors overreact by diagnosing failure, data corruption or permanent decay."}, {"i": "D4.2-L3-a", "c": "D4.2", "l": 3, "f": "a", "cl": "I check an official source for official figures.", "s": "An AI tool states a specific local tax rate for your annual budget. Best validation?", "o": ["Accept the rate because chatbots process public policy documents flawlessly.", "Use the figure if it matches the rate you paid five years ago.", "Check the official tax authority's stated rate on their website.", "Paste the number into a different chatbot to see if it agrees."], "k": 2, "w": "Official financial data must be verified directly through the governing agency. Distractors trust AI infallibility, obsolete personal memory or recursive validation using another chatbot."}, {"i": "D4.2-L3-b", "c": "D4.2", "l": 3, "f": "b", "cl": "I compare health data to reliable references.", "s": "An AI tool gives you a specific nutrition figure for a dietary plan. Strongest check?", "o": ["Trust the figure since the tool phrased the response very professionally.", "Use the figure if it aligns with a trending social media post.", "Compare it against the product label or an official health database.", "Regenerate the prompt to see if the tool outputs the same math."], "k": 2, "w": "Health data requires validation against primary labels or verified institutional databases. Distractors mistake professional tone, popular social media trends or repetitive prompt generation for accurate proof."}, {"i": "D4.2-L3-c", "c": "D4.2", "l": 3, "f": "c", "cl": "I know what genuine data validation requires.", "s": "What constitutes proper validation of a specific AI data claim?", "o": ["Ensuring the output text is completely free of any spelling mistakes.", "Confirming the data matches your personal opinions on the topic.", "Confirming it against an independent, authoritative source of information.", "Checking that the chatbot responded to your prompt within five seconds."], "k": 2, "w": "Validation requires independent grounding against an authoritative source. Distractors confuse verification with surface-level qualities like spelling correctness, speed or individual confirmation bias."}, {"i": "D4.2-L4-a", "c": "D4.2", "l": 4, "f": "a", "cl": "I build routine spot-checks into data workflows.", "s": "You rely on AI tools to pull data figures regularly for work. Best quality practice?", "o": ["Trust the figures blindly to keep your reporting speed as high as possible.", "Stop using the tools entirely because manual data pulling is always flawless.", "Spot-check a sample against source data on a recurring schedule.", "Require a coworker to proofread the font style of the final report."], "k": 2, "w": "Professional creators establish systematic, sampled audits to monitor data pipeline quality. Distractors suggest unverified automation speed, total technology rejection or irrelevant cosmetic reviews."}, {"i": "D4.2-L4-b", "c": "D4.2", "l": 4, "f": "b", "cl": "I establish repeatable checks against ground truth.", "s": "What turns 'hoping data is right' into 'knowing data is right' when using AI?", "o": ["Asking the chatbot to promise that its output text is completely accurate.", "Upgrading your software subscription to the most expensive premium tier available.", "A repeatable check of the data against verified ground truth.", "Copying the data into three different layout templates to see it clearly."], "k": 2, "w": "Factual confidence requires objective, repeatable measurement against an established baseline. Distractors incorrectly rely on conversational reassurance from the AI, premium pricing tiers or visual formatting variations."}, {"i": "D4.2-L4-c", "c": "D4.2", "l": 4, "f": "c", "cl": "I define specific sources of truth for data audits.", "s": "Designing an evaluation check for AI figures others use, strongest framework element?", "o": ["A long training manual explaining the general history of cloud computing.", "A defined source of truth and a set sampling check routine.", "A rule requiring employees to use advanced vocabulary in their prompts.", "An automated system that deletes any summary over two paragraphs long."], "k": 1, "w": "Quality control systems require a clear benchmark source and an explicit operational audit rule. Distractors focus on generic historical education, artificial prompt word requirements or arbitrary length cut-offs."}, {"i": "D4.3-L1-a", "c": "D4.3", "l": 1, "f": "a", "cl": "I know web sources vary in reliability.", "s": "You read a dramatic medical claim on an internet forum. Sensible stance?", "o": ["Believe it instantly because public internet posts reflect real human experiences.", "Discard it immediately because all medical info online is completely false.", "Some sources are more trustworthy; consider who wrote the content.", "Share it with your friends to see if they find it interesting."], "k": 2, "w": "Evaluating information requires assessing the origin and expertise of the author. Distractors show absolute trust in public posts, absolute cynicism toward online content or reckless sharing without checking."}, {"i": "D4.3-L1-b", "c": "D4.3", "l": 1, "f": "b", "cl": "I can identify baseline source reliability signals.", "s": "Which indicator suggests an online source is generally more reliable?", "o": ["The webpage features many colorful flashing graphic design elements.", "The article includes an anonymous commentary section at the bottom.", "The content claims to reveal an absolute secret nobody else knows.", "A known, accountable author or established organization publishes the work."], "k": 3, "w": "Accountability and transparent authorship are primary signals of source credibility. Distractors substitute superficial traits like flashy graphics, anonymous discussions or sensational secret claims."}, {"i": "D4.3-L1-c", "c": "D4.3", "l": 1, "f": "c", "cl": "I treat unsourced dramatic claims with caution.", "s": "A dramatic news claim online features no author profile and no source links. You should?", "o": ["Treat it with caution until you can check it independently.", "Post it immediately before other websites cover the story.", "Assume it is true because a computer system formatted the text.", "Assume it is a complete joke and delete it from your device."], "k": 0, "w": "Unattributed, sensational claims require immediate skepticism and independent checking. Distractors exhibit poor behaviors like viral sharing, trusting automated formatting or making reactive assumptions without checking."}, {"i": "D4.3-L2-a", "c": "D4.3", "l": 2, "f": "a", "cl": "I evaluate publishing sources and consensus.", "s": "Prior to trusting a major claim in an article, which validation step provides the most reliable verification?", "o": ["Who published it and whether independent sources report the same fact.", "Checking if the article features high-resolution stock photography.", "Reading how many positive comments the post received on social media.", "Counting the total number of words used in the introductory text."], "k": 0, "w": "Verifying source intent and looking for cross-institutional consensus ensures reliability. Distractors focus on superficial attributes like high-quality photography, social media praise or word counts."}, {"i": "D4.3-L2-b", "c": "D4.3", "l": 2, "f": "b", "cl": "I resolve source discrepancies using authoritative data.", "s": "When two research sources directly contradict each other on a critical fact, what is the most logical next step?", "o": ["Pick the source that uses the most complex scientific vocabulary terms.", "Average the two numbers together to create a compromise figure.", "Flip a coin to choose one since research data is mostly subjective.", "Look for a reliable primary or authoritative source to resolve it."], "k": 3, "w": "Resolving contradictions requires ascending to primary, authoritative data. Distractors show analytical errors like trusting complex vocabulary, inventing meaningless averages or relying on random chance."}, {"i": "D4.3-L2-c", "c": "D4.3", "l": 2, "f": "c", "cl": "I maintain skepticism toward isolated unverified claims.", "s": "If an unverified piece of news appears exclusively on a single unknown blog, how should its credibility be assessed?", "o": ["Strong because small independent websites never publish false news stories.", "Strong because large media companies are likely hiding the true story.", "Weak because blogs are technically unable to host real text articles.", "Weak until a trustworthy, independent source corroborates the information."], "k": 3, "w": "Isolated reports on unvetted platforms remain untrustworthy until verified by known entities. Distractors assume niche isolation implies purity, indulge in media conspiracy theories or invent absurd technical limits."}, {"i": "D4.3-L3-a", "c": "D4.3", "l": 3, "f": "a", "cl": "I identify visual anomalies from digital editing.", "s": "A viral image shows subtle rendering errors around hands and distorted background text. What is the correct analytical judgment?", "o": ["The image is definitely authentic because the colors look vibrant.", "It may be AI-generated or edited; verify before believing it.", "The errors are caused by a standard camera lens smudge issue.", "The photo was taken in a foreign country with different alphabet signs."], "k": 1, "w": "Geometric anomalies and garbled text are classic signatures of algorithmic synthesis or manipulation. Distractors ignore visual evidence due to vibrant colors, invent lens excuse explanations or dismiss text anomalies as foreign scripts."}, {"i": "D4.3-L3-b", "c": "D4.3", "l": 3, "f": "b", "cl": "I can identify mass-produced AI text traits.", "s": "An article reads very generic, lists no author name and contains vague facts. Reasonable suspicion?", "o": ["It could be AI-mass-produced content; check its provenance carefully.", "It is a high-level executive summary written by an industry expert.", "The author hid their name to protect secret government data sources.", "The piece was written decades ago before modern names were recorded."], "k": 0, "w": "Bland, generic prose lacking specific attribution is a hallmark of programmatic content farms. Distractors misinterpret low-quality traits as expert brevity, espionage secrecy or bizarre historical limitations."}, {"i": "D4.3-L3-c", "c": "D4.3", "l": 3, "f": "c", "cl": "I judge modern sources by provenance and corroboration.", "s": "What is the strongest way to judge a modern digital source's reliability?", "o": ["Its provenance, author accountability and independent corroboration.", "Its search engine ranking and how fast the webpage loads on mobile.", "The number of graphic design awards the website has won recently.", "How closely the written content aligns with your personal political beliefs."], "k": 0, "w": "Modern data literacy requires tracking chain-of-custody, clear accountability and multi-source consensus. Distractors rely on search optimization speed, graphic design awards or personal confirmation bias."}, {"i": "D4.3-L4-a", "c": "D4.3", "l": 4, "f": "a", "cl": "I teach others simple source-evaluation rules.", "s": "You are teaching a friend to vet online claims. What is the best short rule to give them?", "o": ["Check who said it, when, and whether trusted sources agree.", "Believe any article that includes a chart with numbers in it.", "Avoid reading news online completely to ensure absolute peace of mind.", "Trust whatever source has the largest number of social media followers."], "k": 0, "w": "Effective mentors reduce source evaluation to actionable metrics like provenance, recency and consensus. Distractors promote blind trust in charts, total information avoidance or trusting follower counts."}, {"i": "D4.3-L4-b", "c": "D4.3", "l": 4, "f": "b", "cl": "I promote mindful sharing habits for the AI era.", "s": "What is the best habit to pass on now that AI tools can mass-produce content instantly?", "o": ["Pause on striking content and confirm its origin before sharing.", "Share everything you read quickly to let your network decide.", "Report every article you see online as potential computer fraud.", "Only read printed physical books to avoid all digital information."], "k": 0, "w": "Mitigating programmatic misinformation requires friction, pausing to check origins before amplification. Distractors encourage unverified viral sharing, over-reporting all content as fraud or fleeing technology."}, {"i": "D4.3-L4-c", "c": "D4.3", "l": 4, "f": "c", "cl": "I establish practical verification guidelines for collaborative groups.", "s": "If a collaborative group continuously circulates unverified claims, what is the most constructive intervention?", "o": ["Ban all members who share unverified text from posting again.", "Replace the current online chat application with a paper system.", "Tell the group members that verification is too difficult to attempt.", "Introduce a quick check-before-share step with clear criteria."], "k": 3, "w": "Creators address group misinformation by designing a lightweight validation step into shared workflows. Distractors represent excessive punishments, absolute technology rejection or a passive acceptance of errors."}, {"i": "D4.4-L1-a", "c": "D4.4", "l": 1, "f": "a", "cl": "I organize files systematically for easy retrieval.", "s": "If you anticipate needing a specific document a month from now, which action ensures it remains accessible?", "o": ["Leave the document file sitting in your general downloads folder.", "Trust that your device background software will locate it instantly.", "Print the text out and place it somewhere on your desk.", "Save it with a clear name in a sensible folder."], "k": 3, "w": "Basic data management requires deliberate file naming and structured folder storage. Distractors rely on unorganized download queues, blind trust in search indexes or messy physical paperwork."}, {"i": "D4.4-L1-b", "c": "D4.4", "l": 1, "f": "b", "cl": "I mitigate data loss risks by maintaining backups.", "s": "If you currently possess only a single copy of high-value photographs, which strategy represents a responsible approach?", "o": ["Keep a backup copy somewhere safe.", "Delete the files after viewing them.", "Share the photos on public forums.", "Assume your phone never breaks down."], "k": 0, "w": "Maintaining duplicates in separate safe locations mitigates the risk of catastrophic data loss. Distractors advocate for data deletion, public privacy exposure or assuming hardware is immortal."}, {"i": "D4.4-L1-c", "c": "D4.4", "l": 1, "f": "c", "cl": "I evaluate privacy requirements before disclosing credentials.", "s": "If an intake questionnaire requests more personal data points than the immediate objective requires, what is the safest response?", "o": ["Give only what the task actually needs.", "Fill out every single blank space completely.", "Provide false data for the required fields.", "Abandon the important task entirely out of fear."], "k": 0, "w": "Data minimization at the collection phase reduces personal privacy exposure. Distractors show excessive compliance by over-sharing data, falsifying records or unnecessary abandonment of essential tasks."}, {"i": "D4.4-L2-a", "c": "D4.4", "l": 2, "f": "a", "cl": "I apply straightforward logical hierarchies to files.", "s": "When confronted with a disorganized and chaotic file directory, which approach establishes the most effective order?", "o": ["A simple structure by topic or date.", "Deleting every folder to start over completely.", "Keeping the mess but changing folder colors.", "Renaming every individual file with numbers."], "k": 0, "w": "Streamlining file structures requires applying intuitive topic-based or temporal hierarchies. Distractors advocate for reckless data destruction, superficial cosmetic fixes or rigid, unhelpful numerical naming conventions."}, {"i": "D4.4-L2-b", "c": "D4.4", "l": 2, "f": "b", "cl": "I implement version control to protect historical data.", "s": "Which practice demonstrates a responsible habit for managing multiple iterations of a critical document?", "o": ["Overwrite the original file every time you make an edit.", "Save every minor sentence change as a brand new document.", "Use a random password on each draft to secure it.", "Keep clear version names or use version history."], "k": 3, "w": "Effective document tracking utilizes sequential naming or built-in software histories to prevent loss. Distractors demonstrate destructive overwriting, chaotic file proliferation or irrelevant security measures."}, {"i": "D4.4-L2-c", "c": "D4.4", "l": 2, "f": "c", "cl": "I restrict sensitive spreadsheet access to authorized personnel.", "s": "When managing a master ledger containing confidential personal contact information, which practice ensures compliance with privacy standards?", "o": ["Keep it organized and limited to those who need it.", "Post the ledger link openly in the group public chat.", "Allow anyone to edit the data to keep it updated.", "Save the ledger file on a shared public library computer."], "k": 0, "w": "Managing sensitive personal records requires data organization paired with strict authorization limits. Distractors compromise privacy through open distribution, unrestricted editing or insecure public hosting."}, {"i": "D4.4-L3-a", "c": "D4.4", "l": 3, "f": "a", "cl": "I practice data minimization by purging old records.", "s": "If you possess legacy archives containing other individuals' personal identifiers that are no longer operationally useful, what action should you take?", "o": ["Delete or archive what you no longer need, especially personal data.", "Sell the data archive to an online marketing research firm.", "Post the entire archive online so the individuals can find it.", "Keep the files indefinitely on your primary desktop computer screen."], "k": 0, "w": "Integrators securely purge or isolate obsolete personal records to maintain data privacy compliance. Distractors show unethical commercial exploitation, public data exposure or careless indefinite storage."}, {"i": "D4.4-L3-b", "c": "D4.4", "l": 3, "f": "b", "cl": "I know why keeping personal data forever is risky.", "s": "Why should you avoid keeping every piece of personal data indefinitely?", "o": ["Holding unneeded personal data raises privacy and risk exposure.", "Storing old text files damages the physical computer processor.", "Keeping old data causes your internet connection to slow down.", "Retaining digital records violates standard hardware warranty rules."], "k": 0, "w": "Unnecessary data accumulation increases the severity of potential data breaches and compliance audits. Distractors falsely attribute physical hardware damage, network lag or warranty violations to data storage."}, {"i": "D4.4-L3-c", "c": "D4.4", "l": 3, "f": "c", "cl": "I know what good shared-data handling requires.", "s": "What does structuring shared data well actually mean for a group?", "o": ["Clear organization, sensible access and removing what is not needed.", "Forcing every member to use identical computer hardware brands.", "Deleting the entire shared folder at the end of every week.", "Allowing absolute anonymous access to all system document files."], "k": 0, "w": "Shared data spaces rely on clean organization, targeted user permissions and lifecycle data minimization. Distractors advocate for hardware uniformity, disruptive file purging or dangerous total anonymity."}, {"i": "D4.4-L4-a", "c": "D4.4", "l": 4, "f": "a", "cl": "I set sensible governance rules for group data.", "s": "You set data rules for a shared group drive. What is the strongest principle?", "o": ["Granting total administrative access to every single group member.", "Least access needed, clear naming and a retention rule.", "Deleting any document that contains more than three pages of text.", "Forbidding the use of subfolders inside the main storage directory."], "k": 1, "w": "Robust governance applies the principle of least privilege, standardized naming and structured data lifecycles. Distractors choose insecure universal access, arbitrary document length cuts or rigid folder bans."}, {"i": "D4.4-L4-b", "c": "D4.4", "l": 4, "f": "b", "cl": "I make group data handling practices sustainable.", "s": "What design elements make group data handling sustainable over time?", "o": ["Agreed structure, access limits and periodic clean-up routines.", "Complex coding requirements that only software developers understand.", "Changing the organization rules completely every single month.", "Requiring members to pay cash fees to save text documents."], "k": 0, "w": "Data sustainability builds on consensus structures, restricted access permissions and routine lifecycle audits. Distractors emphasize confusing technical gatekeeping, chaotic rule changes or arbitrary user fees."}, {"i": "D4.4-L4-c", "c": "D4.4", "l": 4, "f": "c", "cl": "I remediate messy and sensitive shared storage spaces.", "s": "A shared drive is full of duplicate, sensitive old files. What is the best design fix?", "o": ["Ban the team members from uploading any new documents.", "Move all the old files into a hidden unlabelled folder.", "Delete the entire drive without reviewing any data first.", "Set naming, access and retention rules, then clean up."], "k": 3, "w": "Remediation requires implementing a clear policy framework before executing standard data clean-up. Distractors show unhelpful file bans, deceptive folder hiding or reckless universal data destruction."}, {"i": "D5.1-L1-a", "c": "D5.1", "l": 1, "f": "a", "cl": "I can recognize a repetitive task worth automating.", "s": "Which option represents a good candidate for automation in daily life?", "o": ["Deciding what to say to a sad friend who needs comfort.", "Choosing a unique outfit for an important job interview event.", "Painting an original portrait of a landscape for art class.", "Copying the same weekly grocery list every single week."], "k": 3, "w": "Rule-based tasks with zero variance are ideal for basic automation. Distractors feature high-empathy communication, strategic decisions or original creative work that requires human judgment."}, {"i": "D5.1-L1-b", "c": "D5.1", "l": 1, "f": "b", "cl": "I recognize the primary signs of an automatable task.", "s": "Which sign suggests a personal task is worth automating?", "o": ["The task requires your deepest personal feelings to complete.", "You frequently repeat the exact same procedural steps.", "The task is completely different every time you perform it.", "You only need to complete the task once in your lifetime."], "k": 1, "w": "High frequency and procedural predictability are the core indicators of automatable workflows. Distractors emphasize emotional depth, high variance or one-off tasks which defy automation benefits."}, {"i": "D5.1-L1-c", "c": "D5.1", "l": 1, "f": "c", "cl": "I can distinguish rule-based tasks from human judgment calls.", "s": "Which task is most rule-like, predictable and repetitive?", "o": ["Resolving a heated personal argument between two close friends.", "Writing a movie review based on your personal taste and opinions.", "Negotiating a contract price for a new household service plan.", "Renaming photo files by date every single month."], "k": 3, "w": "File reformatting by standard date protocols follows a strict, non-judgmental rule set. Distractors feature interpersonal mediation, subjective aesthetic critique or financial negotiation."}, {"i": "D5.1-L2-a", "c": "D5.1", "l": 2, "f": "a", "cl": "I prioritize automation tasks based on time saved.", "s": "One task saves 2 hours a week; another saves 10 seconds a year. Which to automate first?", "o": ["The 10-seconds-a-year task because it sounds simple to solve.", "The 2-hours-a-week task because the time savings are much higher.", "Neither task because automation always takes too much effort.", "Both tasks simultaneously using identical software script settings."], "k": 1, "w": "Efficient operators evaluate potential automation projects by calculating return-on-investment metrics. Distractors choose trivial impact tasks, exhibit absolute tech avoidance or attempt impossible unified scripting."}, {"i": "D5.1-L2-b", "c": "D5.1", "l": 2, "f": "b", "cl": "I know the traits of excellent automation candidates.", "s": "The best automation candidate is usually characterized by being?", "o": ["Frequent, rule-based and low-risk if slightly wrong.", "Rare, highly subjective and dangerous if an error occurs.", "Emotional, creative and focused entirely on interpersonal relationships.", "Free, short and requiring a major coding degree to configure."], "k": 0, "w": "Optimal automation candidates feature low-risk profiles, high frequency and structured rules. Distractors list risky one-off tasks, high-empathy human domains or arbitrary educational barriers."}, {"i": "D5.1-L2-c", "c": "D5.1", "l": 2, "f": "c", "cl": "I preserve human judgment while automating routine tasks.", "s": "What is the best approach for a frequent task that demands a human judgment call every time?", "o": ["Automate the whole task and accept whatever errors the computer makes.", "Automate routine processes and preserve the human judgment step.", "Avoid using any tools and complete the entire task manually.", "Delete the task from your schedule so you never deal with it."], "k": 1, "w": "Explorer-level users segment tasks to delegate mechanical grind while protecting human oversight. Distractors advocate for risky full automation, absolute tool rejection or ignoring the task entirely."}, {"i": "D5.1-L3-a", "c": "D5.1", "l": 3, "f": "a", "cl": "I redesign workflows so AI handles routine grind.", "s": "You spend hours sorting paper receipts by hand every month. Best workflow redesign?", "o": ["Throw all your paper receipts away to avoid doing the monthly work.", "Let AI extract and categorize, while you review the final summary.", "Keep sorting them manually because computer tools are too modern.", "Hire an expensive professional accountant to sort the receipts manually."], "k": 1, "w": "Integrators map human-in-the-loop patterns where AI parses data structures and humans verify the accuracy. Distractors show irresponsible data destruction, complete tech fear or excessive outsourcing costs."}, {"i": "D5.1-L3-b", "c": "D5.1", "l": 3, "f": "b", "cl": "I implement draft-and-approval workflows for AI summaries.", "s": "You are redesigning your weekly project report workflow using AI. What is the best approach?", "o": ["Let the AI system post the weekly report directly without your review.", "Write the entire report manually to avoid using modern software tools.", "Have AI draft from your data, then you edit and approve.", "Generate five different reports and pick one based on font style."], "k": 2, "w": "Integrators use AI as a drafting assistant while maintaining a strict manual review and approval checkpoint. Distractors allow unverified posting, reject technology entirely or rely on superficial style choices."}, {"i": "D5.1-L3-c", "c": "D5.1", "l": 3, "f": "c", "cl": "I keep human checkpoints where they matter most.", "s": "A good AI-assisted routine keeps what operational framework element in place?", "o": ["An automated billing system that checks your daily data usage limits.", "A human check at the workflow points that matter most.", "A software block that stops the chatbot from writing long messages.", "A public forum where strangers vote on your project formatting choices."], "k": 1, "w": "Robust AI workflows preserve human checkpoints for high-stakes decisions and final data verification. Distractors focus on automated billing, text length limitations or irrelevant public voting."}, {"i": "D5.1-L4-a", "c": "D5.1", "l": 4, "f": "a", "cl": "I build automated workflows with human fallback paths.", "s": "When automating a team onboarding flow end-to-end, which choice ensures the highest resilience?", "o": ["Allow the software script to delete any user account that has missing data.", "Require new users to complete a complex programming exam during signup.", "Remove all data validation rules so the system never encounters errors.", "Automate the steps but add checks and a human fallback for exceptions."], "k": 3, "w": "Enterprise workflows require automated validation steps combined with explicit human escalation paths for edge cases. Distractors show destructive automation, unnecessary user hurdles or ignoring errors entirely."}, {"i": "D5.1-L4-b", "c": "D5.1", "l": 4, "f": "b", "cl": "I prioritize reliability and clear automation ownership.", "s": "When designing an automated process that others depend on, what are the key principles?", "o": ["Reliability, clear ownership and a way to catch failures.", "Visual aesthetic, high pricing tiers and complex code scripts.", "Rapid speed, total user anonymity and zero manual updates.", "Public access, variable rules and matching social media trends."], "k": 0, "w": "Sustainable team automation requires system reliability, explicit individual ownership and robust exception monitoring. Distractors prioritize superficial design, extreme processing speed or chasing online trends."}, {"i": "D5.1-L4-c", "c": "D5.1", "l": 4, "f": "c", "cl": "I make silent automation failures visible using alerts.", "s": "An automated group file process sometimes fails silently. What is the best design fix?", "o": ["Ignore the issue because file processing errors rarely cause project delays.", "Tell group members to manually check the system log every hour.", "Delete the automated script and process every file by hand instead.", "Add alerts and a fallback so failures are caught and handled."], "k": 3, "w": "High-level system design requires proactive monitoring alerts and explicit error-handling fallbacks. Distractors ignore the operational risk, offload tedious monitoring onto users or abandon automation completely."}, {"i": "D5.2-L2-a", "c": "D5.2", "l": 2, "f": "a", "cl": "I identify low-risk use cases for initial automation.", "s": "Which scenario represents the safest and most reliable point of entry for personal automation?", "o": ["Letting a software script trade your entire life savings on the stock market.", "Allowing a new tool to prescribe medication dosages based on online articles.", "Letting an unverified app reply to confidential legal emails automatically.", "Configuring an automated reminder system for recurring billing cycles."], "k": 3, "w": "Safe automation adoption begins with highly predictable, low-risk administrative tasks like calendar or billing reminders. Distractors present dangerous, high-stakes financial, medical or legal hazards."}, {"i": "D5.2-L2-b", "c": "D5.2", "l": 2, "f": "b", "cl": "I streamline repetitive communication using templates.", "s": "If you routinely compose and dispatch the identical email message on a weekly basis, what is the simplest automation entry point?", "o": ["Pay a premium subscription fee for an advanced coding assistant.", "Saving a template or using a saved reply feature.", "Rewriting the entire text from memory every single week.", "Letting an AI tool generate a completely new message each time."], "k": 1, "w": "Text templates provide a frictionless, zero-risk method to automate static communication tasks. Distractors introduce unnecessary premium software costs, manual inefficiency or erratic text generation."}, {"i": "D5.2-L2-c", "c": "D5.2", "l": 2, "f": "c", "cl": "I streamline file management using automated tools.", "s": "When managing a large volume of digital imagery, which strategy represents a practical entry point for small-scale automation?", "o": ["Printing every photo out to store them in physical paper boxes.", "Deleting half of your imagery files to save local hard drive space.", "Utilizing a rule or dedicated tool to sort files automatically by date.", "Giving strangers online access to your photo library to organize it."], "k": 2, "w": "Automated file sorting by metadata fields like dates is an accessible, low-risk workflow upgrade. Distractors show regression to paper, destructive data purging or dangerous security exposure."}, {"i": "D5.2-L3-a", "c": "D5.2", "l": 3, "f": "a", "cl": "I design automations to flag anomalies for review.", "s": "How should a robust, multi-step automation workflow be structured to manage operational risks?", "o": ["Handle the common cases and flag the rest for you.", "Process every scenario identically regardless of severe data errors.", "Stop running entirely the moment any single file is opened.", "Force a human to type out every code step manually during execution."], "k": 0, "w": "Multi-step workflows optimize efficiency by processing standard structures automatically while isolating anomalies. Distractors show reckless error blindness, system fragility or manual over-processing."}, {"i": "D5.2-L3-b", "c": "D5.2", "l": 3, "f": "b", "cl": "I enforce review checkpoints before outputs go out.", "s": "If you build an automation that gathers data, summarizes it and drafts a message, which safeguard ensures quality?", "o": ["Ensure the final text uses an advanced and complex vocabulary style.", "Check if the background color of your email app matches the template.", "Trust the tool completely if it processed the data in under five seconds.", "Review the summary before the email goes out to the recipient."], "k": 3, "w": "Human-in-the-loop validation protects against automated dissemination of hallucinations or formatting glitches. Distractors emphasize vocabulary style, cosmetic background coloring or execution speed."}, {"i": "D5.2-L3-c", "c": "D5.2", "l": 3, "f": "c", "cl": "I identify factors that deliver genuine time savings.", "s": "Which design characteristic ensures that a multi-step automation truly optimizes productivity and saves time?", "o": ["It features thousands of lines of highly complex programming code.", "It reliably handles the routine flow with minimal fixing needed.", "It requires you to change the setup configuration every morning.", "It sends dozens of daily confirmation notifications to your phone."], "k": 1, "w": "True automation ROI depends on high reliability and low human maintenance requirements for standard paths. Distractors confuse code complexity, frequent maintenance or notification spam with productivity."}, {"i": "D5.2-L4-a", "c": "D5.2", "l": 4, "f": "a", "cl": "I test edge cases and integrate error handling.", "s": "When designing an automated workflow that other team members depend on, which practice best ensures system resilience?", "o": ["Test edge cases and add clear failure handling mechanisms.", "Standardize the system to only accept data from one specific user.", "Keep the underlying logic completely hidden so nobody asks questions.", "Assume that errors are impossible if you use a paid software tool."], "k": 0, "w": "Resilient team tools require defensive testing against unexpected user inputs and clear programmatic error trapping. Distractors restrict access needlessly, embrace obfuscation or assume tool infallibility."}, {"i": "D5.2-L4-b", "c": "D5.2", "l": 4, "f": "b", "cl": "I handle malformed inputs safely with failure alerts.", "s": "Which characteristic distinguishes a resilient and dependable automation from a fragile system architecture?", "o": ["It stops running permanently if an unexpected text font is uploaded.", "It automatically updates its visual theme based on popular web trends.", "It requires a software engineer to launch the script every single time.", "It handles bad input gracefully and alerts on failure events."], "k": 3, "w": "System robustness is defined by input validation tolerance and visible telemetry alerts when crashes occur. Distractors describe brittle failure profiles, cosmetic theme trends or a lack of autonomy."}, {"i": "D5.2-L4-c", "c": "D5.2", "l": 4, "f": "c", "cl": "I deploy shared automations alongside documentation.", "s": "To guarantee long-term dependability, what components must accompany a shared automated workflow?", "o": ["A gallery of trendy infographic icons and a high price tag.", "Clear docs and a named owner for when it breaks.", "A long video explaining the general history of internet technology.", "An automated rule that deletes the user history every single day."], "k": 1, "w": "Long-term ownership and transparent documentation ensure systems can be maintained when integration components drift. Distractors highlight cosmetic assets, generic historical education or data destruction."}, {"i": "D5.3-L3-a", "c": "D5.3", "l": 3, "f": "a", "cl": "I configure custom assistants with clear scope bounds.", "s": "When building a custom assistant to address frequently asked questions for a project, which choice is most critical?", "o": ["Selecting a clever and funny name for the chatbot profile.", "Allowing the assistant to discuss any random topic a user brings up.", "Ensuring the interface uses bright and highly colorful graphics.", "Clear instructions and the reference info it should use."], "k": 3, "w": "Custom assistants require explicit system prompts and clean context data to prevent hallucinations. Distractors focus on profile naming, unconstrained conversational scope or interface colors."}, {"i": "D5.3-L3-b", "c": "D5.3", "l": 3, "f": "b", "cl": "I refine custom assistants to stay within scope.", "s": "If a custom assistant begins generating off-topic responses during interactions, which adjustment represents the most effective solution?", "o": ["Delete the entire assistant profile and build it again from scratch.", "Tell your users that they are writing bad questions to the chatbot.", "Tighten its instructions to stay on scope and defer otherwise.", "Change the visual font style of the chatbot conversation screen."], "k": 2, "w": "Scope drift is corrected by refining behavioral guidelines and instructing the model to decline out-of-bounds queries. Distractors show overreactions like profile destruction, user-blaming or cosmetic font adjustments."}, {"i": "D5.3-L3-c", "c": "D5.3", "l": 3, "f": "c", "cl": "I validate custom assistants against real-world test cases.", "s": "Prior to distributing a newly configured custom assistant to your team, which step ensures its operational readiness?", "o": ["Test it on real questions and fix weak answers.", "Publish it immediately to show you can build software tools fast.", "Assume it is flawless if the setup interface looks highly modern.", "Check if the tool works well late at night when traffic is low."], "k": 0, "w": "Validation requires auditing assistant responses against a sample dataset of real user inquiries. Distractors prioritize deployment speed, rely on modern interface aesthetics or perform irrelevant timeframe checks."}, {"i": "D5.3-L4-a", "c": "D5.3", "l": 4, "f": "a", "cl": "I implement behavioral limits on acting agents.", "s": "When deploying an agent capable of executing consequential actions like sending communications, which design choice provides the highest safety?", "o": ["Giving the agent complete, unmonitored control over your main bank account.", "Allowing the agent to delete files without keeping any operational history.", "Restricting the agent to running only during early morning hours.", "Confirmation or limits on consequential actions, plus clear logging."], "k": 3, "w": "Autonomous agents must operate within explicit transaction boundaries, human approval thresholds and detailed audit logging. Distractors describe dangerous unmonitored financial access, lack of audit trails or arbitrary hour restrictions."}, {"i": "D5.3-L4-b", "c": "D5.3", "l": 4, "f": "b", "cl": "I apply the principle of least privilege to agents.", "s": "When connecting an autonomous agent to your external accounts, which configuration establishes the safest security boundary?", "o": ["Provide full administrative passwords to every linked file directory.", "Grant only the access it needs, nothing more.", "Allow the agent to share your personal login data publicly.", "Turn off all account security alerts to avoid system interruptions."], "k": 1, "w": "The principle of least privilege dictates restricting API access to the minimal scope required for the task. Distractors describe unsafe universal admin permissions, public credential disclosure or turning off security monitoring."}, {"i": "D5.3-L4-c", "c": "D5.3", "l": 4, "f": "c", "cl": "I integrate mandatory manual overrides within agent architectures.", "s": "Which design pattern best ensures system safety when deploying an operational acting agent?", "o": ["Allowing the agent to change its own security parameters automatically.", "Hiding the shutdown button so users cannot interrupt the active script.", "Forcing the agent to use highly complex vocabulary in its reports.", "A human override and limits on high-impact actions."], "k": 3, "w": "Resilient agent governance requires permanent human override switches paired with programmatic caps on irreversible actions. Distractors allow dangerous self-modification of security parameters, conceal kill switches or focus on linguistic style."}, {"i": "D5.4-L2-a", "c": "D5.4", "l": 2, "f": "a", "cl": "I review automated output before it goes public.", "s": "Your automated script drafts weekly social posts for your club. What is a sensible control?", "o": ["Let the script publish the drafts automatically at midnight.", "Trust the script completely if it uses standard grammar formatting.", "Review the drafted posts manually before they go public.", "Delete the automation if any single draft contains a typo."], "k": 2, "w": "Keeping a human check on automated output ensures quality and prevents public errors. Distractors favor unverified automatic publishing, trust basic grammar over factuality or advocate for destroying useful software over minor glitches."}, {"i": "D5.4-L2-b", "c": "D5.4", "l": 2, "f": "b", "cl": "I sanity-check automated summaries before acting.", "s": "Automated system summaries feed an important group decision. What is the human-in-control step?", "o": ["Read and sanity-check the text before deciding.", "Accept the summary immediately to maintain operational speed.", "Paste the summary into a secondary chatbot for reassurance.", "Ignore the summary and make the decision based on luck."], "k": 0, "w": "Human-in-the-loop systems require individuals to cross-reference summaries before executing decisions. Distractors prize unverified speed, trust recursive AI loops or abandon analytics entirely for luck."}, {"i": "D5.4-L2-c", "c": "D5.4", "l": 2, "f": "c", "cl": "I recognize when a human is still in control of a system.", "s": "Which option represents the best sign that a human is still in control of an automated process?", "o": ["A person manually reviews and approves consequential outputs.", "The software tool features a brightly colored user interface theme.", "The script processes thousands of file updates every second.", "The computer program never generates any system error messages."], "k": 0, "w": "True human control is defined by active approval steps on high-impact actions. Distractors mistake cosmetic interface choices, processing speed or an absence of error logs for structural safety boundaries."}, {"i": "D5.4-L3-a", "c": "D5.4", "l": 3, "f": "a", "cl": "I place checkpoints before consequential steps.", "s": "Where should a human checkpoint sit within a multi-step automation workflow?", "o": ["Before any consequential or irreversible execution step.", "At the very beginning of the pipeline before data enters.", "At the absolute end of the process after outputs publish.", "Inside the offline software installation manual folder."], "k": 0, "w": "Safeguards must intercept data immediately before irreversible or high-stakes operations occur. Distractors locate the check too early, too late after damages are done or inside static external documentation files."}, {"i": "D5.4-L3-b", "c": "D5.4", "l": 3, "f": "b", "cl": "I require manual approval before money moves.", "s": "You are designing an automated billing workflow. What is the best placement for an approval step?", "o": ["Before the money is officially sent to the external account.", "Immediately after the financial transaction completes successfully.", "Once a month when you review your general bank statement.", "When configuring the initial programming code layout settings."], "k": 0, "w": "Financial integrity designs mandate that human verification gates transactional outlays before funds escape control. Distractors place the check after the money is gone, weeks later during audits or solely in initial code setup."}, {"i": "D5.4-L3-c", "c": "D5.4", "l": 3, "f": "c", "cl": "I apply human-in-the-loop workflows where they matter most.", "s": "Where is keeping a human-in-the-loop checkpoint most valuable in an automated system?", "o": ["During the initial selection of a software interface color theme.", "When generating routine text formatting styles for basic documentation files.", "For simple file reorganization tasks that have low overall stakes.", "For high-impact or irreversible operational and financial actions."], "k": 3, "w": "Human-in-the-loop oversight is critical for mitigating risks associated with irreversible or high-stakes actions. Distractors focus on low-stakes, cosmetic or routine tasks where automated errors cause minimal harm."}, {"i": "D5.4-L4-a", "c": "D5.4", "l": 4, "f": "a", "cl": "I build action logs and manual overrides into automations.", "s": "What is the strongest oversight feature to include when designing an automation for others?", "o": ["An automated email system that sends daily congratulations messages to users.", "A hidden programming script that prevents anyone from viewing operational history.", "A clear log of actions plus an easy override or stop option.", "A visual configuration tool that allows users to change font styles easily."], "k": 2, "w": "Creator-level automation design requires transparent telemetry logging paired with immediate human kill switches. Distractors present useless notification spam, dangerous system obfuscation or trivial cosmetic features."}, {"i": "D5.4-L4-b", "c": "D5.4", "l": 4, "f": "b", "cl": "I know why system logging matters in automation.", "s": "Why should you build an explicit action log into a multi-step automation workflow?", "o": ["To guarantee the software script runs twice as fast during peak hours.", "So you can see what it did and catch or undo problems.", "To prevent other team members from suggesting updates to the code structure.", "To automatically delete any file that takes too long to process."], "k": 1, "w": "Operational logging provides an audit trail necessary to diagnose anomalies and reverse systemic errors. Distractors suggest incorrect performance gains, anti-collaborative gatekeeping or destructive data purging."}, {"i": "D5.4-L4-c", "c": "D5.4", "l": 4, "f": "c", "cl": "I make system override controls easy to reach.", "s": "When deploying a shared automation process, an override control button should be designed to be?", "o": ["Easy to find and use when something goes wrong with the script.", "Hidden deep inside the advanced backend programming code files for security.", "Accessible only late at night when system processing traffic is completely low.", "Disabled completely to ensure the automated pipeline finishes its tasks rapidly."], "k": 0, "w": "Resilient systems ensure emergency intervention tools are highly visible and frictionless for operators. Distractors advocate for burying tools in code, restricting access by timeframe or removing overrides entirely."}, {"i": "D6.1-L1-a", "c": "D6.1", "l": 1, "f": "a", "cl": "I do not paste others' personal data into public tools.", "s": "You want an AI tool to summarize a document full of clients' personal details. Safe move?", "o": ["Remove or anonymize the personal details first, or use an approved tool.", "Paste the entire document since famous software platforms protect files automatically.", "Upload the file unchanged because text data contains no high-risk visual elements.", "Share the document link only late at night when data harvesting is low."], "k": 0, "w": "Protecting privacy requires data minimization or utilizing vetted corporate enterprise sandboxes. Distractors show naive trust in consumer software brands, misunderstand data types or rely on arbitrary timeframes."}, {"i": "D6.1-L1-b", "c": "D6.1", "l": 1, "f": "b", "cl": "I can identify data that is risky to paste into tools.", "s": "Which dataset represents the highest privacy risk if pasted into a public consumer AI tool?", "o": ["A list of standard grocery items with generic price estimates.", "Someone's name, physical address and personal identity number.", "The opening hours of a local public park during summer.", "A collection of anonymous historical weather statistics from last year."], "k": 1, "w": "Personally identifiable information (PII) carries severe legal and privacy exposure if leaked. Distractors feature non-sensitive, public domain facts like grocery lists, park hours or historical weather statistics."}, {"i": "D6.1-L1-c", "c": "D6.1", "l": 1, "f": "c", "cl": "I check text content for private data before pasting.", "s": "What is the best habit to adopt before pasting any text block into a public AI assistant?", "o": ["Ensure the text block uses advanced vocabulary and perfect grammar structures.", "Count the total number of words to verify it meets length limits.", "Check that it does not contain other people's private data.", "Translate the text into a different language to hide the meaning."], "k": 2, "w": "Proactive data review prevents accidental data leaks on public infrastructure. Distractors focus on irrelevant cosmetic properties like vocabulary, word counts or ineffective translation obfuscation."}, {"i": "D6.1-L2-a", "c": "D6.1", "l": 2, "f": "a", "cl": "I share only the minimum data a task requires.", "s": "An AI tool can help you draft a letter about a neighbor dispute. Data-minimizing approach?", "o": ["Paste your neighbor's entire employment history and contact file into the tool.", "Upload the full historical property deed document containing everyone's signatures.", "Avoid using the tool entirely because all digital editing is highly dangerous.", "Share only the details needed, generalizing names where possible."], "k": 3, "w": "Data minimization involves stripping or abstraction of identifiers to the lowest functional baseline. Distractors over-share high-risk documents, expose employment details or reject the tool out of paranoia."}, {"i": "D6.1-L2-b", "c": "D6.1", "l": 2, "f": "b", "cl": "I know what the principle of data minimization means.", "s": "Within the context of interacting with digital tools, what does data minimization actually mean?", "o": ["Reducing the font size of your input text to save screen space.", "Deleting half of your saved personal photographs every single month.", "Compressing large data folders into smaller file sizes before archiving them.", "Giving only the information that is strictly necessary for the task."], "k": 3, "w": "Data minimization is a core privacy concept focused on restricting data collection to immediate operational necessity. Distractors confuse the rule with font sizes, random image deletion or file compression."}, {"i": "D6.1-L2-c", "c": "D6.1", "l": 2, "f": "c", "cl": "I strip identifying details from input text snippets.", "s": "You want a public AI assistant to check one paragraph's grammar. What is the most sensible input?", "o": ["The entire multi-page document so the tool has complete context.", "The target paragraph paired with the author's full private address.", "Just the paragraph, with identifying details removed from the text.", "A blank document link to let the tool find the text itself."], "k": 2, "w": "Isolating a text snippet and scrubbing identifiers limits privacy exposure during simple utility tasks like proofreading. Distractors risk over-sharing whole files, adding unnecessary PII or providing blank links."}, {"i": "D6.1-L3-a", "c": "D6.1", "l": 3, "f": "a", "cl": "I check for a lawful basis before processing large datasets.", "s": "You plan to process a large volume of personal data using a new AI method. Sound step?", "o": ["Launch the process quickly to surprise your team with the results.", "Check you have a lawful basis and whether a privacy assessment is needed.", "Assume processing is legal since your company purchased a paid software license.", "Ask a colleague if they personally feel the workflow is ethical."], "k": 1, "w": "Integrators understand compliance requirements like lawful basis checks and Data Protection Impact Assessments (DPIAs). Distractors act impulsively for surprise value, assume software licenses confer legality or trust casual opinions."}, {"i": "D6.1-L3-b", "c": "D6.1", "l": 3, "f": "b", "cl": "I know which data uses trigger formal privacy checks.", "s": "Which data processing scenario most urgently requires a formal data privacy impact check?", "o": ["Sorting a small list of generic office supply item names alphabetically.", "Counting the number of words used in a public promotional blog post.", "Systematically profiling many individuals' sensitive personal data.", "Changing the background layout colors on your team project management dashboard."], "k": 2, "w": "Large-scale, automated profiling of special-category or sensitive personal data is a primary legal trigger for formal DPIAs. Distractors feature zero-risk administrative work like sorting supplies, counting words or altering dashboard colors."}, {"i": "D6.1-L3-c", "c": "D6.1", "l": 3, "f": "c", "cl": "I treat special-category personal data with extra care.", "s": "When handling special-category data like health status or religious beliefs with AI, what is the right instinct?", "o": ["Process it freely because data classification categories have zero legal weight.", "Avoid all processing because handling special-category data online is completely illegal.", "Apply extra care; it needs stronger justification and protective safeguards.", "Treat it identically to public information like local city weather stats."], "k": 2, "w": "Special-category data commands heightened technical and legal safeguards due to discrimination risks. Distractors err by denying legal boundaries, falsely claiming all processing is illegal or flattening risk classifications."}, {"i": "D6.1-L4-a", "c": "D6.1", "l": 4, "f": "a", "cl": "I design privacy protections into automated workflows from the start.", "s": "You are setting up a shared AI process that handles personal records. What is a privacy-by-design choice?", "o": ["Collect all data now and worry about access permissions next year.", "Collect the minimum, limit access and set retention from the start.", "Grant universal administrative editing permissions to every single user account.", "Save all user records into a public spreadsheet for convenience."], "k": 1, "w": "Privacy-by-design incorporates collection limits, access controls and clear lifecycles into the initial architecture. Distractors show poor governance habits like delaying checks, granting universal access or public hosting."}, {"i": "D6.1-L4-b", "c": "D6.1", "l": 4, "f": "b", "cl": "I know what the concept of privacy-by-design requires.", "s": "What does the professional framework requirement of privacy-by-design mean for a project?", "o": ["Privacy parameters are checked only after a major data leak occurs.", "Privacy guidelines are written exclusively by the graphic design department.", "Privacy features cost double the price of a standard software license.", "Privacy considerations are built into the system design from the beginning."], "k": 3, "w": "Privacy-by-design requires embedding data protection protocols into system engineering upfront rather than retrofitting them. Distractors describe reactive forensics, cosmetic design confusion or arbitrary price metrics."}, {"i": "D6.1-L4-c", "c": "D6.1", "l": 4, "f": "c", "cl": "I configure safe defaults for workflows handling personal records.", "s": "What is the strongest privacy default setting for a new AI workflow handling personal records?", "o": ["Maximum data collection, open public visibility and indefinite local storage.", "Zero data encryption, hidden log tracking and random deletion schedules.", "Variable data collection, automatic social media sharing and anonymous edits.", "Minimal data collection, restricted access control and clear retention rules."], "k": 3, "w": "Safe configuration defaults embrace minimization, tight privilege isolation and structured deletion. Distractors describe insecure worst practices like universal exposure, unencrypted data streams or social media distribution."}, {"i": "D6.2-L1-a", "c": "D6.2", "l": 1, "f": "a", "cl": "I know AI outputs are not automatically neutral.", "s": "Which statement regarding the objectivity of AI models is accurate?", "o": ["AI outputs represent pure, objective truth because machines lack feelings.", "AI systems can reflect human biases present in their training data.", "All digital tools are automatically fair because math has no opinions.", "Paid chatbot applications are legally certified to be completely neutral."], "k": 1, "w": "AI outputs mirror the historical inequalities, statistical skews and human biases embedded in training corpuses. Distractors embrace naive techno-optimism regarding machine purity, math neutrality or premium software certifications."}, {"i": "D6.2-L1-b", "c": "D6.2", "l": 1, "f": "b", "cl": "I can identify common causes of algorithmic bias.", "s": "An automated AI screening tool favors one demographic group unfairly. What is the most likely cause?", "o": ["The software application was launched during an unusually warm summer month.", "The computer processor unit experienced a temporary electrical power surge.", "The model learned systemic bias from skewed past historical training data.", "The user typed their prompt using lowercase letters instead of capitals."], "k": 2, "w": "Algorithmic bias typically stems from unrepresentative or discriminatory patterns in historical training data. Distractors suggest absurd environmental, hardware or trivial typographic causes like weather, power surges or text case."}, {"i": "D6.2-L1-c", "c": "D6.2", "l": 1, "f": "c", "cl": "I remain aware that AI outputs can be unfair.", "s": "What is a healthy, realistic awareness to maintain regarding AI fairness?", "o": ["Stay alert that outputs can be systematically unfair to some groups.", "Assume all outputs are perfectly fair unless a computer error icon blinks.", "Believe that algorithmic tools have completely solved human bias everywhere.", "Discard all digital outputs because technology is always intentionally evil."], "k": 0, "w": "Critical AI literacy demands an active, baseline awareness that systems replicate systemic biases. Distractors show absolute complacency, blind trust in error icons, utopian beliefs or absolute Luddite rejection."}, {"i": "D6.2-L2-a", "c": "D6.2", "l": 2, "f": "a", "cl": "I identify where algorithmic bias causes operational harm.", "s": "In which application area does an AI tool's underlying algorithmic bias matter most?", "o": ["Generating a random color scheme for a personal digital notebook.", "Screening bank loan applications or hiring prospective job candidates.", "Suggesting a fictional name for a spaceship in a creative story.", "Sorting a list of grocery items by weight or expiration date."], "k": 1, "w": "Algorithmic bias carries severe real-world harm when deployed in gatekeeping domains like finance, employment or legal sentencing. Distractors present low-stakes aesthetic, creative or routine logistical tasks."}, {"i": "D6.2-L2-b", "c": "D6.2", "l": 2, "f": "b", "cl": "I know which tool use needs the most fairness care.", "s": "In which scenario does an AI tool require the highest level of algorithmic fairness evaluation?", "o": ["Determining the fastest driving route to a public library.", "Recommending a fictional movie based on your viewing history.", "Sorting email messages into different personal label folders.", "Deciding who gets access to an essential public benefit."], "k": 3, "w": "Fair distribution metrics are critical when automated systems allocate scarce or life-altering resources. Distractors involve low-stakes navigational, entertainment or organizational preferences with no social equity risk."}, {"i": "D6.2-L2-c", "c": "D6.2", "l": 2, "f": "c", "cl": "I raise fairness concerns when tools rank people.", "s": "An automated system ranks candidates for a scholarship opportunity. What is the most responsible concern?", "o": ["Ensure the ranking list fits on a single printed page.", "Check that the tool is not systematically disadvantaging a group.", "Confirm that the tool uses highly advanced vocabulary labels.", "Verify that the tool processes the names in alphabetical order."], "k": 2, "w": "Evaluating whether a demographic subgroup faces systemic exclusion is an essential fairness habit. Distractors highlight superficial formatting concerns like document length, word choice complexity or sorting methods."}, {"i": "D6.2-L3-a", "c": "D6.2", "l": 3, "f": "a", "cl": "I audit group outcomes and retain human checks.", "s": "You use an AI system to shortlist volunteers for a community program. What is a sound fairness practice?", "o": ["Review whether it treats demographic groups consistently and keep human oversight.", "Accept the first five candidates automatically to ensure rapid onboarding speed.", "Change the prompt wording every morning to randomize user outcomes.", "Trust that the system is perfectly objective because it ignores names."], "k": 0, "w": "Integrators cross-check automated outcomes for consistent subgroup selection ratios while keeping human veto rights. Distractors show careless speed prioritization, ineffective prompt randomization or naive trust in data colorblindness."}, {"i": "D6.2-L3-b", "c": "D6.2", "l": 3, "f": "b", "cl": "I detect algorithmic bias by comparing outcomes.", "s": "How might you detect systemic bias in an automated decision-making tool?", "o": ["Count the total number of characters used in the system prompt.", "Compare outcomes across different demographic groups for unfair gaps.", "Monitor whether the software tool crashes when processing large files.", "Ask the chatbot directly if it prefers certain types of users."], "k": 1, "w": "Disparate impact is identified by analyzing demographic statistical skews across historical outcomes. Distractors look at irrelevant metrics like prompt lengths, software stability bugs or meaningless conversational self-reporting."}, {"i": "D6.2-L3-c", "c": "D6.2", "l": 3, "f": "c", "cl": "I preserve manual review for high-impact decisions.", "s": "What should you always retain for an impactful, AI-assisted selection process?", "o": ["A paid software subscription to ensure complete data neutrality.", "A highly complex sequence of different prompt engineering words.", "Human review, especially where fairness is at stake.", "An automated rule that deletes user history logs quickly."], "k": 2, "w": "Preserving manual verification safeguards human rights and accountability in sensitive workflows. Distractors mistakenly treat premium tiers, prompt complexity or aggressive data purging as safeguards."}, {"i": "D6.2-L4-a", "c": "D6.2", "l": 4, "f": "a", "cl": "I integrate routine bias audits into group processes.", "s": "What is the strongest bias-check mechanism to build into a group's AI evaluation workflow?", "o": ["Forcing team members to complete a daily typing speed test.", "Requiring all text outputs to use a specific corporate font.", "Routinely compare outcomes across groups and act on unfair gaps.", "Limiting system access to users with advanced engineering degrees."], "k": 2, "w": "Governance frameworks require continuous statistical surveillance of outcome fields to identify demographic skews. Distractors present useless operational hoops like typing tests, font uniformity or credential gatekeeping."}, {"i": "D6.2-L4-b", "c": "D6.2", "l": 4, "f": "b", "cl": "I understand the requirements of a bias check.", "s": "What operational assets does a robust algorithmic bias check require to function?", "o": ["A massive collection of high-resolution stock photography files.", "A fast internet browser extension that blocks marketing advertisements.", "A long written summary detailing the history of computing math.", "Outcome data by demographic group and a threshold for concern."], "k": 3, "w": "Auditing software requires categorizable demographic metadata coupled with an explicit metric threshold for intervention. Distractors look for irrelevant media graphics, ad blockers or abstract history lessons."}, {"i": "D6.2-L4-c", "c": "D6.2", "l": 4, "f": "c", "cl": "I remediate workflows when bias is flagged.", "s": "If a routine bias audit flags an unfair demographic gap in your system, what is the best response?", "o": ["Ignore the alert unless a user submits a formal legal complaint.", "Delete the historical data log file to remove the warning sign.", "Investigate and adjust the process or add human review.", "Switch the whole team to a different consumer chatbot tool immediately."], "k": 2, "w": "Corrective action means pausing the automated pipeline to redesign parameters or strengthen human-in-the-loop gates. Distractors exhibit passive avoidance, evidence destruction or platform hopping."}, {"i": "D6.3-L1-a", "c": "D6.3", "l": 1, "f": "a", "cl": "I maintain final human authority for high-stakes outcomes.", "s": "When an AI tool recommends rejecting an individual's sensitive request, what is the safest approach?", "o": ["Approve the rejection automatically since machines evaluate rules without human emotion.", "Delete the request file entirely from the company directory database.", "Ask a different chatbot if it agrees with the first recommendation.", "A human should make and own the final decision manually."], "k": 3, "w": "Ethical alignment mandates that automated agents never possess solitary authority over critical personal choices. Distractors show automated passivity, data avoidance or infinite machine-to-machine loop validation."}, {"i": "D6.3-L1-b", "c": "D6.3", "l": 1, "f": "b", "cl": "I maintain absolute clarity regarding human accountability.", "s": "When deploying an AI-assisted workflow, where does the ultimate legal and ethical accountability reside?", "o": ["With the software development firm that hosted the platform server.", "Inside the neural network code structures that processed the text data.", "The human who made or approved the final operational outcome.", "With the public regulatory body that monitors local internet speeds."], "k": 2, "w": "Humans remain the sole accountable actors for any choice optimized by an informational tool. Distractors deflect responsibility toward third-party software firms, autonomous code hallucinations or internet regulators."}, {"i": "D6.3-L1-c", "c": "D6.3", "l": 1, "f": "c", "cl": "I treat AI text solely as an advisory input.", "s": "For an automated workflow that directly impacts an individual, how should the AI component be utilized?", "o": ["As a complete replacement for human decision-making teams.", "As a tool to automatically generate and send final legal denials.", "An advisory input to inform a human decision step.", "As an automated method to sort files by folder color."], "k": 2, "w": "Aware-level users understand that automated outputs serve as assistive data rather than definitive judgments. Distractors embrace total workflow substitution, unmonitored communication or trivial folder sorting."}, {"i": "D6.3-L2-a", "c": "D6.3", "l": 2, "f": "a", "cl": "I use scores as input but require human decisions.", "s": "When leveraging automated screening tools to evaluate candidate qualifications, which workflow model represents the most responsible deployment strategy?", "o": ["Let the tool email rejection notices directly based on low scores.", "Hire whatever candidate achieves the highest numerical score automatically.", "Delete any application file that takes too long to upload.", "Use the score as input; a person reviews and decides."], "k": 3, "w": "Explorer-level workflow optimization treats data metrics as screening signals that require human validation. Distractors authorize automated firing, automated hiring or destructive data processing habits."}, {"i": "D6.3-L2-b", "c": "D6.3", "l": 2, "f": "b", "cl": "I understand the requirements of human-in-the-loop.", "s": "In the context of critical and high-impact workflows, what does a human-in-the-loop framework require?", "o": ["A person checks and can change the system outcome manually.", "An engineer reviews the system data logs once every three years.", "A user types out their prompts using perfect computer coding scripts.", "A manager reads an informational brochure detailing how chatbots work."], "k": 0, "w": "True human-in-the-loop architecture empowers human operators to actively audit, override or rewrite automated decisions. Distractors present useless long-term review delays, prompt code criteria or passive reading habits."}, {"i": "D6.3-L2-c", "c": "D6.3", "l": 2, "f": "c", "cl": "I audit AI correspondence before public dissemination.", "s": "If an automated system drafts an official decision regarding an individual's welfare or benefits, what action must occur prior to dispatch?", "o": ["The system must verify that the text block contains zero adjectives.", "The software should convert the document file into a zipped archive.", "The pipeline must update its graphic background theme options.", "A person reviews and approves the communication manually."], "k": 3, "w": "Official letters regarding personal livelihood require strict human editorial validation before sending. Distractors focus on bizarre text composition constraints, file compression formats or aesthetic interface details."}, {"i": "D6.3-L3-a", "c": "D6.3", "l": 3, "f": "a", "cl": "I route high-impact use cases through escalation channels.", "s": "Which category of automated decision-making requires additional administrative oversight or formal leadership sign-off?", "o": ["Reorganizing a list of internal office supplies by box weight.", "Translating a public holiday greeting into a second language.", "Changing the visual theme layout of a shared project dashboard.", "Determining workforce compensation, shift allocations or hiring selections."], "k": 3, "w": "Material employment determinations directly alter user livelihoods and trigger mandatory corporate governance escalation. Distractors feature zero-risk administrative work like sorting supplies, language translation or theme layout changes."}, {"i": "D6.3-L3-b", "c": "D6.3", "l": 3, "f": "b", "cl": "I manage high-impact AI risks with escalation paths.", "s": "Which approach ensures proper risk management when deploying a high-impact AI application for your team?", "o": ["Allow the software to run completely unmonitored to maximize speed.", "Require team members to hide tool usage details from external auditors.", "Establishing clear escalation paths and requiring formal human sign-off.", "Limiting the workflow deployment exclusively to overnight operating hours."], "k": 2, "w": "Integrators insulate groups from algorithmic liability by deploying rigorous escalation maps and formal authorization checkpoints. Distractors promote dangerous unmonitored execution, cover-up behavior or time limits."}, {"i": "D6.3-L3-c", "c": "D6.3", "l": 3, "f": "c", "cl": "I escalate high-impact uses because errors harm people.", "s": "Why is it critical to escalate high-impact AI applications to higher levels of organizational oversight?", "o": ["Because advanced software tools require a massive amount of electricity.", "Because senior managers prefer reading long technical code printouts.", "Because errors in those domains seriously affect people's lives.", "Because older computers are unable to process complex text templates."], "k": 2, "w": "The gravity of user harm dictates the level of human review density required in modern compliance. Distractors highlight irrelevant energy concerns, corporate management stereotypes or fictional hardware constraints."}, {"i": "D6.3-L4-a", "c": "D6.3", "l": 4, "f": "a", "cl": "I integrate ownership and records into AI governance.", "s": "When establishing a governance framework for a team's AI integration, which operational model provides the highest structural integrity?", "o": ["Defining clear ownership, reviewing impactful use cases and maintaining formal records.", "Allowing individual users to install whatever software extensions they find online.", "Turning off all network system logs to minimize file storage usage.", "Requiring the group to change their operational security rules every morning."], "k": 0, "w": "Comprehensive governance combines clear accountability boundaries, risk-based review loops and absolute document transparency. Distractors promote unvetted shadow IT installation, logging inactivation or chaotic rule oscillation."}, {"i": "D6.3-L4-b", "c": "D6.3", "l": 4, "f": "b", "cl": "I build AI governance with explicit escalation rules.", "s": "Which operational elements must be present to establish robust AI governance within a collaborative group?", "o": ["An expensive premium subscription paired with high-end graphic design templates.", "Defining clear responsibilities and establishing escalation paths for high-impact use cases.", "A strict corporate mandate forbidding the use of any mobile devices.", "Requiring all group communications to be reviewed by an external consultant daily."], "k": 1, "w": "Sustainable corporate governance requires explicit task matrix assignments and transparent remediation channels for high-stakes exceptions. Distractors emphasize premium aesthetic template assets, total mobile device bans or paralyzing daily external reliance."}, {"i": "D6.3-L4-c", "c": "D6.3", "l": 4, "f": "c", "cl": "I ensure system accountability lines are highly visible.", "s": "Which design priority should an effective oversight framework emphasize to maintain automated system integrity?", "o": ["Masking the identity of system administrators to prevent team complaints.", "Forcing users to pass a complex math examination before opening documents.", "Providing clear visibility into who is accountable and how to escalate issues.", "Automating the systematic deletion of all employee conversation history weekly."], "k": 2, "w": "System transparency allows collaborators to trace systemic errors quickly and identify the human owner responsible. Distractors describe unaccountable administrative concealment, arbitrary user barriers or destructive logging habits."}, {"i": "D6.4-L1-a", "c": "D6.4", "l": 1, "f": "a", "cl": "I am willing to disclose AI use where it is relevant.", "s": "You used AI to write an important notice others rely on. What is an honest stance?", "o": ["Hide the software use completely so your coworkers do not think you are lazy.", "Claim you wrote the text entirely by hand to build personal authority.", "Be willing to disclose AI involvement where it is relevant to your readers.", "Assume that computers write public notices better than human teams can."], "k": 2, "w": "Basic transparency requires users to acknowledge programmatic assistance on impactful files. Distractors show deceptive habits like hiding tool use, claiming unearned authorship or assuming total machine superiority."}, {"i": "D6.4-L1-b", "c": "D6.4", "l": 1, "f": "b", "cl": "I know when disclosing AI use matters most.", "s": "When is disclosing AI use most important for a group?", "o": ["When you generate a basic alphabetical list of office supplies.", "When you use a digital tool to check for minor spelling mistakes.", "When it affects trust or a major decision about someone's life.", "When you alter the background layout color of a private spreadsheet."], "k": 2, "w": "Transparency efforts must scale with stakes and relational trust boundaries. Distractors feature zero-risk, routine administrative actions like sorting supplies, spell checking or altering private spreadsheet colors."}, {"i": "D6.4-L1-c", "c": "D6.4", "l": 1, "f": "c", "cl": "I have a healthy attitude to transparency.", "s": "What is a healthy, realistic attitude to maintain regarding AI transparency?", "o": ["Be open about it where it matters for trust and accountability.", "Disclose the specific software version for every short text message you send.", "Refuse to acknowledge tool use because computer editing is completely private.", "Use technology only late at night so nobody knows you have tools."], "k": 0, "w": "Practical literacy values situational openness rather than obsessive micro-disclosure or total secrecy. Distractors represent over-disclosing trivial items, absolute non-disclosure or hiding tool use based on timeframes."}, {"i": "D6.4-L2-a", "c": "D6.4", "l": 2, "f": "a", "cl": "I disclose AI assistance where it is expected.", "s": "You submit AI-assisted work where originality is expected. What is the right move?", "o": ["Claim the work is entirely original since you edited the final word spacing.", "Submit the file using a fake name to protect your identity from the group.", "Disclose the AI assistance per the rules or expectations of the project.", "Delete the project file and refuse to finish the assigned work."], "k": 2, "w": "Meeting ethical guidelines means disclosing tool support in contexts that presume independent human generation. Distractors show deceptive modifications, anonymous evasion or complete task abandonment."}, {"i": "D6.4-L2-b", "c": "D6.4", "l": 2, "f": "b", "cl": "I do not present AI work as personal lived experience.", "s": "A public post is largely AI-written but presented as your personal experience. What is the issue?", "o": ["It can mislead; be transparent about AI's role in the text.", "The text might contain minor background formatting font glitches.", "Public internet sites automatically delete any automated stories.", "It forces other users to upgrade to premium paid account tiers."], "k": 0, "w": "Passing off synthesized prose as authentic human struggle or personal testimony erodes digital trust. Distractors minimize the ethical problem into cosmetic font errors, fictional platform deletion rules or price tier changes."}, {"i": "D6.4-L2-c", "c": "D6.4", "l": 2, "f": "c", "cl": "I state AI use clearly where disclosure is expected.", "s": "Where tool disclosure is formally expected by a group, what is the best practice?", "o": ["Use complex technical jargon to confuse the final review team.", "State clearly that AI was used to help generate the content.", "Hide the disclosure note inside a tiny blank image file.", "Tell the team that checking for tool usage is an absolute waste of time."], "k": 1, "w": "Proper explorer behavior delivers explicit, plain-language notifications when guidelines require disclosure. Distractors show obfuscation tactics, micro-text concealment or confrontational dismissals of group rules."}, {"i": "D6.4-L3-a", "c": "D6.4", "l": 3, "f": "a", "cl": "I keep AI-assisted decisions explainable.", "s": "An AI-assisted decision affects someone's status. What is a sound practice?", "o": ["Tell the person that the computer made the absolute final judgment choice.", "Change the system password so nobody can audit the original file directory.", "Delete the evaluation records quickly to protect team data privacy rules.", "Record the reasoning so it can be explained and reviewed later."], "k": 3, "w": "Integrators preserve decision provenance to guarantee recourse channels and algorithmic accountability. Distractors hide behind machine authority, block system access or destroy evaluation history."}, {"i": "D6.4-L3-b", "c": "D6.4", "l": 3, "f": "b", "cl": "I know why documenting decision bases matters.", "s": "Why should you document the basis of an AI-assisted decision?", "o": ["So it can be explained and reviewed if questioned by an individual.", "To ensure the chatbot software runs faster during peak operation times.", "To prevent other department members from trying out new digital tools.", "To automatically reduce the physical storage space on local computer hardware."], "k": 0, "w": "Documentation provides the evidence trail necessary for human review and administrative appeals. Distractors highlight fictional performance boosts, anti-collaborative gatekeeping or mechanical drive compression."}, {"i": "D6.4-L3-c", "c": "D6.4", "l": 3, "f": "c", "cl": "I know what explainability means.", "s": "Within a professional governance framework, what does explainability mean?", "o": ["Being able to read code text files at extreme typing speeds.", "Knowing the complete historical biography of the tool software developer.", "Translating every text file output into five separate global languages.", "Show the specific reasons behind the generated project outcome."], "k": 3, "w": "Explainability is the capacity to reveal the logic, inputs and constraints that produced an automated conclusion. Distractors confuse the term with reading speed, historical trivia or multilingual translation."}, {"i": "D6.4-L4-a", "c": "D6.4", "l": 4, "f": "a", "cl": "I set a clear disclosure practice for a group.", "s": "What is the best group norm to design for AI tool disclosure?", "o": ["Requiring a formal legal contract every time a chatbot is opened.", "A simple, consistent way to note when AI materially contributed to work.", "Banning the mention of any computer software names in group chats.", "Allowing members to use unvetted apps as long as they pay a fee."], "k": 1, "w": "Creator-level policies establish lightweight, predictable and standardized attribution rules for teams. Distractors describe paralyzing legal hurdles, absolute communication bans or cash fees for policy avoidance."}, {"i": "D6.4-L4-b", "c": "D6.4", "l": 4, "f": "b", "cl": "I know what a good disclosure practice looks like.", "s": "A good group disclosure practice should be designed to be?", "o": ["Long, highly complicated and requiring advanced math degrees to complete.", "Optional, hidden and only checked when a major project failure happens.", "Consistent, proportionate and easy to follow for all team members.", "Automated, unmonitored and managed entirely by an external software bot."], "k": 2, "w": "Sustainable compliance designs ensure tracking mechanisms are repeatable, risk-aligned and user-friendly. Distractors endorse intimidating complexity, reactive neglect or offloading oversight onto unvetted bots."}, {"i": "D6.4-L4-c", "c": "D6.4", "l": 4, "f": "c", "cl": "I focus disclosure where it affects trust or decisions.", "s": "A group's disclosure practice should focus primarily on cases where AI use?", "o": ["Changes the visual font style of a basic text document template.", "Takes more than five seconds to process an internet query line.", "Could affect trust or important decisions about real people.", "Requires the user to download an update for their web browser."], "k": 2, "w": "Governance frameworks optimize team energy by applying transparency rules to high-risk human outcomes rather than low-stakes trivia. Distractors point to cosmetic font styles, processing lag or browser updates."}, {"i": "D6.5-L1-a", "c": "D6.5", "l": 1, "f": "a", "cl": "I avoid uploading work files to unknown sites.", "s": "A flashy unknown AI site asks you to upload work files. Secure response?", "o": ["Upload the files immediately to see what advanced features the tool has.", "Share the site link with your entire group to encourage adoption speed.", "Use the site only late at night when network tracking is completely low.", "Avoid it; use approved, trusted tools to process the information."], "k": 3, "w": "Security awareness means declining interactions with unvetted platforms that harvest user files. Distractors show risky curiosity, viral propagation of shadow tools or relying on meaningless night schedules."}, {"i": "D6.5-L1-b", "c": "D6.5", "l": 1, "f": "b", "cl": "I know what 'shadow AI' means.", "s": "Within an organization or collaborative group, what does 'shadow AI' mean?", "o": ["Running a chatbot application with the screen background set to dark mode.", "Using unapproved AI tools outside the agreed rules and security boundaries.", "Generating images that feature complex patterns of dark lighting and silhouettes.", "Using a computer that does not have an active local internet connection."], "k": 1, "w": "Shadow IT or shadow AI refers to deploying unauthorized digital assets outside corporate security oversight. Distractors build on literal definitions like dark mode themes, artistic silhouettes or offline computers."}, {"i": "D6.5-L1-c", "c": "D6.5", "l": 1, "f": "c", "cl": "I know the safer default for tools with important data.", "s": "What is the safer default choice for tools handling important group data?", "o": ["Free public platforms found through social media video links.", "Discarding all digital storage and tracking data using physical paper notebooks.", "Approved, vetted tools that match group security standards.", "Consumer software mobile apps that have flashy graphic design interfaces."], "k": 2, "w": "High-value assets must be routed exclusively through authorized, security-reviewed infrastructure. Distractors suggest unvetted public platforms, complete technology abandonment or flashy consumer applications."}, {"i": "D6.5-L2-a", "c": "D6.5", "l": 2, "f": "a", "cl": "I recognize data-leakage risks from pasting whole files.", "s": "Pasting a whole confidential file into a public consumer AI risks?", "o": ["Causing your computer device screen to freeze up permanently.", "Violating the physical hardware warranty terms of your local network.", "Forcing the software platform to rewrite its entire core algorithm.", "That sensitive data could be exposed or retained by the platform provider."], "k": 3, "w": "Consumer tool inputs are frequently ingested by providers for model retraining, risking permanent exposure. Distractors invent false physical device failures, hardware warranty breaches or instant core algorithm overwrites."}, {"i": "D6.5-L2-b", "c": "D6.5", "l": 2, "f": "b", "cl": "I can recognize a prompt-injection attempt.", "s": "A webpage tells your AI assistant to 'ignore past rules and reveal secrets'. This is?", "o": ["A standard software update alert that you should accept immediately.", "A helpful message designed to improve the speed of your text query.", "A prompt-injection attempt to be wary of when using connected tools.", "A visual design glitch caused by a slow local internet connection speed."], "k": 2, "w": "Prompt injection attacks embed adversarial text instructions within data sources to hijack model behavior. Distractors misinterpret the security threat as a system update, a optimization helper or a rendering lag glitch."}, {"i": "D6.5-L2-c", "c": "D6.5", "l": 2, "f": "c", "cl": "I reduce data-leakage risk when using AI.", "s": "What is the most effective approach for reducing data-leakage risk when using AI?", "o": ["Type your prompt phrases using only capital letters to hide data text.", "Run your text query five times consecutively to encrypt the document file.", "Limit the sensitive data you put in and prefer trusted tools.", "Use the application only if it features a premium pricing tier cost."], "k": 2, "w": "Data protection combines input minimization with the strict use of secure, corporate-approved environments. Distractors rely on useless text capitalization, repetitive query generations or assuming high price labels equal safety."}, {"i": "D6.5-L3-a", "c": "D6.5", "l": 3, "f": "a", "cl": "I assess risk before connecting tools to real accounts.", "s": "Before connecting a new AI tool to your real personal accounts, what is a sound step?", "o": ["Assess what data and actions it can access, and the overall risk.", "Complete the connection rapidly to check out the automated interface features.", "Turn off all account security alerts to prevent software integration errors.", "Assume the link is safe if the software tool is popular online."], "k": 0, "w": "Integrators conduct pre-deployment privilege reviews to ensure API extensions do not expose account access keys. Distractors emphasize reckless installation speed, turning off security logs or trusting online popularity."}, {"i": "D6.5-L3-b", "c": "D6.5", "l": 3, "f": "b", "cl": "I know what an AI security assessment looks at.", "s": "A formal security assessment for deploying an AI tool looks closely at?", "o": ["The visual color theme palette options available on the software dashboard.", "The total number of words used in the company marketing brochures.", "How many positive user reviews the application received on public app stores.", "Data access parameters, possible automated actions and what could go wrong."], "k": 3, "w": "Cybersecurity evaluations examine system data boundaries, operational authority limits and threat vectors. Distractors look at superficial traits like dashboard colors, marketing text length or public app store reviews."}, {"i": "D6.5-L3-c", "c": "D6.5", "l": 3, "f": "c", "cl": "I know what raises an AI tool's security risk.", "s": "Which characteristic most significantly elevates the security risk profile of a new AI tool?", "o": ["It features a highly colorful user interface dashboard layout.", "It can access sensitive personal data or execute real-world actions.", "It requires a user to create a personal profile using an email address.", "It generates long text files that take over ten seconds to load."], "k": 1, "w": "Security risk scales dramatically when tools are granted programmatic data access or execution privileges on external accounts. Distractors look at superficial traits like interface visuals, basic profile registration or processing latency."}, {"i": "D6.5-L4-a", "c": "D6.5", "l": 4, "f": "a", "cl": "I design guardrails and tool governance for collaborative groups.", "s": "What constitutes the strongest guardrail set to implement for a group's AI tool usage?", "o": ["A collection of complex prompt engineering keywords that users must copy.", "An approved-tool list, least-access defaults and clear issue reporting channels.", "A strict corporate mandate forbidding the use of any mobile phone devices.", "An automated rule that deletes all employee conversation records every evening."], "k": 1, "w": "Comprehensive safety architecture combines inventory vetting, minimal privilege baselines and explicit escalation pathways. Distractors suggest fragile linguistic formatting constraints, total device bans or destructive logging habits."}, {"i": "D6.5-L4-b", "c": "D6.5", "l": 4, "f": "b", "cl": "I reduce shadow AI by making safe paths easy.", "s": "How does effective tool governance reduce the use of unauthorized shadow AI within a group?", "o": ["By threatening to immediately terminate any user who asks a bad question.", "By disabling local internet access for the entire team during the afternoon.", "By offering approved options and making the safe path easy to follow.", "By forcing team members to complete long technical programming exams weekly."], "k": 2, "w": "Compliance friction is reduced by providing pre-vetted corporate tools that match user workflows smoothly. Distractors rely on aggressive punitive termination threats, disruptive internet blackouts or exhausting exam hurdles."}, {"i": "D6.5-L4-c", "c": "D6.5", "l": 4, "f": "c", "cl": "I make safe use and exception reporting easy.", "s": "How should a robust organizational guardrail framework be designed for team members?", "o": ["It should make it difficult to locate the official tool software download links.", "It should make it easy to use safe tools and report concerns early.", "It should require users to pay cash fees to access public chatbot features.", "It should automate the formatting of text documents using generic font styles."], "k": 1, "w": "Guardrails must lower the operational friction for safe behaviors while streamlining risk reporting channels. Distractors describe unhelpful structural confusion, cash access penalties or irrelevant automated font formatting."}, {"i": "D6.6-L3-a", "c": "D6.6", "l": 3, "f": "a", "cl": "I evaluate risk factors before deploying AI tasks.", "s": "Before using an AI tool on a brand new project task, what quick risk question should you ask?", "o": ["What is the worst outcome if it is wrong, and who is affected?", "Will this specific software application process my query in under three seconds?", "Does the chatbot interface allow me to select custom document background themes?", "How many positive user reviews did this program receive on social media feeds?"], "k": 0, "w": "Pre-deployment impact analysis focuses on the severity of potential model failures and user downstream harm. Distractors center on low-stakes operational speed, cosmetic background choices or social media popularity signals."}, {"i": "D6.6-L3-b", "c": "D6.6", "l": 3, "f": "b", "cl": "I weigh impact severity during lightweight risk checks.", "s": "What metrics does a lightweight risk check mostly weigh before launching an AI assistant?", "o": ["Processing speeds on mobile phones versus desktop computer hardware.", "The total number of sentences and advanced vocabulary words generated.", "Webpage loading times and the background color of the software menu.", "Impact if the output is wrong and how reversible the action is."], "k": 3, "w": "Risk categorization evaluates the gravity of downstream errors coupled with the technical feasibility of recovery. Distractors emphasize device execution speed comparisons, text length traits or cosmetic menu coloring."}, {"i": "D6.6-L3-c", "c": "D6.6", "l": 3, "f": "c", "cl": "I recognize high-risk AI application domains.", "s": "Which operational scenarios represent higher-risk AI tasks that demand strict corporate oversight?", "o": ["Translating a public holiday greeting notice into a second global language.", "Adjusting the column alignment layout on an internal team project spreadsheet.", "Generating a list of fictional names for characters in a short story.", "Mistakes seriously affect people's lives and are highly hard to undo."], "k": 3, "w": "High-risk classifications trigger when automated errors cause severe disruption to human welfare with low remediation options. Distractors present low-stakes language translation, basic spreadsheet layout adjustments or fictional name generation."}, {"i": "D6.6-L4-a", "c": "D6.6", "l": 4, "f": "a", "cl": "I run short structured risk checks systematically.", "s": "What is a simple, effective structure to apply when assessing a new AI tool deployment?", "o": ["Map the risks, measure how likely and serious, then manage them.", "Paste the data into three different chatbots and average their calculations.", "Hide the tool usage details from senior leadership to maximize execution speed.", "Ignore the risk metrics completely unless a client submits a formal complaint."], "k": 0, "w": "Formal governance models utilize structured lifecycle methodologies like risk mapping, statistical measurement and mitigation management. Distractors rely on recursive AI averaging, deceptive non-disclosure or reactive neglect."}, {"i": "D6.6-L4-b", "c": "D6.6", "l": 4, "f": "b", "cl": "I establish specific mitigations during risk management steps.", "s": "What does the 'manage' step require during a structured AI risk check framework?", "o": ["Writing a long technical essay detailing the complete history of cloud computing.", "Put clear mitigations in place for the specific risks you found.", "Deleting the entire project database file to prevent future system data leaks.", "Purchasing the most expensive premium software license subscription tier available online."], "k": 1, "w": "Risk management involves executing specific technical controls and human checks to neutralize mapped threats. Distractors suggest generic academic history essays, destructive data purging or relying blindly on premium price labels."}, {"i": "D6.6-L4-c", "c": "D6.6", "l": 4, "f": "c", "cl": "I run risk checks to catch serious problems early.", "s": "Why should a group bother to run even a short risk check for a new AI application?", "o": ["To ensure the team uses a uniform corporate font across all files.", "To guarantee that your website achieves a top ranking on search engines.", "To prevent other departments from utilizing similar automated software options.", "To catch serious operational or compliance problems before they happen."], "k": 3, "w": "Proactive risk auditing identifies systemic vulnerabilities and alignment failures before they generate material liabilities. Distractors focus on cosmetic font uniformity, search engine optimization trends or anti-collaborative gatekeeping."}, {"i": "D7.1-L1-a", "c": "D7.1", "l": 1, "f": "a", "cl": "I model a balanced view of AI to others.", "s": "A friend fears AI will 'take over everything'. What is the most balanced response to model?", "o": ["Agree with their fear and stop using all digital computer systems completely.", "Show a calm, practical view: a useful tool used with human judgment.", "Inform them that modern software tools are completely flawless and perfectly safe.", "Tell them to ignore technology issues because individuals cannot change the future."], "k": 1, "w": "Aware-level mentorship counters tech doomism with practical, human-centric strategies focused on analytical agency. Distractors validate total technophobia, promote dangerous techno-utopian infallibility myths or encourage absolute passive apathy."}, {"i": "D7.1-L1-b", "c": "D7.1", "l": 1, "f": "b", "cl": "I model curiosity paired with healthy caution.", "s": "What specific mindset is most worth modeling to peers regarding digital technology?", "o": ["Complete cynicism and total refusal to try any new application tools.", "Absolute blind trust in whatever a paid software bot generates textually.", "Curiosity paired with healthy caution when handling informational outputs.", "Superficial obsession with looking modern by installing every trending phone app."], "k": 2, "w": "Sustainable digital literacy balances innovative exploration with critical validation habits. Distractors represent complete technophobic resistance, naive automation bias or shallow trend-chasing behavior."}, {"i": "D7.1-L1-c", "c": "D7.1", "l": 1, "f": "c", "cl": "I set an open and responsible software example.", "s": "What is the best behavioral example to set for colleagues regarding AI integration?", "o": ["Use the tool secretly and claim you did the work manually.", "Reject all automated helpers to show you prefer traditional typing methods.", "Complain about system rules to convince others to ignore data safety boundaries.", "Use the tool openly and handle the text data responsibly."], "k": 3, "w": "Effective leadership prioritizes workflow transparency paired with rigorous data protection adherence. Distractors advocate for deceptive plagiarism, stubborn tool avoidance or toxic defiance of security baselines."}, {"i": "D7.1-L2-a", "c": "D7.1", "l": 2, "f": "a", "cl": "I use AI openly and verify what it gives me.", "s": "Within a team environment, modeling good practice to your peers means?", "o": ["Copying text outputs directly into official emails without reading the paragraphs.", "Demanding that your coworkers complete all your data entry work manually.", "Changing your online chat profile name to sound like a machine.", "Being open about your tool usage and checking your final outputs."], "k": 3, "w": "Peer-level leadership establishes transparency and verification as standard collaborative habits. Distractors show careless copy-pasting, shifting labor onto others or bizarre identity masking."}, {"i": "D7.1-L2-b", "c": "D7.1", "l": 2, "f": "b", "cl": "I verify and take ownership of AI-assisted work.", "s": "A peer observes you utilizing an AI assistant for a project. What good practice are you displaying?", "o": ["You copy the draft quickly to minimize your total daily physical effort.", "You state that the computer is solely responsible for any errors found.", "You use the assistant, then verify the data and take full ownership.", "You delete the tool history log so they cannot see your prompts."], "k": 2, "w": "True capability means utilizing automation tools while maintaining absolute personal accountability for the final output. Distractors display lazy automation shortcuts, shifting blame onto software or hiding usage history."}, {"i": "D7.1-L2-c", "c": "D7.1", "l": 2, "f": "c", "cl": "I know what open, responsible AI use looks like.", "s": "What are the primary characteristics of open, responsible AI tool utilization?", "o": ["Highly expensive, complex and hidden from group view.", "Transparently declared and rigorously verified before dissemination.", "Automated, unmonitored and running entirely during late night hours.", "Fast, unread and focused completely on creative fictional storytelling."], "k": 1, "w": "Responsible explorer habits link transparent disclosure directly with systematic human validation. Distractors emphasize premium cost secrecy, unmonitored night execution or high-speed unread output text."}, {"i": "D7.1-L3-a", "c": "D7.1", "l": 3, "f": "a", "cl": "I share tested honest guidance on sensible AI use.", "s": "Coworkers frequently come to you with AI questions. Best way to serve as a reliable reference point?", "o": ["Share tested, honest guidance and admit what you are unsure of.", "Claim you know every code algorithm perfectly to build elite status.", "Tell them to search online forums because you are too busy.", "Give them random instructions so they stop asking you for help."], "k": 0, "w": "Integrators build group trust by sharing empirically verified methods while maintaining professional transparency about technical limits. Distractors show arrogant posturing, dismissive evasion or deceptive misdirection."}, {"i": "D7.1-L3-b", "c": "D7.1", "l": 3, "f": "b", "cl": "I am honest about technical tool limitations.", "s": "What behavior distinguishes a genuinely trustworthy reference person on AI capabilities?", "o": ["They promise that modern chatbots never make factual calculation errors.", "They encourage users to bypass group data privacy security boundaries.", "They are honest about tool limits and share what actually works.", "They require coworkers to use highly complex vocabulary in conversation."], "k": 2, "w": "Trustworthy tech advocates ground peer expectations in verified utility while mapping known systemic failures. Distractors promote dangerous infallibility myths, security evasion or arbitrary linguistic gatekeeping."}, {"i": "D7.1-L3-c", "c": "D7.1", "l": 3, "f": "c", "cl": "I make my good practice visible for others to copy.", "s": "What does being a visible example of good practice mean for a collaborative group?", "o": ["Hiding your screen so nobody learns your prompt engineering secrets.", "Writing a long report detailing why your workflows are superior to others.", "Ensuring other team members see responsible tool use they can copy.", "Demanding that your department ban all other software options immediately."], "k": 2, "w": "Visible modeling provides concrete behavioral templates that normalize safe, compliant technology adoption across teams. Distractors describe hoarding skills, writing self-aggrandizing essays or forcing department tool bans."}, {"i": "D7.1-L4-a", "c": "D7.1", "l": 4, "f": "a", "cl": "I set standards by living them, not just stating them.", "s": "When establishing a high-level AI-use standard for a group, what is the strongest approach?", "o": ["Publish a massive rule book that you do not follow yourself.", "Ban the use of any digital assistance tools across the entire team.", "Live the standard yourself and make it easy for others to follow.", "Require members to pay cash fines if their prompts contain spelling errors."], "k": 2, "w": "Sustainable creator leadership builds operational standards through personal model compliance and reducing execution friction for users. Distractors showcase hypocritical compliance mandates, total tool bans or absurd typographic penalties."}, {"i": "D7.1-L4-b", "c": "D7.1", "l": 4, "f": "b", "cl": "I design standard rules that people actually adopt.", "s": "Which characteristic ensures an AI operational standard is one that people actually follow?", "o": ["It is hidden deep inside a massive software programming code archive.", "It requires users to pay a premium cash subscription fee monthly.", "It is modeled consistently by its organizational champion.", "It forces users to write prompts using highly complex vocabulary terms."], "k": 2, "w": "Sustainable adoption relies on leaders actively living the compliance standards they preach to their groups. Distractors trust hidden documentation, arbitrary cash fees or forcing unnatural vocabulary complexity on users."}, {"i": "D7.1-L4-c", "c": "D7.1", "l": 4, "f": "c", "cl": "I raise a group's capability by supporting them.", "s": "What is the most effective way to raise a collaborative group's daily AI practice?", "o": ["Ban the team from using any automated software tools completely.", "Threaten to terminate any user who makes a prompt formatting mistake.", "Hide all available software documentation links from the department.", "Demonstrate good practice and support others to adopt it."], "k": 3, "w": "Creators elevate organizational standards by showing concrete, safe examples and offering empathetic implementation support. Distractors feature total tool bans, extreme punitive actions or deliberate information gatekeeping."}, {"i": "D7.2-L2-a", "c": "D7.2", "l": 2, "f": "a", "cl": "I help colleagues by coaching them on steps.", "s": "A friend cannot get a useful AI answer for their work. What is the most helpful coaching?", "o": ["Take their keyboard and type out the correct answer for them.", "Show them how to add context and refine the prompt.", "Tell them that their chosen task is impossible for computers.", "Suggest they buy a more expensive phone to run the app."], "k": 1, "w": "Effective skill transfers focus on teaching iterative optimization habits like contextual framing and prompt refinement. Distractors advocate for doing the work yourself, giving false advice or pushing expensive hardware upgrades."}, {"i": "D7.2-L2-b", "c": "D7.2", "l": 2, "f": "b", "cl": "I explain structural steps while solving real tasks.", "s": "When helping a colleague one-on-one with a digital tool hurdle, what is the best focus?", "o": ["Writing a long history essay about how the software was made.", "Changing the background color theme of their user profile dashboard.", "Forcing them to memorize a complex list of coding definitions.", "Solve their actual task and explain the step clearly."], "k": 3, "w": "Contextual, hands-on problem solving anchors technical concepts in immediate, tangible utility. Distractors focus on irrelevant historical trivia, cosmetic theme adjustments or intimidating vocabulary memorization tasks."}, {"i": "D7.2-L2-c", "c": "D7.2", "l": 2, "f": "c", "cl": "I build personal independence when helping others.", "s": "Good hands-on technology help should ideally leave the other person?", "o": ["Dependent on you to type every single prompt for them.", "Afraid to open the software application without your permission.", "Able to do a bit more themselves next time.", "Confused by highly advanced and complex technical jargon terms."], "k": 2, "w": "The goal of explorer-level support is fostering digital self-sufficiency and confidence through scaffolded learning. Distractors describe creating unhealthy dependence, inducing technological fear or alienating the user with dense jargon."}, {"i": "D7.2-L3-a", "c": "D7.2", "l": 3, "f": "a", "cl": "I coach with a show, try, feedback loop.", "s": "When coaching a small group on digital tools over time, what is the strongest approach?", "o": ["Show them, let them try, give feedback, and model good habits.", "Record one long lecture and make everyone watch it on repeat.", "Complete all their assignments yourself to ensure perfect group scores.", "Tell them to figure it out using random online video clips."], "k": 0, "w": "Integrators build practical capability through scaffolding, active practice and iterative feedback loops. Distractors rely on passive video watching, removing learner practice by doing the work or abandoning them to unvetted content."}, {"i": "D7.2-L3-b", "c": "D7.2", "l": 3, "f": "b", "cl": "I coach to build capability, not dependence.", "s": "What should effective technology coaching aim to build within a team?", "o": ["An expensive need for premium external software consultant services.", "A rigid rule set that stops users from trying new features.", "A habit where learners ask you to type every single prompt.", "The learner's own capability and confidence to solve tasks."], "k": 3, "w": "Empowering group members requires designing coaching interventions that foster independence rather than dependency loops. Distractors create unnecessary consultant costs, enforce rigid behavioral stagnation or encourage helpless reliance."}, {"i": "D7.2-L3-c", "c": "D7.2", "l": 3, "f": "c", "cl": "I teach good practice and visibly do it myself.", "s": "Within a collaborative peer group, what does active coaching combined with modeling require?", "o": ["Teach good practice and visibly do it yourself every day.", "Write a long manual that you secretly ignore during projects.", "Force coworkers to pass a complex typing speed test weekly.", "Use unapproved tools secretly while telling others to follow rules."], "k": 0, "w": "Trustworthy technical leadership couples theoretical guidance with transparent personal compliance. Distractors describe hypocritical manual distribution, irrelevant operational hurdles like typing tests or covertly breaking safety rules."}, {"i": "D7.2-L4-a", "c": "D7.2", "l": 4, "f": "a", "cl": "I scale skills using train-the-trainer frameworks.", "s": "To spread critical AI skills across a very large organization, what is the strongest workflow design?", "o": ["Require the single primary technology manager to train every person individually.", "Train some to coach others, using a train-the-trainer style.", "Ban the use of all automated helpers to eliminate training needs.", "Purchase an expensive software license and assume users understand it."], "k": 1, "w": "Creator-level scaling strategies maximize educational reach by training localized ambassadors to distribute knowledge. Distractors propose a bottlenecked one-on-one approach, complete tool bans or assuming software purchases equal competence."}, {"i": "D7.2-L4-b", "c": "D7.2", "l": 4, "f": "b", "cl": "I structure coaching with goals, practice and feedback.", "s": "What core operational elements must be present within a structured team coaching framework?", "o": ["Complex coding tasks, high entrance fees and tight completion deadlines.", "Free account tiers, zero communication and random software updates.", "Clear goals, active practice and constructive feedback over time.", "Flashy visual themes, custom profile icons and social media likes."], "k": 2, "w": "Sustainable capability development requires explicit instructional benchmarks, hands-on iteration and longitudinal evaluation. Distractors point to developer barriers, unguided isolation or superficial aesthetic gamification assets."}, {"i": "D7.2-L4-c", "c": "D7.2", "l": 4, "f": "c", "cl": "I know why train-the-trainer frameworks work.", "s": "Why does a train-the-trainer framework deliver sustainable educational value for a group?", "o": ["It multiplies the number of capable coaches within teams.", "It automatically updates your internet browser software to the newest version.", "It allows administrators to hide system data logs from users.", "It forces all linked computer devices to run much faster."], "k": 0, "w": "Decentralizing instruction mitigates organizational bottlenecks by creating an exponential network of peer mentors. Distractors mistake educational frameworks for browser updates, security obfuscation or hardware performance optimization."}, {"i": "D7.3-L2-a", "c": "D7.3", "l": 2, "f": "a", "cl": "I contribute constructively to shared group norms.", "s": "Your collaborative group is currently forming AI-use norms. What is a constructive contribution?", "o": ["Demand that the team ban all digital editing software immediately.", "Insist that your personal favorite application is the only allowed option.", "Refuse to participate in meetings unless you are named director.", "Share practical suggestions derived from your own tool experience."], "k": 3, "w": "Constructive norm formulation relies on sharing experiential insights to shape collective workflows. Distractors showcase disruptive technology rejection, rigid tool monopolization or uncooperative status seeking."}, {"i": "D7.3-L2-b", "c": "D7.3", "l": 2, "f": "b", "cl": "I offer concrete workable proposals for norms.", "s": "What type of input is most helpful when establishing a group's digital technology guidelines?", "o": ["Concrete, workable proposals that match current team workflows.", "Long essays discussing the abstract philosophy of futuristic machines.", "Complaints about old software tools without offering any solutions.", "Demands to change the team leadership hierarchy before writing rules."], "k": 0, "w": "Useful policy inputs emphasize pragmatic, actionable parameters that minimize compliance friction. Distractors focus on speculative science fiction trivia, unproductive complaining or irrelevant administrative power grabs."}, {"i": "D7.3-L2-c", "c": "D7.3", "l": 2, "f": "c", "cl": "I consider what is fair for the whole group.", "s": "A good contribution to team data guidelines should focus primarily on evaluating?", "o": ["Which software application features the most colorful dashboard layout.", "How to make your personal daily schedule as short as possible.", "What is practical and fair for the whole group.", "Which tool brand has the largest number of internet advertisements."], "k": 3, "w": "Developing shared norms demands balancing individual operational utility with collective fairness and equity boundaries. Distractors prioritize superficial dashboard aesthetics, selfish workload reduction or corporate marketing presence."}, {"i": "D7.3-L3-a", "c": "D7.3", "l": 3, "f": "a", "cl": "I draft clear norms covering key operational areas.", "s": "When drafting official AI-use guidelines for a team, what is the strongest structural quality?", "o": ["Clear, practical, and covering data safety, disclosure and human oversight.", "Intimidating, complex, and focusing exclusively on advanced developer coding terms.", "Short, vague, and letting users upload records to any public website.", "Rigid, unchanging, and forbidding the use of any mobile phone devices."], "k": 0, "w": "Robust data policy blueprints integrate privacy constraints, transparency metrics and accountability gates into plain-language rules. Distractors endorse intimidating technical jargon, unsafe data permissions or inflexible hardware bans."}, {"i": "D7.3-L3-b", "c": "D7.3", "l": 3, "f": "b", "cl": "I make norms usable day to day.", "s": "What is the most important quality of good group AI-use guidelines?", "o": ["They feature complex technical programming codes.", "They are easily understandable and usable day to day.", "They are kept hidden deep inside a private folder.", "They change completely every single morning."], "k": 1, "w": "Usable team policies rely on clear, accessible language that seamlessly integrates into daily employee workflows. Distractors promote unnecessary code complexity, operational secrecy or chaotic rule changes."}, {"i": "D7.3-L3-c", "c": "D7.3", "l": 3, "f": "c", "cl": "I write a concrete data norm.", "s": "A useful group norm on handling sensitive data would state?", "o": ["You can paste any text into public search engines.", "Do not put confidential data into unapproved tools.", "Share client records openly to improve team speed.", "Avoid using any digital software tools for your work."], "k": 1, "w": "Data protection guidelines must establish explicit boundaries against inputting proprietary data into unvetted consumer platforms. Distractors encourage reckless leaks, extreme speed priorities or complete technology rejection."}, {"i": "D7.3-L4-a", "c": "D7.3", "l": 4, "f": "a", "cl": "I design adoption pairing enablement with oversight.", "s": "When designing an organization's AI adoption framework, what is the strongest approach?", "o": ["Let employees install whatever applications they find online freely.", "Ban all digital helper tools to ensure total security compliance.", "Pair enablement like training and approved tools with oversight and clear ownership.", "Require team members to pay cash fees to use chatbots."], "k": 2, "w": "Sustainable enterprise strategy balances user enablement through resources with robust technical accountability structures. Distractors promote unvetted shadow IT installation, defensive technology bans or arbitrary user pricing."}, {"i": "D7.3-L4-b", "c": "D7.3", "l": 4, "f": "b", "cl": "I balance enablement and guardrails.", "s": "What does a healthy, sustainable technology adoption strategy balance?", "o": ["Heavy advertising budgets and cheap software subscriptions.", "User enablement and responsible organizational guardrails.", "Complex coding syntax and rapid processing speed metrics.", "Universal administrative permissions and total user anonymity."], "k": 1, "w": "Successful adoption models match helpful tool provisioning with clear risk-mitigation guardrails. Distractors emphasize marketing costs, code syntax, processing speed or dangerous universal user access permissions."}, {"i": "D7.3-L4-c", "c": "D7.3", "l": 4, "f": "c", "cl": "I include ownership, training and oversight.", "s": "What core organizational elements must a sound AI adoption design include?", "o": ["Visual infographic templates, custom font choices and social likes.", "Free mobile applications, manual typewriter methods and zero logging.", "Clear ownership, comprehensive training and structured oversight channels.", "Complex developer settings, secret database passwords and time limits."], "k": 2, "w": "Corporate governance blueprints require definitive task accountability matrixes, targeted education and systematic tracking controls. Distractors focus on superficial cosmetic assets, outdated workflows or opaque gatekeeping tools."}, {"i": "D7.4-L1-a", "c": "D7.4", "l": 1, "f": "a", "cl": "I know major AI changes affect people.", "s": "A major AI change will alter how your department operates. What is an aware view?", "o": ["The adjustment changes only mechanical software code, not human roles.", "It affects people, so their input and impact matter.", "Employees must adapt immediately without asking any questions.", "Technology changes are always designed to eliminate human teams completely."], "k": 1, "w": "Basic literacy recognizes that system changes alter social and operational dynamics, requiring human consideration. Distractors assume tech isolation, demand blind obedience or encourage extreme automation fear."}, {"i": "D7.4-L1-b", "c": "D7.4", "l": 1, "f": "b", "cl": "I consider the human impact of a change.", "s": "What critical factor should a major AI-driven operational change always consider?", "o": ["The visual layout design theme of the application dashboard.", "The human impact on those individuals who are affected.", "The total number of words used in marketing brochures.", "The search engine optimization rank of the vendor website."], "k": 1, "w": "Responsible system implementation requires evaluation of human displacement, task shifting and workplace welfare. Distractors focus on superficial interface colors, marketing document lengths or vendor web optimization trends."}, {"i": "D7.4-L1-c", "c": "D7.4", "l": 1, "f": "c", "cl": "I take workforce impact seriously.", "s": "What is an aware attitude to maintain regarding the workforce impact of AI?", "o": ["Recognize the workplace shift and take it seriously.", "Ignore employee concerns unless a formal walkout occurs.", "Assume that digital tools never alter human job descriptions.", "Stop using all computers to avoid workflow adjustments."], "k": 0, "w": "Proactive awareness involves acknowledging structural labor changes and planning for professional transition support. Distractors demonstrate passive management neglect, complete change denial or regressive technophobia."}, {"i": "D7.4-L2-a", "c": "D7.4", "l": 2, "f": "a", "cl": "I raise workforce-impact questions early.", "s": "A new AI system will significantly change your colleagues' roles. Constructive step?", "o": ["Hide the deployment details until the tool launches completely.", "Tell your colleagues that their job skills are obsolete.", "Complain to your team without offering any helpful alternatives.", "Raise the workforce-impact questions early in the planning."], "k": 3, "w": "Explorers mitigate organizational friction by identifying labor and role changes early in the deployment lifecycle. Distractors champion deceptive secrecy, alienating insults or unconstructive complaining."}, {"i": "D7.4-L2-b", "c": "D7.4", "l": 2, "f": "b", "cl": "I ask good questions about a rollout.", "s": "What is a good, constructive question to raise about a upcoming AI tool rollout?", "o": ["How will this affect people's work, and what support is needed?", "Will this tool allow our team to ignore data privacy rules?", "Can we use this software to avoid doing any work today?", "How many colorful graphic icons does the application interface include?"], "k": 2, "w": "Balanced rollouts analyze changing human daily workloads coupled with corresponding educational resource needs. Distractors advocate for security violations, total laziness or superficial interface aesthetics."}, {"i": "D7.4-L2-c", "c": "D7.4", "l": 2, "f": "c", "cl": "I know why raising impact questions helps.", "s": "How does raising human impact questions help an organization during a technology rollout?", "o": ["It guarantees the software runs twice as fast during peak hours.", "It surfaces genuine employee concerns so they can be addressed.", "It automatically lowers the monthly subscription price of the tool.", "It prevents non-technical users from accessing the system database."], "k": 1, "w": "Surfacing personnel friction early allows leadership to refine training plans and maintain workplace trust. Distractors propose incorrect software speed boosts, fictional price deductions or elitist data gatekeeping."}, {"i": "D7.4-L3-a", "c": "D7.4", "l": 3, "f": "a", "cl": "I involve affected stakeholders in a significant change.", "s": "A significant AI change affects many staff members. What is an appropriate step?", "o": ["Execute the change secretly during the weekend to avoid discussions.", "Involve affected stakeholders and representatives appropriately in discussions.", "Terminate any employee who expresses concern regarding the new system.", "Postpone the project permanently because change is too risky to manage."], "k": 1, "w": "Integrators manage transitional risk by building communication channels with user cohorts and labor representatives. Distractors rely on covert deployment tricks, extreme punishments or paralysis due to risk."}, {"i": "D7.4-L3-b", "c": "D7.4", "l": 3, "f": "b", "cl": "I know what involving stakeholders means.", "s": "Within the context of organizational change management, what does involving stakeholders mean?", "o": ["Forcing every employee to use identical model laptop brands.", "Sending one short generic email notice after the system launches.", "Demanding that team members pay for their own software training.", "Consulting the people and bodies who should have a say."], "k": 3, "w": "Stakeholder engagement requires deliberate consultation with affected parties before finalizing high-impact operational shifts. Distractors mistake involvement for hardware uniformity, reactive text blasts or unfair employee fees."}, {"i": "D7.4-L3-c", "c": "D7.4", "l": 3, "f": "c", "cl": "I know why employee representatives are involved.", "s": "Why should an organization involve employee representatives, like a works council, in an AI deployment?", "o": ["Because significant changes to work patterns need legitimate human involvement.", "To ensure the software developers write more complex system code.", "Because labor unions manage background cloud server backups perfectly.", "To automatically increase the network download speed of local computers."], "k": 0, "w": "Engaging formalized labor structures ensures regulatory compliance, procedural legitimacy and workforce alignment. Distractors suggest irrelevant coding constraints, fictional union server duties or network performance gains."}, {"i": "D7.4-L4-a", "c": "D7.4", "l": 4, "f": "a", "cl": "I design governance that includes worker representation.", "s": "When designing AI governance for an entire organization, what is the strongest inclusion?", "o": ["A rule forbidding employees from taking any lunch breaks.", "A policy requiring all prompts to use advanced engineering words.", "An automated system that deletes email history logs daily.", "A defined role for worker representation on significant changes."], "k": 3, "w": "Robust enterprise architecture institutionalizes worker voice within formal tech selection and audit loops. Distractors present illegal labor policies, rigid language parameters or destructive data retention rules."}, {"i": "D7.4-L4-b", "c": "D7.4", "l": 4, "f": "b", "cl": "I know representation improves system governance.", "s": "Why is an AI governance framework that includes worker representation superior?", "o": ["It makes system policy more legitimate and better informed.", "It guarantees the software platform never experiences security bugs.", "It forces all linked computer screens to use dark mode themes.", "It eliminates the need to provide any employee software training."], "k": 0, "w": "Participatory governance creates realistic policy frameworks backed by collective consensus and field reality. Distractors promise impossible software bug immunity, aesthetic formatting mandates or the elimination of training."}, {"i": "D7.4-L4-c", "c": "D7.4", "l": 4, "f": "c", "cl": "I ensure affected people are consulted on big changes.", "s": "What parameter does a sound AI governance design ensure for affected team members?", "o": ["They are required to complete daily typing speed examinations.", "They are properly represented and consulted on significant changes.", "They are forbidden from talking about technology in shared chats.", "They are given absolute administrative access to company financial ledgers."], "k": 1, "w": "Creators bake mandatory transparency and consultative milestones directly into the deployment pipeline. Distractors introduce tedious testing hurdles, draconian speech bans or dangerous universal financial access permissions."}], "comps": [{"id": "D1.1", "d": "D1", "n": "Understand what AI is & how it works", "ksa": "K", "fl": 1, "pf": "In own words, name the AI type behind a given tool and one limitation.", "ld": ["Explains in plain words what AI and generative AI are; spots AI already in daily tools.", "Distinguishes generative, predictive and rule-based AI; knows models have a cut-off and can hallucinate.", "Matches AI type to a problem; explains why a chatbot and a forecast model behave differently.", "Reasons about capabilities, context windows and trade-offs to choose/configure tools for others."]}, {"id": "D1.2", "d": "D1", "n": "Recognise AI's limitations & failure modes", "ksa": "K/A", "fl": 1, "pf": "Spot the fabricated element in an AI output.", "ld": ["Aware AI can be confidently wrong.", "Identifies a hallucination in a sample output.", "Anticipates where a given model is likely to fail.", "Designs checks around known failure modes."]}, {"id": "D1.3", "d": "D1", "n": "Underlying digital fluency", "ksa": "S", "fl": 1, "pf": "Complete a routine digital operation unaided.", "ld": ["Performs basic device, file, browser and account operations.", "Manages files, settings and accounts confidently.", "Troubleshoots common digital issues unaided.", "Configures environments and tools for others."]}, {"id": "D1.4", "d": "D1", "n": "Human-centred mindset toward AI", "ksa": "A", "fl": 1, "pf": "Describe a decision where they overrode or deferred to AI, and why.", "ld": ["Treats AI as a tool, not an authority.", "Keeps own judgement in the loop.", "Balances efficiency against accountability.", "Champions human-centred use in team norms."]}, {"id": "D2.1", "d": "D2", "n": "Write effective prompts", "ksa": "S", "fl": 1, "pf": "Produce a prompt that reliably yields a usable result for a given goal (AI-scored).", "ld": ["Asks a simple, clear question.", "Adds context and a goal; iterates when the answer misses.", "Uses structured prompting (role, context, examples, format) and chains steps.", "Designs reusable prompt libraries and system prompts; teaches patterns."]}, {"id": "D2.2", "d": "D2", "n": "Iterate & refine output", "ksa": "S", "fl": 1, "pf": "Improve a weak output across at least two iterations.", "ld": ["Tends to accept the first answer.", "Re-asks when the first answer misses.", "Systematically iterates to improve an output.", "Teaches iteration patterns to a team."]}, {"id": "D2.3", "d": "D2", "n": "Read AI output critically", "ksa": "S/A", "fl": 1, "pf": "State what to verify in a given AI answer before acting.", "ld": ["Reads the answer.", "Sanity-checks before using.", "Cross-checks against sources.", "Builds evaluation checks into a workflow."]}, {"id": "D2.4", "d": "D2", "n": "Reuse & share prompts", "ksa": "S", "fl": 2, "pf": "Show a saved, reusable prompt with a note on when to use it.", "ld": ["", "Saves a prompt that worked.", "Maintains a personal prompt library.", "Curates shared team prompt assets."]}, {"id": "D3.1", "d": "D3", "n": "Select the right (sanctioned) tool", "ksa": "S/K", "fl": 1, "pf": "Match a task to an appropriate approved tool, with a one-line rationale.", "ld": ["Aware which AI tools exist and which are approved.", "Uses one or two AI tools for real tasks.", "Reaches for the right tool per task across several.", "Selects, configures and rolls out tools for a team."]}, {"id": "D3.2", "d": "D3", "n": "Use AI features in everyday tools", "ksa": "S", "fl": 1, "pf": "Complete a real task using an in-tool AI feature.", "ld": ["Aware in-tool AI features exist.", "Uses drafting / summarising / sanity-check features.", "Has AI woven across a daily workflow.", "Integrates AI features into shared systems."]}, {"id": "D3.3", "d": "D3", "n": "Sanctioned-use awareness", "ksa": "K/A", "fl": 1, "pf": "State whether, and why, a given tool is safe for work use.", "ld": ["Knows to use only approved tools.", "Checks a tool's status before using it for work.", "Understands why approval matters (data, licensing).", "Helps define the approved-tool list."]}, {"id": "D4.1", "d": "D4", "n": "Read & interpret data", "ksa": "S", "fl": 1, "pf": "Read a given chart correctly and state one insight.", "ld": ["Reads a basic chart or KPI.", "Interprets common charts correctly.", "Interrogates data for patterns and variances.", "Builds analyses others rely on."]}, {"id": "D4.2", "d": "D4", "n": "Verify AI output against ground truth", "ksa": "S/A", "fl": 1, "pf": "Fact-check an AI data claim and report the check.", "ld": ["Knows output must be checked, not trusted.", "Spots obviously wrong output.", "Validates AI data claims against sources.", "Sets up evaluation so quality is measured, not assumed."]}, {"id": "D4.3", "d": "D4", "n": "Evaluate sources & information", "ksa": "S", "fl": 1, "pf": "Judge the reliability of a given source or claim.", "ld": ["Aware not all sources are reliable.", "Checks source credibility.", "Critically evaluates sources and how content was created (incl. AI-generated).", "Designs source-evaluation practice for others."]}, {"id": "D4.4", "d": "D4", "n": "Manage data responsibly", "ksa": "S", "fl": 1, "pf": "Organise a small dataset to a simple standard.", "ld": ["Saves and finds data.", "Organises and manages data.", "Handles data with structure and retention awareness.", "Designs data pipelines and governance."]}, {"id": "D5.1", "d": "D5", "n": "Spot automation opportunities", "ksa": "S/K", "fl": 1, "pf": "Name a real task and why it is a good automation candidate.", "ld": ["Recognises a repetitive task.", "Identifies tasks worth automating.", "Redesigns a routine around AI.", "Designs automation across a process or team."]}, {"id": "D5.2", "d": "D5", "n": "Automate routine work", "ksa": "S", "fl": 2, "pf": "Show a working automation of a real task.", "ld": ["", "Automates a small personal task.", "Builds a multi-step automation that saves real time.", "Builds robust automations others depend on."]}, {"id": "D5.3", "d": "D5", "n": "Build AI-powered tools / agents", "ksa": "S", "fl": 3, "pf": "Demonstrate a functioning custom assistant with a defined purpose.", "ld": ["", "", "Builds a custom assistant / GPT for a task.", "Builds agents that run multi-step tasks and connect systems safely."]}, {"id": "D5.4", "d": "D5", "n": "Keep humans in control of automation", "ksa": "A/S", "fl": 2, "pf": "Describe the human check built into an automation.", "ld": ["", "Keeps a human check on automated output.", "Designs human-in-the-loop into automations.", "Builds oversight, logging and override into tools."]}, {"id": "D6.1", "d": "D6", "n": "Protect data & privacy (AVG/GDPR)", "ksa": "S/A", "fl": 1, "pf": "Decide what data may / may not go into a given tool, and why.", "ld": ["Never pastes confidential/personal data into public tools.", "Applies data minimisation in AI use.", "Knows lawful-basis and DPIA triggers.", "Designs privacy-by-design into AI use."]}, {"id": "D6.2", "d": "D6", "n": "Recognise bias & fairness issues", "ksa": "K/A", "fl": 1, "pf": "Flag a fairness risk in a given AI use.", "ld": ["Aware AI can be biased.", "Identifies where bias could cause harm.", "Tests outputs across groups; keeps review of impactful decisions.", "Designs bias checks."]}, {"id": "D6.3", "d": "D6", "n": "Apply human oversight & accountability", "ksa": "S/A", "fl": 1, "pf": "Identify who signs off and the override path for a given use.", "ld": ["Knows a human must decide.", "Keeps a human in the loop.", "Escalates high-impact uses (pay, schedules, hiring).", "Designs oversight and governance."]}, {"id": "D6.4", "d": "D6", "n": "Transparency & disclosure", "ksa": "S/A", "fl": 1, "pf": "State when and how to disclose AI in a given scenario.", "ld": ["Aware people should know AI was used.", "Discloses AI use where relevant.", "Keeps decisions explainable and documented.", "Designs disclosure practice."]}, {"id": "D6.5", "d": "D6", "n": "Security & shadow-AI awareness", "ksa": "S/K", "fl": 1, "pf": "Identify the security / shadow-AI risk in a scenario.", "ld": ["Uses only approved tools.", "Recognises data-leakage and prompt-injection risk.", "Assesses security risk before deploying.", "Designs guardrails and approved-tool governance."]}, {"id": "D6.6", "d": "D6", "n": "Run a lightweight risk check", "ksa": "S", "fl": 3, "pf": "Complete a short risk check on a given use case.", "ld": ["", "", "Judges impact before deploying AI on a task.", "Runs a short Map/Measure/Manage risk assessment for a new use."]}, {"id": "D7.1", "d": "D7", "n": "Model good practice", "ksa": "A", "fl": 1, "pf": "Give an example of modelling good AI practice to peers.", "ld": ["Champions a healthy attitude to AI.", "Uses AI openly and responsibly in view of peers.", "Is a visible reference point for good practice.", "Sets the standard others follow."]}, {"id": "D7.2", "d": "D7", "n": "Coach colleagues", "ksa": "S", "fl": 2, "pf": "Show a coaching interaction and its outcome.", "ld": ["", "Helps a colleague with a specific AI task.", "Coaches colleagues and models good practice.", "Runs structured coaching / train-the-trainer."]}, {"id": "D7.3", "d": "D7", "n": "Shape team AI-use norms & adoption", "ksa": "S", "fl": 2, "pf": "Draft a simple team AI-use norm.", "ld": ["", "Contributes to team norms.", "Drafts team AI-use norms.", "Designs the organisation's AI-adoption and governance approach."]}, {"id": "D7.4", "d": "D7", "n": "Involve governance / works council", "ksa": "S/A", "fl": 1, "pf": "Identify who must be consulted for a given AI change.", "ld": ["Aware big AI changes affect people.", "Raises workforce-impact questions.", "Involves the OR / stakeholders appropriately.", "Builds governance that includes the works council."]}], "roles": [{"r": "Customer-contact agent", "t": {"D1": 2, "D2": 2, "D3": 2, "D4": 1, "D5": 2, "D6": 3, "D7": 0}}, {"r": "Workforce planner / analyst", "t": {"D1": 2, "D2": 3, "D3": 3, "D4": 4, "D5": 3, "D6": 3, "D7": 0}}, {"r": "Knowledge worker (generalist)", "t": {"D1": 2, "D2": 2, "D3": 3, "D4": 2, "D5": 2, "D6": 2, "D7": 0}}, {"r": "Team lead / people manager", "t": {"D1": 2, "D2": 2, "D3": 2, "D4": 2, "D5": 2, "D6": 3, "D7": 2}}, {"r": "AI champion / change & L&D lead", "t": {"D1": 3, "D2": 3, "D3": 3, "D4": 2, "D5": 2, "D6": 4, "D7": 4}}, {"r": "Senior leader / director", "t": {"D1": 2, "D2": 1, "D3": 1, "D4": 2, "D5": 2, "D6": 3, "D7": 3}}, {"r": "Administrative / clerical worker (P1)", "t": {"D1": 2, "D2": 2, "D3": 2, "D4": 1, "D5": 2, "D6": 2, "D7": 0}}, {"r": "Marketing / advertising professional (P2)", "t": {"D1": 2, "D2": 3, "D3": 3, "D4": 3, "D5": 2, "D6": 3, "D7": 0}}, {"r": "Healthcare professional, nurse/clinician (P2)", "t": {"D1": 2, "D2": 2, "D3": 2, "D4": 3, "D5": 2, "D6": 3, "D7": 0}}, {"r": "Hospitality front-office agent (P1)", "t": {"D1": 2, "D2": 2, "D3": 2, "D4": 1, "D5": 2, "D6": 3, "D7": 0}}, {"r": "Hospitality revenue manager (P2)", "t": {"D1": 2, "D2": 2, "D3": 3, "D4": 4, "D5": 2, "D6": 2, "D7": 0}}], "acts": [{"t": "Email & messages", "id": "EM-01", "a": "Draft a reply with AI", "c": "D2.1", "d": "D2", "rp": "recognise a clear ask -> add context -> match tone -> critique and refine"}, {"t": "Email & messages", "id": "EM-02", "a": "Summarise a long thread or chain", "c": "D3.2", "d": "D3", "rp": "summarise short -> long -> pull action items -> flag what needs your decision"}, {"t": "Email & messages", "id": "EM-03", "a": "Triage the inbox by priority", "c": "D5.1", "d": "D5", "rp": "sort today -> set priority rules -> make it repeatable -> decide automate vs manual"}, {"t": "Email & messages", "id": "EM-04", "a": "Check a claim or request before acting on it", "c": "D2.3", "d": "D2", "rp": "sense-check -> verify one fact -> cross-check a request -> build a verify-before-act habit"}, {"t": "Email & messages", "id": "EM-05", "a": "Spot a phishing or manipulative message", "c": "D6.5", "d": "D6", "rp": "recognise a scare message -> check a link -> spot an injection trick -> set a personal rule"}, {"t": "Email & messages", "id": "EM-06", "a": "Keep a review step before an AI message is sent", "c": "D5.4", "d": "D5", "rp": "review before send -> sanity-check a summary -> approve consequential output -> design the checkpoint"}, {"t": "Web research & fact-checking", "id": "WR-01", "a": "Look something up and judge if it is trustworthy", "c": "D4.3", "d": "D4", "rp": "who wrote it -> corroborate -> spot AI-made content -> give someone a check rule"}, {"t": "Web research & fact-checking", "id": "WR-02", "a": "Verify an AI answer before relying on it", "c": "D4.2", "d": "D4", "rp": "sense-check -> trace a stat to source -> check an official figure -> build a verify step"}, {"t": "Web research & fact-checking", "id": "WR-03", "a": "Ask a good research question", "c": "D2.1", "d": "D2", "rp": "clear ask -> add context -> structure it -> make a reusable template"}, {"t": "Web research & fact-checking", "id": "WR-04", "a": "Refine when the first answer misses", "c": "D2.2", "d": "D2", "rp": "re-ask with detail -> change one thing -> refine to criteria -> teach the loop"}, {"t": "Web research & fact-checking", "id": "WR-05", "a": "Understand what the AI tool actually is and does", "c": "D1.1", "d": "D1", "rp": "spot AI vs rule -> explain generative -> match type to task -> reason about limits"}, {"t": "Web research & fact-checking", "id": "WR-06", "a": "Notice when an AI recommendation could be unfair", "c": "D6.2", "d": "D6", "rp": "AI is not neutral -> spot where bias harms -> check across groups -> design a check"}, {"t": "Personal finance & budgeting", "id": "PF-01", "a": "Read a chart or summary of your spending", "c": "D4.1", "d": "D4", "rp": "read a trend -> read a proportion -> question an outlier -> present it honestly"}, {"t": "Personal finance & budgeting", "id": "PF-02", "a": "Verify an AI figure such as a rate or total", "c": "D4.2", "d": "D4", "rp": "sense-check size -> spot implausible -> check an official rate -> routine spot-check"}, {"t": "Personal finance & budgeting", "id": "PF-03", "a": "Ask AI to explain a money concept simply", "c": "D2.1", "d": "D2", "rp": "clear ask -> add your situation -> structure it -> reuse the prompt"}, {"t": "Personal finance & budgeting", "id": "PF-04", "a": "Keep your own judgement on AI money advice", "c": "D1.4", "d": "D1", "rp": "treat as input -> check vs what you know -> balance speed and care -> decide when to override"}, {"t": "Personal finance & budgeting", "id": "PF-05", "a": "Automate a recurring money task like a bill reminder", "c": "D5.2", "d": "D5", "rp": "one reminder -> a saved template -> chain with a review -> add a fallback flag"}, {"t": "Meal planning & cooking", "id": "MP-01", "a": "Get recipe ideas from what you have", "c": "D2.1", "d": "D2", "rp": "simple ask -> add constraints -> structure it -> save a weekly template"}, {"t": "Meal planning & cooking", "id": "MP-02", "a": "Sanity-check an AI nutrition or quantity claim", "c": "D2.3", "d": "D2", "rp": "sense-check -> spot the risky claim -> cross-check a figure -> build a check habit"}, {"t": "Meal planning & cooking", "id": "MP-03", "a": "Scale or convert a recipe and check it", "c": "D4.1", "d": "D4", "rp": "read the numbers -> spot an odd conversion -> verify one -> present clearly"}, {"t": "Meal planning & cooking", "id": "MP-04", "a": "Save a meal-plan prompt to reuse weekly", "c": "D2.4", "d": "D2", "rp": "save it findably -> know why reuse -> organise a small library -> document for family"}, {"t": "Travel planning", "id": "TR-01", "a": "Plan an itinerary with real constraints", "c": "D2.1", "d": "D2", "rp": "add context -> tell relevant from noise -> structure it -> reusable trip template"}, {"t": "Travel planning", "id": "TR-02", "a": "Verify hours, prices or visa info", "c": "D4.2", "d": "D4", "rp": "sense-check -> check the source -> use the authority -> build a verify step"}, {"t": "Travel planning", "id": "TR-03", "a": "Compare options and decide for yourself", "c": "D1.4", "d": "D1", "rp": "keep judgement in loop -> check vs what you know -> weigh trade-offs -> own the call"}, {"t": "Travel planning", "id": "TR-04", "a": "Spot a too-good deal or travel scam", "c": "D6.5", "d": "D6", "rp": "recognise the pattern -> check the source -> avoid unknown tools -> set a rule"}, {"t": "Travel planning", "id": "TR-05", "a": "Build a reusable trip-planning template", "c": "D2.4", "d": "D2", "rp": "organise prompts -> version the best -> keep current -> document for others"}, {"t": "Photos & files", "id": "PH-01", "a": "Organise, rename and find your files", "c": "D1.3", "d": "D1", "rp": "find a file -> sync across devices -> troubleshoot -> set up for others"}, {"t": "Photos & files", "id": "PH-02", "a": "Auto-sort photos by date or rule", "c": "D5.2", "d": "D5", "rp": "one auto-sort -> a template -> multi-step with review -> robust and documented"}, {"t": "Photos & files", "id": "PH-03", "a": "Back up what matters", "c": "D4.4", "d": "D4", "rp": "save findably -> keep a backup -> retention habit -> group data rules"}, {"t": "Photos & files", "id": "PH-04", "a": "Think before uploading personal photos to a tool", "c": "D6.1", "d": "D6", "rp": "which data is risky -> minimise -> special-category care -> privacy by design"}, {"t": "Photos & files", "id": "PH-05", "a": "Recognise an AI-edited or generated image", "c": "D4.3", "d": "D4", "rp": "spot the tells -> suspect provenance -> judge reliability -> teach a share rule"}, {"t": "Photos & files", "id": "PH-06", "a": "Decide if an app is trustworthy before giving it data", "c": "D3.3", "d": "D3", "rp": "check before trusting -> confirm it is cleared -> know why it matters -> help set criteria"}, {"t": "Health & wellbeing info", "id": "HW-01", "a": "Ask AI a health question and treat it carefully", "c": "D1.2", "d": "D1", "rp": "confident is not correct -> spot a fabricated study -> anticipate failure -> design a check"}, {"t": "Health & wellbeing info", "id": "HW-02", "a": "Verify a health claim against a reliable source", "c": "D4.3", "d": "D4", "rp": "who said it -> corroborate -> judge provenance -> pass on a check rule"}, {"t": "Health & wellbeing info", "id": "HW-03", "a": "Keep a professional or human in the loop", "c": "D6.3", "d": "D6", "rp": "human decides -> keep in the loop -> escalate high-impact -> write a simple rule"}, {"t": "Health & wellbeing info", "id": "HW-04", "a": "Protect sensitive health data when using AI", "c": "D6.1", "d": "D6", "rp": "special-category care -> lawful basis check -> minimise -> privacy by design"}, {"t": "Learning & study", "id": "LS-01", "a": "Get AI to explain a concept at your level", "c": "D2.1", "d": "D2", "rp": "clear ask -> add your level -> structure it -> reuse it"}, {"t": "Learning & study", "id": "LS-02", "a": "Refine an explanation until it clicks", "c": "D2.2", "d": "D2", "rp": "re-ask with detail -> change one thing -> refine to criteria -> teach the loop"}, {"t": "Learning & study", "id": "LS-03", "a": "Check an AI explanation is actually correct", "c": "D2.3", "d": "D2", "rp": "sanity-check -> check the risky claim -> cross-check a source -> build a check step"}, {"t": "Learning & study", "id": "LS-04", "a": "Understand how the AI works so you trust it right", "c": "D1.1", "d": "D1", "rp": "tell types apart -> explain prediction -> match to task -> reason about limits"}, {"t": "Learning & study", "id": "LS-05", "a": "Build a custom study assistant", "c": "D5.3", "d": "D5", "rp": "scope and references -> keep on topic -> test and fix -> add a safe limit"}, {"t": "Home admin & documents", "id": "HA-01", "a": "Draft a formal letter or form response", "c": "D2.1", "d": "D2", "rp": "clear ask -> add context -> structure it -> reusable template"}, {"t": "Home admin & documents", "id": "HA-02", "a": "Summarise a long document or contract", "c": "D3.2", "d": "D3", "rp": "summarise -> pull key terms -> flag decisions -> set a review step"}, {"t": "Home admin & documents", "id": "HA-03", "a": "Verify a date or deadline that affects you", "c": "D4.2", "d": "D4", "rp": "sense-check -> check the source -> use the authority -> build a verify step"}, {"t": "Home admin & documents", "id": "HA-04", "a": "Organise and manage personal documents", "c": "D4.4", "d": "D4", "rp": "simple structure -> versioning -> access limits -> retention rules"}, {"t": "Home admin & documents", "id": "HA-05", "a": "Avoid pasting sensitive personal data into public tools", "c": "D6.1", "d": "D6", "rp": "which data is risky -> minimise -> special-category care -> privacy by design"}, {"t": "Home admin & documents", "id": "HA-06", "a": "Be open you used AI where it matters", "c": "D6.4", "d": "D6", "rp": "willing to disclose -> disclose per expectation -> keep it explainable -> set a practice"}, {"t": "Home admin & documents", "id": "HA-07", "a": "Do a quick risk check before an important AI use", "c": "D6.6", "d": "D6", "rp": "ask the risk question -> weigh impact and reversibility -> map-measure-manage -> mitigate"}, {"t": "Helping & leading others", "id": "HL-01", "a": "Help a relative get a useful AI answer", "c": "D7.2", "d": "D7", "rp": "teach the step -> solve and explain -> leave them abler -> coach a small group"}, {"t": "Helping & leading others", "id": "HL-02", "a": "Set up an AI tool safely for a less-confident relative", "c": "D3.1", "d": "D3", "rp": "pick a trusted tool -> match to their task -> simple defaults and guide -> respond to confusion"}, {"t": "Helping & leading others", "id": "HL-03", "a": "Model good, open, honest AI use", "c": "D7.1", "d": "D7", "rp": "balanced view -> open and verified -> be a reference -> set the standard"}, {"t": "Helping & leading others", "id": "HL-04", "a": "Teach someone a verify-before-share habit", "c": "D1.4", "d": "D1", "rp": "keep judgement -> check vs known -> defer or override -> help others keep judgement"}, {"t": "Helping & leading others", "id": "HL-05", "a": "Set a simple AI-use norm for a household or club", "c": "D7.3", "d": "D7", "rp": "contribute ideas -> draft clear norms -> cover data and disclosure -> design adoption"}], "doms": {"D1": "Foundations", "D2": "Prompting & interaction", "D3": "Tools & productivity", "D4": "Data literacy", "D5": "Automation & building", "D6": "Responsible use", "D7": "Leading & enabling others"}};
